(window.GIM_TP=window.GIM_TP||{})["Z.Vayigash.0"]={"from":0,"a":[[[],[],[]],[["וַיִּגַּשׁ אֵלָיו יְהוּדָה וְגו', רִבִּי אֶלְעָזָר פָּתַח, (ישעיהו ס״ג:ט״ז) כִּי אַתָּה אָבִינוּ כִּי אַבְרָהָם לא יָדְעָנוּ וְיִשְׂרָאֵל לא יַכִּירֶנּוּ אַתָּה ה' אָבִינוּ גוֹאֲלֵנוּ מֵעוֹלָם שְׁמֶךָ. הַאי קְרָא אוּקְמוּהָ, אֲבָל תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, כָּל יוֹמָא וְיוֹמָא, עָבִיד עֲבִידְתָּא כְּדְקָא חָזֵי. בְּכָל יוֹמָא וְיוֹמָא כְּמָה דְאִצְטְרִיךְ. כֵּיוָן דְּאָתָא יוֹמָא שְׁתִיתָאָה וְאִצְטְרִיךְ לְמִבְרִי אָדָם, אָתַת אוֹרַיְיתָא קַמֵּיהּ. אָמְרָה (קמי קודשא בריך הוא). הַאי אָדָם דְּאַתְּ בָּעֵי לְמִבְרֵי, זַמִּין הוּא לְאַרְגָּזָא קַמָּךְ. אִלְמָלֵא לָא תַאֲרִיךְ רוּגְזָא, טַב לֵיהּ דְּלָא יִתְבְּרֵי. אָמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, וְכִי לְמַגָּנָא אִתְקְרֵינָא אֶרֶךְ אַפַּיִם.","אֶלָּא, כֹּלָּא בְּאוֹרַיְיתָא אִתְבְּרֵי, וְכֹלָּא בְּאוֹרַיְיתָא אִשְׁתַּכְלַל. בְּגִין דְּעַד לָא בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, אַתְיָין כָּל אַתְוָון קַמֵּיהּ, וְעָאלוּ כָּל חַד וְחַד לְמַפְרֵעַ.","עָאֳלַת תי\"ו. אָמְרָה קַמֵּיהּ, רְעוּתָךְ לְמִבְרֵי בִּי עַלְמָא, אָמַר לַהּ לָאו, דְּבָךְ זְמִינִין כַּמָּה צַדִּיקַיָא לְמֵימַת, דִּכְתִיב, (יחזקאל ט׳:ד׳) וְהִתְוֵיתָ תָּיו עַל מִצְחוֹת הָאֲנָשִׁים וְגו'. וְתָנִינָן, דִּכְתִיב וּמִמִּקְדָּשִׁי תָּחֵלּוּ. אַל תִּקְרֵי מִמִּקְדָּשִׁי, אֶלָּא מִמְקוּדָּשַׁי. וּבְגִין כָּךְ עַלְמָא לָא יִתְבְּרֵי בָּךְ.","עָאלוּ תְּלַת אַתְוָון, שִׁי\"ן, קוּ\"ף, רֵי\"שׁ, כָּל חַד וְחַד בִּלְחוֹדוֹי. אָמַר לְהּוּ קוּדְשָׁא בְּרִיךְ הוּא, לָאו אַתּוּן כְּדַאי לְמִבְרֵי בְּכוּ עַלְמָא, דְּהָא אַתּוּן אַתְוָון דְּאִתְקְרֵי בְּכוּ שֶׁקֶר, וְשֶׁקֶר לָאו אִיהוּ כְּדַאי לְמֵיקַם קַמַּאי, וְהָא אוּקְמוּהָ.","וְעָלוּ פּ\"א צד\"י, וְכֵן כֻּלְּהוּ, עַד דְּמָטוּ אַתְוָון לְאָת כ\"ף. כֵּיוָן דְּנָחַת כּ\"ף מֵעַל כִּתְרָא, אִזְדַּעְזָעוּ עִלָּאֵי וְתַתָּאֵי כו', עַד דְּאִתְקַיֵּים כְּלָא בְּאָת בֵּי\"ת, דְּאִיהוּ סִימָן בְּרָכָה, וּבֵיהּ אִשְׁתָּכְלַל עַלְמָא וְאִתְבְּרֵי.","וְאִי תֵימָא, דְּאל\"ף אִיהוּ רֵישָׁא דְּכָל (אינון) אַתְוָון, (לאו) יָאוֹת אִיהוּ. אֶלָּא בְּגִין דְּאִתְקְרֵי בֵּיהּ אָרוּר (ובגין דאתקרי בה ארור). וּבְגִין דָּא לָא אִתְבְּרֵי בֵּיהּ עַלְמָא, אַף עַל גַּב דְּאל\"ף אִיהוּ אָת דְּרָזָא עִלָּאָה. בְּגִין דְּלָא לְמֵיהַב דּוּכְתָּא לְסִטְרָא אָחֳרָא דְּאִקְרֵי אָרוּר, לָא אִתְבְּרֵי בֵּיהּ עַלְמָא. וְאִשְׁתַּכְלַל בְּבֵי\"ת עַלְמָא, וּבֵיהּ אִתְבְּרֵי.","תָּא חֲזֵי, כִּי אַתָּה אָבִינוּ, בְּגִין דְּהַאי עַלְמָא, בְּהַאי דַרְגָּא אִשְׁתַּכְלַל וְאִתְבְּרֵי. וּבַר נַשׁ בֵּיהּ אִתְבְּרֵי, וְנָפַק לְעַלְמָא.","כִּי אַבְרָהָם לֹא יְדָעָנוּ, דְּהָא אַף עַל גַּב דְּבֵיהּ קִיּוּמָא דְעַלְמָא. לָא אִשְׁתַּדַּל עֲלָן, כְּמָה דְאִשְׁתַּדַּל עַל יִשְׁמָעֵאל. דְּאָמַר, (בראשית י״ז:י״ח) לוּ יִשְׁמָעֵאל יִחְיֶה לְפָנֶיךָ. וְיִשְׂרָאֵל לֹא יַכִּירֶנּוּ, בְּגִין דְּכָל בִּרְכָאן דְּאִצְטְרִיךְ לְבָרְכָא לִבְנוֹי, שָׁבַק לְהַאי דַרְגָּא לְבָרְכָא כֻּלְּהוּ.","אַתָּה ה' אָבִינוּ, דְּהָא אַנְתְּ קָיְימַת עֲלָן תָּדִיר לְבָרְכָא, וּלְאַשְׁגָּחָא עֲלָן, כְּאַבָּא דְאַשְׁגַּח עַל בְּנִין בְּכָל מַה דְּאִצְטְרִיךְ לוֹן. גּוֹאֲלֵנוּ מֵעוֹלָם שְׁמֶךָ, דְּהָא אַנְתְּ הוּא גוֹאֵל, דְּהָכִי אִתְקְרֵי הַמַּלְאָךְ הַגּוֹאֵל. וְדָא גוֹאֲלֵנוּ מֵעוֹלָם שְׁמֶךָ, שְׁמֶךָ וַדַּאי. תָּנִינָן, אֵין מַפְסִיקִין בֵּין גְּאוּלָּה לִתְפִלָּה, כְּמָה דְלָא מַפְסִיקִין בֵּין תְּפִלָּה שֶׁל יַד לִתְפִלָּה שֶׁל רֹאשׁ. דְּבָעֵי לְמֶחזֵי דְּכֹלָּא חַד, וְהָא אוּקְמוּהָ.","רִבִּי יִצְחָק וְרִבִּי יְהוּדָה הֲווּ יַתְבֵי לֵילְיָא חַד וְלָעָאן בְּאוֹרַיְיתָא. אָמַר רִבִּי יִצְחָק לְרִבִּי יְהוּדָה, הָא תָּנִינָן דְּכַד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, עֲבַד עַלְמָא תַּתָּאָה כְּגַוְונָא דְעַלְמָא עִלָּאָה. וְכֹלָּא דָּא לָקֳבֵל דָּא. (ד\"א ציין זה למהוי דא לקבל דא) וְאִיהוּ יְקָרֵיהּ לְעֵילָא וְתַתָּא.","אָמַר רִבִּי יְהוּדָה, הָכִי הוּא וַדַּאי. וּבָרָא אָדָם עַל כֹּלָּא, הֲדָא הוּא דִכְתִיב, (ישעיה מ) אָנֹכִי עָשִׂיתִי אֶרֶץ וְאָדָם עָלֶיהָ בָּרָאתִי. אָנֹכִי עָשִׂיתִי אֶרֶץ וַדַּאי. מַאי טַעְמָא עָשִׂיתִי אֶרֶץ, בְּגִין דְּאָדָם עָלֶיהָ בָּרָאתִי, דְּאִיהוּ קִיוּמָא דְעַלְמָא, לְמֶהֱוֵי כֹּלָּא בִּשְׁלִימוּ חַד.","פָּתַח וְאָמַר, (ישעיהו מ״ב:ה׳) כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם רוֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ נוֹתֵן נְשָׁמָה לָעָם עָלֶיהָ וְרוּחַ לַהוֹלְכִים בָּהּ. הַאי קְרָא אוּקְמוּהָ, אֲבָל, כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם, דָּא קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא לְעֵילָא. דְּאִיהוּ בּוֹרֵא הַשָּׁמַיִם, וְאַתְקִין לֵיהּ תָּדִיר בְּכָל זִמְנָא. רוֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ, דָּא אַרְעָא קַדִּישָׁא, צְרוֹרָא דְחַיֵּי. נוֹתֵן נְשָׁמָה לָעָם עָלֶיהָ. (הארץ) דָּא הִיא דְּיַהֲבָה נְשָׁמָה וְגו'.","אָמַר רִבִּי יִצְחָק, כֹּלָּא אִיהוּ לְעֵילָא, דְּהָא מִתַּמָּן נָפְקָא נִשְׁמָתָא דְחַיֵּי, לְהַאי אֶרֶץ. וְהַאי אֶרֶץ, נָקְטָא נִשְׁמָתָא לְמֵיהַב לְכֹלָּא. בְּגִין דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק, אִיהוּ יָהִיב וְעָיִיל נִשְׁמָתִין לְהַאי אֶרֶץ, וְאִיהוּ נָקְטָא לוֹן וְיָהֲבָא לְכֹלָּא.","תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא לֵיהּ לְאָדָם, אַכְנִישׁ עַפְרֵיהּ מֵאַרְבַּע סִטְרִין דְּעַלְמָא. וְעֲבַד גַּרְמֵיהּ בְּאֲתַר דְּמַקְדְּשָׁא לְתַתָּא, וְאַמְשִׁיךְ עֲלֵיהּ נִשְׁמָתָא דְחַיֵּי מִבֵּי מַקְדְּשָׁא לְעֵילָא."],[[0,"ויגש אליו יהודה וגו':","ר' אלעזר פתח ואמר, כי אתה אבינו כי אברהם לא ידענו וגו'. מקרא זה בארוהו. אבל בא וראה, כשברא הקב\"ה את העולם, כל יום ויום עשה את מלאכתו כראוי, בכל יום ויום עשה כמו שצריך, כיון שבא יום הששי, והוצרך לברוא את האדם, באה לפניו התורה, אמרה, אדם זה שאתה רוצה לברוא, עתיד הוא להכעיס אותך, אם לא תאריך אפך, מוטב לו שלא יברא. אמר לה הקב\"ה, הכי בחנם אני נקרא, ארך אפים. הביאור הוא בסוף המאמר."],[1,"אלא כלא באורייתא וכו':","אלא הכל נברא בתורה, והכל נשתכלל בתורה. וכמו שהתורה מתחלת ב \u0003ב'\u0004 כן נברא העולם ב \u0003ב'.\u0004 כי מטרם שברא הקב\"ה את העולם שהוא הנוקבא, באו כל האותיות לפניו, ונכנסו כל אחת ואחת למפרע. דהיינו בסדר תשר\"ק צפע\"ס וכו', ולא בסדר אבג\"ד וכו'."],[2,"עאלת תיו וכו':","נכנסה ה \u0003ת'\u0004 ואמרה לפניו, רצונך לברוא עמי את העולם. אמר לה הקב\"ה לא. כי בך עתידים הרבה צדיקים למות. שכתוב, והתוית תיו על מצחות האנשים וגו'. ולמדנו, שכתוב וממקדשי תחלו, אל תקרי וממקדשי, אלא וממקודשי שהם הצדיקים, (כמ\"ש במסכת שבת דף נה. ע\"ש) ומשום זה, העולם לא יברא בך."],[3,"עאלו תלת אתוון וכו':","באו ג' האותיות, שין קוף ריש, כל אחד ואחד בפני עצמו. אמר להן הקב\"ה, אינכן כדאי, שיברא בכן העולם, כי אתן האותיות שנקרא בכם שקר, ושקר אינו שוה לקום לפני, וכבר בארוה."],[4,"ועלו פ\"א צד\"י וכו':","ובאו האותיות \u0003פ'\u0004 ו \u0003צ'\u0004, וכן כולן, עד שהגיעו האותיות לאות \u0003כ',\u0004 כיון שירדה ה \u0003כ'\u0004 מעל הכתר, נזדעזעו העליונים ותחתונים, עד שנתקיים הכל באת \u0003ב',\u0004 שהיא סימן ברכה, ובו נשתכלל העולם ונברא. וביאור ענין זה תמצא לעיל (בהקדמת ספר הזהר דף כ\"ה מאות כ\"ב עד אות ל\"ט בהסולם ע\"ש)."],[5,"ואי תימא דאלף וכו':","ואם תאמר, הרי ה \u0003א'\u0004 הוא ראש כל האותיות, והיה צריך לברוא בה העולם. ומשיב, כך הוא, אלא משום שנקרא בה ארור, לא נברא בה העולם, משום זה, אע\"פ שה \u0003א'\u0004 היא אות מסוד עליון. בכדי שלא לתת מקום דהיינו כח וחיזוק, לסטרא אחרא, הנקראת \u0003ארור.\u0004 לכן לא נברא בה העולם, ונשתכלל העולם ב \u0003ב'\u0004 ובו נברא."],[6,"ת\"ח, כי אתה אבינו:","פירושו, משום שעולם הזה, שהוא הנוקבא דז\"א הנקראת \u0003אתה,\u0004 נשתכלל ונברא במדרגה זו, דהיינו בסימן ברכה, כנ\"ל שהעולם נברא ונשתכלל ב \u0003ב',\u0004 מפני שהיא סימן הברכה, וגם האדם נברא בה, במדרגת סימן הברכה, ויצא לעולם. לפיכך נחשבת הנוקבא מבחינה זו לשורש אל האדם, ואנו אומרים אליה, כי \u0003אתה\u0004 אבינו. דהיינו כי \u0003אתה\u0004 שורשינו. ומ\"ש שגם האדם נברא בסימן ברכה, יבואר להלן (בדף ג' ד\"ה ועם זה)."],[7,"כי אברהם לא ידענו:","כי אע\"פ שבו קיום העולם, שה\"ס החסד, שכתוב, עולם חסד יבנה לא השתדל עלינו כמו שהשתדל על ישמעאל, שאמר, לו ישמעאל יחיה לפניך. \u0003וישראל לא יכירנו:\u0004 כי כל הברכות שהיה צריך לברך את בניו, הניח למדרגה הזאת, דהיינו הנוקבא, לברך את כולם. דהיינו כמ\"ש \u0003וזאת\u0004 אשר דבר להם אביהם, שפירושו שהנוקבא הנקראת זאת, דבר להם דהיינו בשבילם, אביהם, שתברך אותם. וכן בברכת אפרים ומנשה, אמר, המלאך הגואל אותי מכל רע, שהוא הנוקבא, יברך את הנערים וגו'."],[8,"אתה ה' אבינו:","היינו הנוקבא כנ\"ל, כי את עומדת עלינו תמיד, לברך ולהשגיח עלינו, כמו אב המשגיח על הבנים בכל מה שנצרך להם. \u0003גואלנו מעולם שמך:\u0004 כי את, דהיינו הנוקבא, היא גואל, כי כן היא נקראת, \u0003המלאך הגואל,\u0004 וזהו גואלנו מעולם, \u0003שמך.\u0004 שמך ודאי, שהוא הנוקבא, הנקרא \u0003שם\u0004 הוי\"ה. למדנו, שאין מפסיקים בין גאולה לתפלה, דהיינו בין הברכה גאל ישראל, לתפלת שמונה עשרה, כמו שאין מפסיקים בין ברכת תפלה של יד לברכת תפלה של ראש. וכבר בארוה."],[8,"","ביאור המאמר. כי הוקשה לו בכתוב, ויגש אליו יהודה, שלכאורה הוא מיותר, שהיה מספיק לומר, ויאמר אליו יהודה בי אדני. ופתח ר' אלעזר לבאר זה עם הכתוב, כי אתה אבינו וגו'. ומוכיח תחילה, שהאדם והנוקבא דז\"א הם שניהם במדרגה אחת, דהיינו במדרגת חסדים המגולים בהארת החכמה, שהאדם נברא עם השם \u0003ארך אפים,\u0004 שיורה שמאריך אפו ואינו מגלהו, כדי שהאדם יוכל לקבל ג\"ר דהארת החכמה. וכן העולם שהוא הנוקבא דז\"א נבראה עם \u0003ב',\u0004 שפירושה נקודה בהיכליה, שהיא סימן ברכה, דהיינו התחלה לגילוי המוחין דג\"ר דהארת החכמה. כמ\"ש לעיל (בראשית א' דף קכ\"ט אות קל\"ט וק\"מ) אשר א' ה\"ס \u0003חיות טמירין,\u0004 שפירושם חסדים מכוסים מחכמה. ו \u0003ב'\u0004 ה\"ס \u0003חיות דאתגליין,\u0004 שפירושם חסדים המתגלים בהארת החכמה. עש\"ה."],[8,"","ועם זה ביאר הכתוב, שאמרו ישראל אל הנוקבא דז\"א, שנקראת \u0003אתה,\u0004 מטעם היותה \u0003עלמא דאתגליא\u0004 כי הנוקבא שמחזה ולמעלה דז\"א נקראת \u0003הוא,\u0004 דהיינו נסתר, ולא \u0003אתה,\u0004 כנודע. ומתוך שהיא, עלמא דאתגלייא עם הארת החכמה, ע\"כ אמרו לה, \u0003כי אתה אבינו\u0004 כי גם בני ישראל הם ממדרגת \u0003עלמא דאתגלייא\u0004 כנ\"ל, שע\"כ נברא עם השם ארך אפים. \u0003כי אברהם לא ידענו, דלא אשתדל עלן, כמה דאשתדל על ישמעאל, דאמר, לו ישמעאל יחיה לפניך,\u0004 כי ישמעאל ה\"ס, מל ולא פרע י\"ה, שאינו ממשיך הג\"ר דחכמה, שנק' י\"ה, ומילה שלו היא \u0003בריקניא\u0004 דהיינו בו\"ק, בלי מוחין דהארת חכמה. ולהיותו צריך לחכמה, כי הוא מבחי' מחזה ולמטה, ואין לו, ע\"כ נחשב לפסולת הימין. אמנם אברהם ה\"ס חסדים דימין הבינה שאינו צריך לחכמה, וע\"כ הוא מכוסה מחכמה, בסוד, \u0003כי חפץ חסד הוא,\u0004 וע\"כ התפלל ביותר על חסדים הנעלמים מחכמה, כי אליהם כל חפצו ותשוקתו. וז\"ס שאמר, לו ישמעאל יחיה לפניך, ולא אמר כלשון הזה על יצחק. ונמצא משום זה, \u0003אברהם לא ידענו.\u0004 שאין \u0003הדעת\u0004 שלו מגולה לנו. \u0003וישראל לא יכירנו,\u0004 מטעם שישראל ה\"ס קו אמצעי שמחזה ולמעלה דז\"א, ששם סוד \u0003עלמא דאתכסיא\u0004 מהארת חכמה, וע\"כ \u0003כל ברכאן דאצטריך לברכא לבנוי, שבק להאי דרגא,\u0004 דהיינו אל הנוקבא, \u0003לברכא כלהו,\u0004 כי בניו הם מבחינת מחזה ולמטה, שהיא עלמא דאתגליא בהארת חכמה, וכיון שהוא רק בחינת חסדים מכוסים, לא היה יכול לברך אותם, וע\"כ הניח הברכה שלהם ביד הנוקבא, שהיא עלמא דאתגלייא, שהיא תברך אותם. הרי אשר \u0003ישראל\u0004 לא יכיר את צרכינו למלאות לנו. לפיכך אמרו אל הנוקבא, \u0003אתה ה' אבינו, דהא את וכו' בכל מה דאצטריך לון,\u0004 דהיינו הן חסדים והן חכמה, \u0003גואלנו מעולם שמך, דהא אנת הוא גואל וכו',\u0004 כי אין גאולה אלא במוחין דהארת החכמה, וע\"כ נקראת הנוקבא, \u0003המלאך הגואל\u0004 כלפי בני ישראל, וכן יסוד דז\"א הנקרא \u0003יוסף,\u0004 נקרא \u0003גואל\u0004 כלפי הנוקבא, משום שמשפיע לה המוחין הללו דהארת חכמה. וז\"ס שאין מפסיקים בין גאולה לתפלה, דהיינו בין יסוד לנוקבא, כי ליחדם אנו צריכים, וגם ז\"ס שאין מפסיקים בין תפלה של יד שה\"ס הנוקבא, לבין תפלה של ראש שה\"ס ז\"א. ובזה נפתח לנו ביאור הכתוב \u0003ויגש אליו יהודה,\u0004 כי יהודה ה\"ס הנוקבא דהיינו תפילה, ויוסף ה\"ס גאולה, כנ\"ל, ומשמיענו הכתוב שנגשו זה לזה, לזווג, עד ולא יכול יוסף להתאפק וגו'. וגילה להם המוחין הללו."],[9,"ר' יצחק ור' יהודה וכו':","ר\"י ור' יהודה, היו יושבים לילה אחד ועוסקים בתורה. א\"ר יצחק לר' יהודה, הרי למדנו, כי כאשר ברא הקב\"ה את העולם, עשה את עולם התחתון כעין עולם העליון, ועשה הכל זה כנגד זה, שכל פרט ופרט שבעולם התחתון יש לו שורש, כנגדו בעולם העליון, והוא כבודו למעלה ולמטה."],[10,"אמר ר' יהודה וכו':","אר\"י, כן הוא ודאי, וברא אדם על הכל, שהוא כולל ומשלים כל פרטי הבריאה, וז\"ש, אנכי עשיתי ארץ ואדם עליה בראתי, \u0003אנכי עשיתי ארץ,\u0004 זה ודאי ואינו צריך להשמיענו. אלא משמיענו, מהו הטעם שעשיתי ארץ, משום \u0003שאדם עליה בראתי,\u0004 שהוא קיום העולם, ושתהיה הכל שלימות אחד. כלומר, שתכלית כל העולם ושלימותו, הוא האדם."],[11,"פתח ואמר, כה אמר האל וגו'",": מקרא זה כבר בארוה. אבל כה אמר האל ה' \u0003בורא שמים ונוטיהם.\u0004 זהו הקב\"ה למעלה למעלה, דהיינו בינה, שהוא בורא השמים, שהוא ז\"א, שהבינה, מתקנת את ז\"א תמיד בכל זמן. כלומר שהיא מאצלת אותו ומשפעת לו המוחין. \u0003רוקע הארץ וצאצאיה,\u0004 זהו ארץ הקדושה צרור החיים, דהיינו הנוקבא. \u0003נותן נשמה לעם עליה,\u0004 הארץ, שהיא הנוקבא, נותנת נשמה."],[12,"אמר ר' יצחק וכו':","אר\"י, הכל היא למעלה, דהיינו בבינה וחולק על ר' יהודה, שאמר, שנותן נשמה לעם, סובב על הנוקבא, כי משם, מבינה, יוצאת נשמת חיים לארץ הזו, שהיא הנוקבא. וארץ הזו מקבלת הנשמה, לתת לכל, כי נהר ההוא הנמשך ויוצא, שהוא ז\"א, הוא, מקבל מבינה, ונותן ומכניס הנשמות לארץ הזו, שהיא הנוקבא, והיא מקבלת אותן ונותנת לכל אדם הזוכים בה."],[13,"ת\"ח כד ברא וכו':","בוא וראה כאשר ברא הקב\"ה את האדם, אסף עפרו מארבע רוחות העולם, ועשה אותו במקום בית המקדש שלמטה, שה\"ס הנוקבא, והמשיך עליו נשמת חיים, מבית המקדש שלמעלה, שה\"ס בינה."]],[[0,"","וַיִּגַּשׁ אֵלָיו יְהוּדָה וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (ישעיה סג) כִּי אַתָּה אָבִינוּ כִּי אַבְרָהָם לֹא יְדָעָנוּ וְיִשְׂרָאֵל לֹא יַכִּירָנוּ אַתָּה ה' אָבִינוּ גֹּאֲלֵנוּ מֵעוֹלָם שְׁמֶךְ. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ. אֲבָל בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, כָּל יוֹם וָיוֹם עָשָׂה מַעֲשֵׂהוּ כָּרָאוּי בְּכָל יוֹם וָיוֹם כְּמוֹ שֶׁצָּרִיךְ. כֵּיוָן שֶׁבָּא הַיּוֹם הַשִּׁשִּׁי וְהִצְטָרֵךְ לִבְרֹא אָדָם, בָּאָה לְפָנָיו הַתּוֹרָה. אָמְרָה (לפני הקדוש ברוך הוא): הָאָדָם הַזֶּה שֶׁאַתָּה רוֹצֶה לִבְרֹא, עָתִיד הוּא לְהַרְגִּיז לְפָנֶיךְ. אִלְמָלֵא לֹא תַאֲרִיךְ רָגְזְךְ, טוֹב לוֹ שֶׁלֹּא יִבָּרֵא. אָמַר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא: וְכִי לְחִנָּם נִקְרֵאתִי אֶרֶךְ אַפַּיִם?"],[1,"","אֶלָּא הַכֹּל נִבְרָא בַּתּוֹרָה וְהַכֹּל נִתְקַן בַּתּוֹרָה, מִשּׁוּם שֶׁבְּטֶרֶם בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, בָּאוּ לְפָנָיו כָּל הָאוֹתִיּוֹת, וְנִכְנְסוּ כָּל אַחַת לְמַפְרֵעַ."],[2,"","נִכְנְסָה תָּי\"ו, אָמְרָה לְפָנָיו: רְצוֹנְךְ לִבְרֹא בִי אֶת הָעוֹלָם? אָמַר לָהּ: לֹא, שֶׁבָּךְ עֲתִידִים כַּמָּה צַדִּיקִים לָמוּת, שֶׁכָּתוּב וְהִתְוִיתָ תָּו עַל מִצְחוֹת הָאֲנָשִׁים וְגוֹ'. וְשָׁנִינוּ, שֶׁכָּתוּב וּמִמִּקְדָּשִׁי תָּחֵלּוּ, אַל תִּקְרֵי מִמִּקְדָּשִׁי אֶלָּא מִמְקֻדָּשַׁי. וּמִשּׁוּם כָּךְ הָעוֹלָם לֹא יִבָּרֵא בָּךְ."],[3,"","נִכְנְסוּ שְׁלֹשׁ הָאוֹתִיּוֹת שִׁי\"ן קוֹ\"ף רֵי\"שׁ, כָּל אַחַת וְאַחַת לְבַדָּהּ. אָמַר לָהֶן הַקָּדוֹשׁ בָּרוּךְ הוּא: אֵינְכֶן כְּדָאִיּוֹת לִבְרֹא בָכֶן אֶת הָעוֹלָם, שֶׁהֲרי אַתֶּן הָאוֹתִיּוֹת שֶׁנִּקְרָא בָכֶן שֶׁקֶר, וְהַשֶּׁקֶר אֵינוֹ כְדַאי לַעֲמֹד לְפָנַי, וְהִנֵּה פֵּרְשׁוּהָ."],[4,"","וְנִכְנְסוּ פֵּ\"א צָדִ\"י, וְכֵן כֻּלָּן, עַד שֶׁהִגִּיעוּ הָאוֹתִיּוֹת לָאוֹת כָּ\"ף. כֵּיוָן שֶׁיָּרְדָה כָּ\"ף מֵעַל הַכֶּתֶר, הִזְדַּעְזְעוּ עֶלְיוֹנִים וְתַחְתּוֹנִים וְכוּ', עַד שֶׁהַכֹּל הִתְקַיֵּם בָּאוֹת בֵּי\"ת, שֶׁהִיא סִימַן בְּרָכָה, וּבָהּ הִשְׁתַּכְלֵל הָעוֹלָם וְנִבְרָא."],[5,"","וְאִם תֹּאמַר שֶׁאָלֶ\"ף הִיא הָרֹאשׁ שֶׁל כָּל (אותן) הָאוֹתִיּוֹת - (לא) נָאֶה הוּא. אֶלָּא מִשּׁוּם שֶׁנִּקְרָא בּוֹ אָרוּר (משום שנקרא בה ארור), וּמִשּׁוּם זֶה לֹא נִבְרָא בּוֹ הָעוֹלָם, אַף עַל גַּב שֶׁאָלֶ\"ף הִיא אוֹת שֶׁל סוֹד עֶלְיוֹן. כְּדֵי לֹא לָתֵת מָקוֹם לַצַּד הָאַחֵר שֶׁנִּקְרָא אָרוּר, לֹא נִבְרָא בּוֹ הָעוֹלָם, וְנִתְקַן הָעוֹלָם בְּבֵי\"ת, וּבוֹ הוּא נִבְרָא."],[6,"","בֹּא רְאֵה, כִּי אַתָּה אָבִינוּ, מִשּׁוּם שֶׁהָעוֹלָם הַזֶּה נִתְקַן וְנִבְרָא בַּדַּרְגָּה הַזּוֹ, וְהָאָדָם נִבְרָא בָּהּ וְיָצָא לָעוֹלָם."],[7,"","כִּי אַבְרָהָם לֹא יְדָעָנוּ, שֶׁהֲרֵי אַף עַל גַּב שֶׁבּוֹ קִיּוּם הָעוֹלָם, לֹא הִשְׁתַּדֵּל עָלֵינוּ כְּמוֹ שֶׁהִשְׁתַּדֵּל עַל יִשְׁמָעֵאל, שֶׁאָמַר לוּ יִשְׁמָעֵאל יִחְיֶה לְפָנֶיךְ. וְיִשְׂרָאֵל לֹא יַכִּירָנוּ, מִשּׁוּם שֶׁכָּל הַבְּרָכוֹת שֶׁהִצְטָרֵךְ לְבָרֵךְ אֶת בָּנָיו, הִשְׁאִיר לַדַּרְגָּה הַזּוֹ לְבָרֵךְ אֶת כֻּלָּם."],[8,"","אַתָּה ה' אָבִינוּ, שֶׁהֲרֵי אַתָּה תָּמִיד עוֹמֵד עָלֵינוּ לְבָרֵךְ וּלְהַשְׁגִּיחַ עָלֵינוּ, כְּמוֹ אָב שֶׁמַּשְׁגִּיחַ עַל הַבָּנִים בְּכָל מַה שֶּׁצָּרִיךְ לָהֶם. גֹּאֲלֵנוּ מֵעוֹלָם שְׁמֶךְ, שֶׁהֲרֵי אַתָּה הוּא גוֹאֵל, שֶׁכָּךְ נִקְרָא הַמַּלְאָךְ הַגּוֹאֵל, וְזֶה גֹּאֲלֵנוּ מֵעוֹלָם שְׁמֶךְ, שְׁמֶךְ וַדַּאי. שָׁנִינוּ, אֵין מַפְסִיקִים בֵּין גְּאֻלָּה לִתְפִלָּה, כְּמוֹ שֶׁלֹּא מַפְסִיקִים בֵּין תְּפִלָּה שֶׁל יָד לִתְפִלָּה שֶׁל רֹאשׁ, שֶׁצָּרִיךְ לְהַרְאוֹת שֶׁהַכֹּל אֶחָד, וְהִנֵּה פֵּרְשׁוּהָ."],[9,"","רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ יוֹשְׁבִים לַיְלָה אֶחָד וְעוֹסְקִים בַּתּוֹרָה. אָמַר רַבִּי יִצְחָק לְרַבִּי יְהוּדָה, הִנֵּה שָׁנִינוּ, שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אֶת הָעוֹלָם הַתַּחְתּוֹן כְּמוֹ שֶׁהָעוֹלָם הָעֶלְיוֹן, וְהַכֹּל זֶה כְּנֶגֶד זֶה, (כדי להיות זה כנגד זה) וְהוּא כְבוֹדוֹ לְמַעְלָה וּלְמַטָּה."],[10,"","אָמַר רַבִּי יְהוּדָה, כָּךְ זֶה וַדַּאי, וּבָרָא אָדָם עַל הַכֹּל. זֶהוּ שֶׁכָּתוּב (ישעיה מה) אָנֹכִי עָשִׂיתִי אֶרֶץ וְאָדָם עָלֶיהָ בָרָאתִי. אָנֹכִי עָשִׂיתִי אֶרֶץ, וַדַּאי. מָה הַטַּעַם עָשִׂיתִי אֶרֶץ? מִשּׁוּם שֶׁאָדָם עָלֶיהָ בָרָאתִי, שֶׁהוּא קִיּוּמוֹ שֶׁל הָעוֹלָם, שֶׁיִּהְיֶה הַכֹּל בִּשְׁלֵמוּת אַחַת."],[11,"","פָּתַח וְאָמַר, (שם מב) כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם רֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ נֹתֵן נְשָׁמָה לָעָם עָלֶיהָ וְרוּחַ לַהֹלְכִים בָּהּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, אֲבָל כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה לְמַעְלָה, שֶׁהוּא בּוֹרֵא הַשָּׁמַיִם, וְהִתְקִינָם תָּמִיד, בְּכָל זְמַן. רֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ - זוֹ הָאָרֶץ הַקְּדוֹשָׁה, צְרוֹר הַחַיִּים. נֹתֵן נְשָׁמָה לָעָם עָלֶיהָ. (הארץ) זוֹ הִיא שֶׁנּוֹתֶנֶת נְשָׁמָה וְגוֹ'."],[12,"","אָמַר רַבִּי יִצְחָק, הַכֹּל הוּא לְמַעְלָה, שֶׁהֲרֵי מִשָּׁם יוֹצֵאת נִשְׁמַת חַיִּים לָאָרֶץ הַזּוֹ, וְהָאָרֶץ הַזּוֹ לוֹקַחַת הַנְּשָׁמָה לָתֵת לַכֹּל, מִשּׁוּם שֶׁהַנָּהָר הַהוּא שֶׁשּׁוֹפֵעַ וְיוֹצֵא, הוּא נוֹתֵן וּמַכְנִיס נְשָׁמוֹת לָאָרֶץ הַזּוֹ, וְהִיא לוֹקַחַת אוֹתָן וְנוֹתֶנֶת לַכֹּל."],[13,"","בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, כִּנֵּס אֶת עֲפָרוֹ מֵאַרְבָּעָה הַצְּדָדִים שֶׁל הָעלָם, וְעָשָׂה אֶת עַצְמוֹ בִּמְקוֹם הַמִּקְדָּשׁ לְמַטָּה, וְהִמְשִׁיךְ עָלָיו נִשְׁמַת חַיִּים מִבֵּית הַמִּקְדָּשׁ לְמַעְלָה."]]],[["וְנִשְׁמָתָא אִיהִי כְּלִילָא בִּתְלַת דַּרְגִּין, וְעַל דָּא תְּלַת שְׁמָהָן אִינוּן לְנִשְׁמָתָא, כְּגַוְונָא דְרָזָא עִלָּאָה. נֶפֶ\"שׁ, רוּ\"חַ, נְשָׁמָ\"ה. נֶפֶשׁ, הָא אוּקְמוּהָ דְּאִיהִי תַּתָּאָה מִכֹּלָּא. רוּחַ, אִיהוּ קִיּוּמָא דְּשָׁלְטָא עַל נֶפֶשׁ, וְאִיהוּ דַרְגָּא עִלָּאָה עֲלָהּ, לְקָיְימָא עֲלָהּ בְּכֹלָּא כְּדְקָא חָזֵי. נְשָׁמָה, אִיהִי קִיּוּמָא עִלָּאָה עַל כֹּלָּא, וְשָׁלְטָא עַל כֹּלָּא, דַּרְגָּא קַדִּישָׁא עִלָּאָה עַל כֻּלְּהוּ.","וְאִלֵּין תְּלַת דַּרְגִּין, כְּלִילָן בְּהוּ בִּבְנֵי נָשָׁא, לְאִינוּן דְּזָכָאן לְפוּלְחָנָא דְּמָארֵיהוֹן. דְּהָא בְּקַדְמִיתָא אִית בֵּיהּ נֶפֶשׁ, וְאִיהוּ תִּקּוּנָא קַדִּישָׁא לְאִתְתַּקָּנָא בָּהּ בַּר נָשׁ. כֵּיוָן דְּאָתֵי בַּר נָשׁ לְאִתְדַּכָּאָה בְּהַאי דַרְגָא, אִתְתַּקַּן לְאִתְעַטְּרָא בְּרוּחַ. דְּאִיהוּ דַרְגָּא קַדִּישָׁא דְּשָׁרְיָא עַל נֶפֶשׁ לְאִתְעַטְּרָא בֵּיהּ בַּר נָשׁ, הַהוּא דְזָכֵי.","כֵּיוָן דְּאִסְתַּלַּק בְּהוּ, בְּנֶפֶשׁ וְרוּחַ, וְעָאל וְאִתְתַּקַּן בְּפוּלְחָנָא דְמָארֵיהּ כְּדְקָא יְאוּת. כְּדֵין שַׁרְיָא עֲלֵיהּ נְשָׁמָה. דַּרְגָּא עִלָּאָה קַדִּישָׁא, דְּשָׁלְטָא עַל כֹּלָּא. בְּגִין לְאִתְעַטְּרָא בְּדַרְגָּא עִלָּאָה קַדִּישָׁא. וּכְדֵין אִיהוּ שְׁלִימָא דְּכֹלָּא, שְׁלִים בְּכָל סִטְרִין, לְמִזְכֵּי בְּעַלְמָא דְאָתֵי. וְאִיהוּ רְחִימָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָא דְאַתְּ אָמֵר, (משלי ח׳:כ״א) לְהַנְחִיל אוֹהֲבַי יֵשׁ. מַאן אִינוּן אוֹהֲבַי, אִלֵּין אִינוּן דְּנִשְׁמָתָא קַדִּישָׁא בְּהוּ.","אָמַר רִבִּי יְהוּדָה, אִי הָכִי הָא כְּתִיב, (בראשית ז׳:כ״ב) כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו וְגו'. אָמַר לֵיהּ, הָכִי הוּא וַדַּאי. דְּהָא לָא אִשְׁתָּאַר בְּהוּ. מִכָּל אִינוּן דְּהֲווּ בְּהוּ נִשְׁמָתָא קַדִּישָׁא. כְּגוֹן חֲנוֹךְ, יֶרֶד וְכֻלְּהוּ צַדִּיקַיָּא, בְּגִין לַאֲגָנָא עַל אַרְעָא, דְּלָא יִשְׁתֵּצֵי בְּגִינַיְיהוּ. הֲדָא הוּא דִכְתִיב, כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ. כְּבָר מֵתוּ וְאִסְתַּלָּקוּ מֵעַלְמָא, וְלָא אִשְׁתָּאַר מִנְּהוֹן מַאן דְּיָגִין עַל עַלְמָא בְּהַהוּא זִמְנָא.","תָּא חֲזֵי, כֹּלָּא אִינוּן דַּרְגִּין, אִלֵּין עַל אִלֵּין. נֶפֶ\"שׁ, רוּ\"חַ, נְשָׁמָ\"ה. דַּרְגָּא עַל דַּרְגָּא. נֶפֶשׁ בְּקַדְמִיתָא, וְאִיהִי דַרְגָּא תַּתָּאָה כִּדְקָאֲמָרָן. רוּחַ לְבָתַר, דְּשַׁרְיָא עַל נֶפֶשׁ וְקָיְימָא עֲלָהּ. נְשָׁמָה, דַּרְגָּא דְסָלְקָא עַל כֹּלָּא, וְאוּקְמוּהָ.","נֶפֶשׁ, דָּא נֶפֶשׁ דָּוִד, וְאִיהִי דְקָיְימָא לְקַבְּלָא נֶפֶשׁ מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק. רוּחַ, דָּא רוּחַ דְּקָיְימָא עֲלֵיהּ דְּנַפְשָׁא, וְלֵית קִיּוּמָא לְנֶפֶשׁ אֶלָּא בְּרוּחַ. וְדָא אִיהוּ רוּחַ דְּשַׁרְיָא בֵּין אֶשָּׁא וּמַיָּא, וּמֵהָכָא אִתְּזָן הַאי נֶפֶשׁ.","רוּחַ, קָיְימָא בְּקִיּוּמָא דְדַרְגָּא אוֹחֲרָא עִלָּאָה דְּאִקְרֵי נְשָׁמָה, דְּהָא מִתַּמָּן נָפְקֵי נֶפֶשׁ וְרוּחַ. מִתַּמָּן אִתְּזָן רוּחַ. וְכַד נָטִיל רוּחַ, כְּדֵין נָטְלָא נֶפֶשׁ, וְכֹלָּא חַד. וְאִתְקְרִיבוּ דָּא בְּדָא. נֶפֶשׁ אִתְקְרִיב בְּרוּחַ, וְרוּחַ אִתְקְרִיב בִּנְשָׁמָה, וְכֹלָּא חַד.","תָּא חֲזֵי, וַיִּגַּשׁ אֵלָיו, תִּקְרוּבְתָּא דְעַלְמָא בְּעַלְמָא, לְאִתְאַחֲדָא דָּא בְּדָא לְמֶהוֵי כֹּלָּא חַד. בְּגִין דִּיְהוּדָה אִיהוּ מֶלֶךְ וְיוֹסֵף מֶלֶךְ. אִתְקְרִיבוּ דָא בְּדָא, וְאִתְאֲחִידוּ דָּא בְּדָא.","רִבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים מ״ח:ה׳) כִּי הִנֵּה הַמְלָכִים נוֹעֲדוּ, דָּא יְהוּדָה וְיוֹסֵף. בְּגִין דְּתַרְוַויְיהוּ מְלָכִים, וְאִתְקְרִיבוּ דָּא בְּדָא לְאִתְוַוכְּחָא תַּרְוַויְיהוּ כָּחֲדָא. בְּגִין דִּיְהוּדָה אִתְעָרֵב בֵּיהּ בְּבִנְיָמִן, וְהֲוָה עָרֵב לְגַבֵּיהּ דְּאֲבוֹי בֵּיהּ, בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי. וְעַל דָּא אִתְקְרִיב קַמֵּיהּ דְּיוֹסֵף, לְאִתְוַוכְּחָא עִמֵּיהּ עַל עִסְקָא דְבִנְיָמִן, דְּלָא לְמֶהוֵי בְּנִדּוּי. בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי. כְּמָא דְאַתְּ אָמֵר, (בראשית מ״ג:ט׳) אָנֹכִי אֶעֶרְבֶנּוּ מִיָּדִי תְּבַקְּשֶׁנּוּ אִם לא הֲבִיאוֹתִיו אֵלֶיךָ וְהִצַּגְתִּיו לְפָנְיךָ וְחָטָאתִי לְאָבִי כָּל הַיָּמִים. בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי.","וְעַל דָּא, כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ עָבְרוּ יַחְדָּיו, אִתְרְגִיזוּ כְּחֲדָא, וְאִתְרְגִּיזוּ דָּא בְּדָא בְּגִינֵיהּ דְּבִנְיָמִן. מַה כְּתִיב, הֵמָּה רָאוּ כֵּן תָּמָהוּ נִבְהֲלוּ נֶחְפָּזוּ רְעָדָה אֲחָזָתַם שָׁם, לְכָל אִינוּן דְּהֲווּ תַּמָּן. (לכלהו שאר שבטין דהוו תמן).","חִיל כַּיּוֹלֵדָה, בְּגִין דְּהֲווּ דַּחֲלִין, לְקָטְלָא וּלְאִתְקְטָלָא, וְכֹלָּא בְּגִינֵיהּ דְּבִנְיָמִן. (ד\"א ציין זה מה כתיב כן תמהו נבהלו נחפזו וכלא בגיניה) דְּהָא יוֹסֵף אִזְדַּבַּן בְּגִינֵיהּ דִּיהוּדָה, וְאִתְאֲבִיד מֵאֲבוֹי. וְהַשְׁתָּא אִתְעָרַב בֵּיהּ בְּבִנְיָמִין, וְדָחִיל דְּלָא יִתְאֲבִיד. וּבְגִין כָּךְ וַיִּגַּשׁ אֵלָיו יְהוּדָה."],[[0,"ונשמתא איהי כלילא וכו':","והנשמה היא כלולה משלש מדרגות, ועל כן שלשה שמות יש לנשמה, כעין הסוד העליון, \u0003נפש, רוח, נשמה. נפש,\u0004 הרי בארוה שהיא תחתונה מכולם. שהיא נמשכת מן הנוקבא, שהיא התחתונה מעשר ספירות. \u0003רוח,\u0004 הוא קיום, השולט על הנפש, והוא מדרגה שלמעלה ממנה, שנמשך מן ז\"א, לקיים אותה בכל. הן בחכמה הן בחסדים, כראוי. \u0003נשמה\u0004 היא קיום, עליון על הכל, דהיינו אור הבינה. שהיא עליון על אור ז\"א ואור הנוקבה, שהם רוח נפש. ושולטת על הכל, מדרגה קדושה העליונה על כולם. דהיינו על רוח נפש."],[1,"ואלין תלת דרגין וכו':","ואלו ג' מדרגות, נפש רוח ונשמה, כלולות בבני אדם, באלו שזכו לעבודת רבונם. כי מתחילה יש לו נפש, והיא תקון קדוש, שיתתקנו בה בני אדם. כיון שהאדם בא להטהר במדרגה זו, הוא מתתקן להתעטר עם \u0003רוח,\u0004 והיא מדרגה קדושה השורה על \u0003הנפש,\u0004 שיתעטר בה אדם ההוא שזכה."],[2,"כיון דאסתלק בהו וכו':","כיון שנתעלה בנפש ורוח, ובא ונתקן בעבודת רבונו כראוי, אז שורה עליו הנשמה, שהיא מדרגה עליונה קדושה השולטת על הכל, כדי שיתעטר במדרגה עליונה קדושה, ויהיה אז שלם בכל, שלם מכל הצדדים, לזכות לעולם הבא, והוא אוהבו של הקב\"ה, כמו שאתה אומר, להנחיל \u0003אוהבי\u0004 יש, מי המה \u0003אוהבי,\u0004 אלו הם, שנשמה קדושה בהם."],[3,"אמר ר' יהודה וכו':","אר\"י, אם כן, הרי כתוב, כל אשר \u0003נשמת\u0004 רוח חיים באפיו וגו'. ואם הזוכים לנשמה הם אוהביו של הקב\"ה למה מתו במבול. אמר לו, כן הוא ודאי שהם אוהביו של הקב\"ה, ולא נשאר מכל אלו שהיה בהם נשמה קדושה, דהיינו חנוך, ירד, וכל הצדיקים, שהיו יכולים להגן על הארץ שלא תשחת בזכותם. וזהו שכתוב, כל אשר נשמת רוח חיים באפיו מכל אשר בחרבה מתו, שפירושו כבר \u0003מתו\u0004 ונסתלקו מן העולם, ולא נשאר מהם מי שיגן על העולם בזמן ההוא."],[4,"ת\"ח כלא אינון וכו':","בוא וראה, הכל הם, מדרגות על מדרגות, ונפש רוח ונשמה, הם מדרגות על מדרגות, זו למעלה מזו, \u0003נפש\u0004 מתחילה, והיא מדרגה התחתונה, כמו שאמרנו. ואחר כך \u0003רוח,\u0004 השורה על הנפש ועומד עליה. נשמה היא מדרגה העולה על הכל, ובארוה."],[5,"נפש דא וכו':","נפש, זו היא נפש דוד, שהיא הנוקבא, והיא עומדת לקבל הנפש מנהר ההוא הנמשך ויוצא. שהוא ז\"א, \u0003רוח,\u0004 זהו רוח העומד על הנפש, ואין קיום לנפש אלא ברוח, וזה הוא רוח השורה בין אש ומים, דהיינו ת\"ת, שהוא קו אמצעי בין גבורה שנק' אש, לבין חסד הנקרא מים. ומכאן נזונת נפש הזאת."],[6,"רוח קיימא בקיומא וכו':","הרוח עומד ומקבל קיום ממדרגה אחרת עליונה, הנקראת \u0003נשמה,\u0004 אשר משם יוצאים רוח ונפש, דהיינו אור הבינה, שממנה יוצאים אור ז\"א שנקרא רוח ואור הנוקבא שנקרא נפש, משם ניזון הרוח, וכשהרוח נוסע, נוסעת אז גם הנפש, והכל אחד, ומתקרבים זה לזה, הנפש מתקרבת אל הרוח, והרוח מתקרב לנשמה, וכולם אחד."],[7,"תא חזי ויגש וכו':","בוא וראה, \u0003ויגש אליו\u0004 וגו', הוא התקרבות עולם בעולם, דהיינו התקרבות של עולם התחתון, שהוא הנוקבא, ובחינת נפש, הנקראת יהודה, לעולם העליון, שהוא יסוד דז\"א, ובחינת רוח הנקרא יוסף, כדי שיהיה הכל אחד. משום שיהודה היה מלך ויוסף היה מלך, נתקרבו זה לזה ונתאחדו זה בזה."],[8,"ר' יהודה פתח וכו':","ר\"י פתח ואמר, \u0003כי הנה המלכים נועדו,\u0004 זהו יהודה ויוסף, כי שניהם היו מלכים, ונגשו זה לזה להתוכח, שניהם יחד, משום שיהודה ערב את בנימין. וערב אל אביו, בעולם הזה ובעולם הבא, וע\"כ נגש אל יוסף להתוכח עמו על אודות בנימין, שלא להיות בנדוי בעולם הזה ובעולם הבא. כמ\"ש אנכי אערבנו וגו' וחטאתי לאבי כל הימים, בעולם הזה ובעולם הבא."],[9,"ועל דא, כי הנה המלכים נועדו עברו יחדיו:","עברו יחדיו פירושו, שנתרגזו יחדיו, שהתרגזו זה לזה בשביל בנימין. מה כתוב, המה ראו כן תמהו נבהלו נחפזו רעדה אחזתם שם, לכל אלו שהיו שם."],[10,"חיל כיולדה:","משום שהיו יראים להרוג או לההרג. והכל היה בשביל בנימין, והנה יוסף נמכר בעצת יהודה ונאבד מאביו, ועתה ערב את בנימין, והיה מתירא שלא יאבד, ומשום זה, ויגש אליו יהודה."]],[[0,"","וְהַנְּשָׁמָה הִיא כְלוּלָה בְּשָׁלֹשׁ דְּרָגוֹת, וְעַל כֵּן שְׁלֹשָׁה שֵׁמוֹת הֵם לַנְּשָׁמָה, כְּמוֹ שֶׁהַסּוֹד הָעֶלְיוֹן: נֶפֶ\"שׁ, רוּ\"חַ, נְשָׁמָ\"ה. נֶפֶשׁ, הִנֵּה פֵּרְשׁוּהָ, שֶׁהִיא תַחְתּוֹנָה מֵהַכֹּל. רוּחַ, הִיא הַקִּיּוּם שֶׁשּׁוֹלֵט עַל הַנֶּפֶשׁ, וְהִיא דַרְגָּה עֶלְיוֹנָה עָלֶיהָ לַעֲמֹד עָלֶיהָ בַּכֹּל כָּרָאוּי. הַנְּשָׁמָה הִיא הַקִּיּוּם הָעֶלְיוֹן עַל הַכֹּל, וְשׁוֹלֵטֶת עַל הַכֹּל, דַּרְגָּה קְדוֹשָׁה, עֶלְיוֹנָה עַל כֻּלָּם."],[1,"","אֵלּוּ שְׁלֹשׁ הַדְּרָגוֹת כְּלוּלוֹת בִּבְנֵי הָאָדָם, לְאוֹתָם שֶׁזּוֹכִים לַעֲבוֹדַת רִבּוֹנָם. שֶׁהֲרֵי בַּהַתְחָלָה יֵשׁ בּוֹ נֶפֶשׁ, וְהוּא הַתִּקּוּן הַקָּדוֹשׁ לְתַקֵּן בּוֹ אֶת הָאָדָם. כֵּיוָן שֶׁבָּא הָאָדָם לְהִטָּהֵר בַּדַּרְגָּה הַזּוֹ, נִתְקָן לְהִתְעַטֵּר בְּרוּחַ, שֶׁהִיא דַרְגָּה קְדוֹשָׁה שֶׁשּׁוֹרָה עַל הַנֶּפֶשׁ לְהִתְעַטֵּר בָּאָדָם הַהוּא שֶׁזּוֹכֶה."],[2,"","כֵּיוָן שֶׁהִתְעַלָּה בָהֶם, בַּנֶּפֶשׁ וְהָרוּחַ, וְנִכְנַס וְנִתְקַן בַּעֲבוֹדַת רִבּוֹנוֹ כָּרָאוּי, אָז שׁוֹרָה עָלָיו נְשָׁמָה, דַּרְגָּה עֶלְיוֹנָה קְדוֹשָׁה, שֶׁשּׁוֹלֶטֶת עַל הַכֹּל, כְּדֵי לְהִתְעַטֵּר בְּדַרְגָּה עֶלְיוֹנָה קְדוֹשָׁה. וְאָז הוּא הַשָּׁלֵם שֶׁל הַכֹּל, שָׁלֵם בְּכָל הַצְּדָדִים, לִזְכּוֹת בָּעוֹלָם הַבָּא, וְהוּא אוֹהֲבוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר לְהַנְחִיל אֹהֲבַי יֵשׁ. מִי הֵם אוֹהֲבַי? אֵלּוּ הֵם שֶׁבָּהֶם נְשָׁמָה קְדוֹשָׁה."],[3,"","אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, הֲרֵי כָּתוּב כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו וְגוֹ'. אָמַר לוֹ, כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי לֹא נִשְׁאַר בָּהֶם. מִכָּל אוֹתָם שֶׁהָיְתָה בָהֶם נְשָׁמָה קְדוֹשָׁה כְּמוֹ חֲנוֹךְ, יֶרֶד, וְכָל הַצַּדִּיקִים, כְּדֵי לְהָגֵן עַל הָאָרֶץ שֶׁלֹּא תֻשְׁמַד בִּגְלָלָם. זֶהוּ שֶׁכָּתוּב כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ, כְּבָר מֵתוּ וְהִסְתַּלְּקוּ מִן הָעוֹלָם, וְלֹא נִשְׁאַר מֵהֶם מִי שֶׁיָּגֵן עַל הָעוֹלָם בַּזְּמַן הַהוּא."],[4,"","בֹּא רְאֵה, הַכֹּל הֵם דְּרָגוֹת אֵלּוּ עַל אֵלּוּ, נֶפֶ\"שׁ, רוּ\"חַ, נְשָׁמָ\"ה, דַּרְגָּה עַל דַּרְגָּה. הַנֶּפֶשׁ בָּרִאשׁוֹנָה, וְהִיא הַדַּרְגָּה הַתַּחְתּוֹנָה, כְּפִי שֶׁאָמַרְנוּ. אַחַר כָּךְ רוּחַ, שֶׁשּׁוֹרָה עַל הַנֶּפֶשׁ וְעוֹמֶדֶת עָלֶיהָ. הַנְּשָׁמָה הַדַּרְגָּה שֶׁעוֹלָה עַל הַכֹּל, וּבֵאֲרוּהָ."],[5,"","נֶפֶשׁ - זוֹ נֶפֶשׁ דָּוִד, וְהִיא שֶׁעוֹמֶדֶת לְקַבֵּל הַנֶּפֶשׁ מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא. רוּחַ - זוֹ הָרוּחַ שֶׁעוֹמֶדֶת עַל הַנֶּפֶשׁ, וְאֵין קִיּוּם לַנֶּפֶשׁ אֶלָּא בָּרוּחַ, וְזוֹ הָרוּחַ שֶׁשּׁוֹרָה בֵּין הָאֵשׁ וְהַמַּיִם, וּמִכָּאן נִזּוֹנֵית הַנֶּפֶשׁ הַזּוֹ."],[6,"","הָרוּחַ עוֹמֶדֶת בְּקִיּוּם שֶׁל דַּרְגָּה אַחֶרֶת עֶלְיוֹנָה שֶׁנִּקְרֵאת נְשָׁמָה, שֶׁהֲרֵי מִשָּׁם יוֹצְאוֹת נֶפֶשׁ וְרוּחַ, מִשָּׁם נִזּוֹנֵית הָרוּחַ. וּכְשֶׁנּוֹסַעַת הָרוּחַ, אָז נוֹסַעַת הַנֶּפֶשׁ, וְהַכֹּל אֶחָד. וּמִתְקָרְבִים זֶה לָזֶה. הַנֶּפֶשׁ נִקְרֶבֶת לָרוּחַ, וְהָרוּחַ נִקְרֶבֶת לַנְּשָׁמָה, וְהַכֹּל אֶחָד."],[7,"","בֹּא רְאֵה, וַיִּגַּשׁ אֵלָיו, הִתְקָרְבוּת שֶׁל עוֹלָם עִם עוֹלָם, לְהֵאָחֵז זֶה עִם זֶה, שֶׁהַכֹּל יִהְיֶה אֶחָד. מִשּׁוּם שֶׁיְּהוּדָה הוּא מֶלֶךְ וְיוֹסֵף מֶלֶךְ, הִתְקָרְבוּ זֶה לָזֶה וְנֶאֶחְזוּ זֶה עִם זֶה."],[8,"","רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים מח) כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ - זֶה יְהוּדָה וְיוֹסֵף, מִשּׁוּם שֶׁשְּׁנֵיהֶם מְלָכִים, וְהִתְקָרְבוּ זֶה לָזֶה לְהִתְוַכֵּחַ שְׁנֵיהֶם יַחַד, מִשּׁוּם שֶׁיְּהוּדָה עָרַב לְבִנְיָמִין, וְהָיָה עָרֵב לְאָבִיו בּוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְעַל כֵּן הִתְקָרֵב לִפְנֵי יוֹסֵף לְהִתְוַכֵּחַ עִמּוֹ עַל עִסְקוֹ שֶׁל בִּנְיָמִין, שֶׁלֹּא לִהְיוֹת בְּנִדּוּי בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מג) אָנֹכִי אֶעֶרְבֶנּוּ מִיָּדִי תְּבַקְשֶׁנּוּ אִם לֹא הֲבִיאֹתִיו אֵלֶיךְ וְהִצַּגְתִּיו לְפָנֶיךְ וְחָטָאתִי לְךְ כָּל הַיָּמִים, בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[9,"","וְעַל כֵּן, כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ עָבְרוּ יַחְדָּו, הִתְרַגְּזוּ יַחַד וְהִתְרַגְּזוּ זֶה עִם זֶה בִּשְׁבִיל בִּנְיָמִין. מַה כָּתוּב? הֵמָּה רָאוּ כֵּן תָּמָהוּ נִבְהֲלוּ נֶחְפָּזוּ רְעָדָה אֲחָזָתַם שָׁם, לְכָל אוֹתָם שֶׁהָיוּ שָׁם. (לכל שאר השבטים שהיו שם,)"],[10,"","חִיל כַּיּוֹלֵדָה, מִשּׁוּם שֶׁהָיוּ פוֹחֲדִים לַהֲרֹג וּלְהֵהָרֵג, וְהַכֹּל בִּשְׁבִיל בִּנְיָמִין. (מה כתוב? כן תמהו נבהלו נחפזו, והכל בגללו) שֶׁהֲרֵי יוֹסֵף נִמְכַּר בִּגְלַל יְהוּדָה וְאָבַד לְאָבִיו, וְכָעֵת עָרַב לוֹ לְבִנְיָמִין, וּפָחַד שֶׁלֹּא יֹאבַד, וּמִשּׁוּם כָּךְ וַיִּגַּשׁ אֵלָיו יְהוּדָה."]]],[["דָּבָר אַחֵר, כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ, דָּא יְהוּדָה וְיוֹסֵף, דְּאִזְדַּמְּנוּ לְאִתְוַכְּחָא דָּא עִם דָּא, לְאִתְוַכְּחָא תַּרְוַויְיהוּ כְּחֲדָא. בְּגִין דִּיהוּדָה הֲוָה מֶלֶךְ, וְיוֹסֵף הֲוָה מֶלֶךְ, וְתַרְוַויְיהוּ אָתוּ כְּחֲדָא לְאִתְוַכְּחָא דָּא עִם דָּא. דָּא עַל בִּנְיָמִן, וְדָא עַל בִּנְיָמִן.","כִּי הִנֵּה הַמְּלָכִים, אָמַר רִבִּי יְהוּדָה, רָזָא דִמְהֵימְנוּתָא הָכָא, דְּהָא כַּד רְעוּתָא אִשְׁתַּכַּח, וְקִשּׁוּרָא אִתְעַטַּר כְּחֲדָא, כְּדֵין תְּרֵין עָלְמִין מִתְקַשְּׁרָן כְּחֲדָא וְאִזְדַּמְּנָן כְּחֲדָא. דָּא לְאַפְתָּחָא אוֹצָרָא, וְדָא לְלַקְּטָא וּלְמִכְנַשׁ בְּגַוֵּיהּ. וּכְדֵין כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ, תְּרֵין עָלְמִין קַדִּישִׁין, עַלְמָא עִלָּאָה וְעַלְמָא תַּתָּאָה.","עָבְרוּ יַחְדָּיו, רָזָא דְמִלָּה, דְּכַד מִתְחַבְּרָן כְּחֲדָא, כְּדֵין עָבְרוּ יַחְדָּיו. בְּגִין דְּכָל חִיּוּבִין דְּעַלְמָא לָא אִתְעַבְרָן לְאִתְכַּפְיָא, עַד דְּמִתְחַבְּרָן כְּחֲדָא. כְּדִכְתִיב, (מיכה ז׳:י״ח) וְעוֹבֵר עַל פֶּשַׁע. וְעַל דָּא עָבְרוּ יַחְדָּיו. עָבְרוּ, אִינוּן חוֹבִין אִתְכַּפָּרוּ. בְּגִין דְּהָא כְדֵין כָּל אַנְפִּין נְהִירִין, וְכָל חוֹבִין אִתְעֲבָרוּ.","רִבִּי חִיָּיא אָמַר, רָזָא דָא בְתִקּוּנָא דְּקָרְבָּנָא אִיהוּ. דְּהָא כַּד קָרְבָּנָא אִתְקְרִיב וְכֹלָּא מִסְתַּפְּקִין, וְכָל חַד וְחַד כְּדְקָא חָזֵי לֵיהּ, כְּדֵין אִתְקַשַּׁר כֹּלָּא כְּחֲדָא. וְכָל אַנְפִּין נְהִירִין, וְקִשּׁוּרָא חַד אִשְׁתַּכַּח. וּכְדֵין הַמְּלָכִים נוֹעֲדוּ וְאִזְדַּמְּנוּ כְּחֲדָא, לְכַפָּרָא עַל חוֹבִין, לְאַעֲבָרָא עֲלַיְיהוּ. וּכְדֵין הַמְּלָכִים נוֹעֲדוּ, וְאִתְקַשְּׁרָן כְּחֲדָא. עָבְרוּ יַחְדָּיו, לְאַנְהָרָא כָּל אַנְפִּין, וּלְמֶהֱוֵי כֹּלָּא רְעוּתָא חָדָא.","הֵמָּה רָאוּ כֵּן תָּמָהוּ, סַלְקָא דַעְתָּךְ דְּאִינוּן מְלָכִים. אֶלָּא אִלֵּין מָארֵיהוֹן דְּדִינִין, דְּחֶדְוָה דִלְהוֹן לְמֶעְבַּד הַהוּא דִינָא דְּאִתְפַּקְּדוּ עֲלֵיהּ. וּכְדֵין, כַּד מְלָכִים אִזְדַּמְּנוּ תַּרְוַויְיהוּ בִּרְעוּתָא חָדָא, כְּדֵין הֵמָה רָאוּ הַהוּא רְעוּתָא דִתְרֵין עָלְמִין. כֵּן תָּמָהוּ נִבְהֲלוּ נֶחְפָּזוּ, בְּגִין דְּכֻלְּהוּ מָארֵי דְדִינָא אִתְכַּפְיָין וּמִתְעַבְרָן מֵעַלְמָא, וְלָא יָכְלֵי לְשַׁלְּטָאָה. וּכְדֵין מִתְעַבְרִין קִיּוּמֵיהוֹן, מְעַבְרִין שָׁלְטָנְהוֹן.","רִבִּי אֶלְעָזָר אָמַר, וַיִּגַשׁ אֵלָיו יְהוּדָה. מַאי טַעְמָא יְהוּדָה, בְּגִין דְּהָכִי אִצְטְרִיךְ, דְּאִיהוּ עָרַב. כְּמָא דְאַתְּ אָמֵר, כִּי עַבְדְּךָ עָרַב אֶת הַנַּעַר. וְרָזָא דְמִלָּה, יְהוּדָה וְיוֹסֵף הָכִי אִצְטְרִיכוּ לְאִתְקָרְבָא כְּחֲדָא. בְּגִין דְּיוֹסֵף אִיהוּ צַדִּיק, יְהוּדָה אִיהוּ מֶלֶךְ. וְעַל דָּא וַיִּגַּשׁ אֵלָיו יְהוּדָה. בְּגִין דְּקוּרְבָא דִלְהוֹן דְאִתְקְרִיבוּ כְּחֲדָא, גָּרַם כַּמָּה טָבִין לְעַלְמָא. גָּרַם שְׁלָמָא לְכֻלְּהוּ שִׁבְטִין. גָּרַם שְׁלָמָא בֵּינַייהוּ. גָּרַם לְיַעֲקֹב דְּאִתְקְיַּים רוּחָא דִילֵיהּ. כְּמָא דְאַתְּ אָמֵר, (בראשית מ״ה:כ״ז) וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. וְעַל דָּא קְרִיבוּ דְּדָא עִם דָּא אִצְטְרִיךְ, בְּכֻלְּהוּ סִטְרִין לְעֵילָא וְתַתָּא.","רִבִּי אַבָּא פָּתַח וְאָמַר, (תהילים מ״ח:ג׳) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ הַר צִיּוֹן יַרְכְּתֵי צָפוֹן קִרְיַת מֶלֶךְ רָב. הַאי קְרָא רָזָא דִמְהֵימְנוּתָא אִיהוּ. יְפֵה נוֹף, דָּא אִיהוּ יוֹסֵף הַצַּדִּיק, דִּכְתִיב בֵּיהּ, וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה. מְשׂוֹשׂ כָּל הָאָרֶץ, אִיהוּ חֶדְוָה וְחֵדוּ לְעֵילָא וְתַתָּא. הַר צִיּוֹן יַרְכְּתֵי צָפוֹן, בְּגִין דִּבְחוּלָקֵיהּ קָאִים מַשְׁכְּנָא דְשִׁילֹה, הַר צִיּוֹן דָּא יְרוּשָׁלַ ם. יַרְכְּתֵי צָפוֹן, הָכִי הוּא וַדַּאי לְעֵילָא וְתַתָּא.","קִרְיַת מֶלֶךְ רָב, אֲתַר אִיהוּ מְתַקְּנָא, לָקֳבֵיל מֶלֶךְ רָב, דָּא מַלְכָּא עִלָּאָה דְּכֹלָּא, קֹדֶשׁ הַקֳּדָשִׁים. דְּהָא מִתַּמָּן אַתְיָא כָּל נְהִירוּ וְכָל בִּרְכָאן וְכָל חֵידוּ דְּכֹלָּא. דְּהָא מִתַּמָּן נָהֲרִין כָּל אַנְפִּין, וּבֵי מַקְדְּשָׁא אִתְבָּרְכָא מִתַּמָּן. וְכַד אִיהִי מִתְבָּרְכָא, מִתַּמָּן נָפְקֵי בִּרְכָאן לְכָל עַלְמָא, דְּהָא כָּל עַלְמָא מִתַּמָּן אִתְבָּרְכָא.","רִבִּי יְהוּדָה וְרִבִּי יוֹסֵי אִעָרְעוּ בִּכְפַר חָנָן. עַד דְּהֲווּ יָתְבֵי בֵּי אוּשְׁפִּיזַיְיהוּ, אֲתָא חַד בַּר נָשׁ וְחַד מָטוּלָא דְחַמְרָא קַמֵיהּ וְעָאל בְּבֵיתָא. אַדְּהָכִי, אָמַר רִבִּי יְהוּדָה לְרִבִּי יוֹסֵי, הָא תָּנִינָן, דְּדָוִד מַלְכָּא הֲוָה מִתְנַמְנֵם כְּסוּס, וְשֵׁינְתֵיהּ זְעֵיר, הֵיךְ הֲוָה קָם בְּפַלְגּוּת לֵילְיָא. הַאי שִׁעוּרָא זְעֵיר אִיהוּ וְלָא הֲוָה אִתְעַר אֲפִילּוּ בִּתְלָתוּת לֵילְיָא.","אָמַר לֵיהּ, בְּשַׁעְתָּא דְּעָאל לֵילְיָא, הֲוָה יָתִיב עִם כָּל רַבְרְבֵי בֵיתֵיהּ וְדָאִין דִּינָא, וְעָסִיק בְּמִלֵּי דְאוֹרַיְיתָא. וּלְבָתַר הֲוָה נָאִים שֵׁינְתֵיהּ עַד פַּלְגוּת לֵילְיָא, וְקָם בְּפַלְגוּת לֵילְיָא וְאִתְעַר, וְאִשְׁתְּדָּל בְּפוּלְחָנָא דְמָארֵיהּ, בְּשִׁירִין וְתוּשְׁבְּחָן."],[[0,"ד\"א כי הנה המלכים נועדו:","ל\"ג זה, כי הם דברים מכופלים. וצ\"ל, ד\"א כי הנה המלכים, אמר ר' יהודה רזא דמהימנותא וכו'."],[1,"כי הנה המלכים:","אמר ר' יהודה סוד האמונה כאן. שהיא הנוקבא. כי כשנגלה הרצון, והיחוד התעטר בזו\"ן כאחד. אז שני העולמות זו\"ן, מתקשרים יחד, ונועדים יחד. זה, ז\"א, לפתוח האוצר ולהשפיע. וזה, הנוקבא, ללקוט ולאסוף לתוכה, את השפע, ואז, \u0003כי הנה המלכים נועדו,\u0004 שהם שני עולמות, עולם העליון, שהוא ז\"א, ועולם התחתון, שהיא הנוקבא."],[2,"עברו יחדיו:","משום שכל העונות שבעולם אינם נעברים להתכפר, עד שזו\"ן מתחברים יחד. כמו שכתוב, \u0003ועובר על פשע,\u0004 ועל דרך זה \u0003עברו\u0004 יחדיו, עברו העונות, נתכפרו, משום, שבהארת הזווג, מאירים פני כל, וכל העונות מתכפרים. \u0003לאתכפיא,\u0004 פירושו להתכפר, מלשון מתן בסתר \u0003יכפה\u0004 אף. (משלי כ\"א)."],[3,"ר' חייא אמר וכו':","רח\"א, סוד כתוב הזה, הוא בתקון הקרבנות. כי כשנקרב הקרבן, והכל מקבלים הספקתם, כל אחד ואחד כראוי לו, אז מתקשר הכל כאחד, ומאירים כל פנים, וקשר אחד נמצא, דהיינו זווג אחד, ואז \u0003המלכים נועדו,\u0004 שנועדו יחד לכפר על העונות להעביר אותם. ואז, \u0003המלכים נועדו,\u0004 שהם זו\"ן, שנתקשרו יחד \u0003עברו יחדיו,\u0004 היינו לכפר העונות, כדי להאיר כל פנים, ושיהיה הכל רצון אחד."],[4,"המה ראו כן תמהו:","שואל, היעלה על דעתך שהם המלכים, שהמלכים ראו ותמהו. ומשיב, לא, אלא הם בעלי הדין, ששמחתם הוא לעשות הדין שנצטוו עליו, ואז, כשהמלכים נועדו שניהם ברצון אחד, אז, \u0003המה ראו,\u0004 אותו הרצון של שני העולמות, זו\"ן, \u0003כן תמהו נבהלו נחפזו,\u0004 כי כל בעלי הדין נשקטו ונעברו מן העולם, ואינם יכולים לשלוט, ואז נעבר קיומם ונעברה שליטתם."],[5,"ר' אלעזר אמר ויגש אליו יהודה:","מה הטעם שנגש יהודה. ומשיב, משום שכך צריך להיות, כי הוא ערב, כמש\"א, כי עבדך ערב את הנער. וסוד הדבר, יהודה ויוסף היו צריכים להתקרב יחד, משום שיוסף הוא צדיק, דהיינו יסוד דז\"א, יהודה הוא מלך, דהיינו מלכות, נוקבא דז\"א, וע\"כ ויגש אליו יהודה, משום שהקרבה שלהם שנקרבו יחד, סבב הרבה טובות לעולם, סבב שלום לכל השבטים, סבב שלום ביניהם עצמם, דהיינו בין יהודה ליוסף, סבב ליעקב שהרוח שלו חזר לתחיה, כמש\"א ותחי רוח יעקב אביהם. ועל כן, קרבת זה בזה היה נצרך בכל הצדדים, למעלה, ולמטה."],[6,"ר' אבא פתח ואמר, יפה נוף משוש כל וגו':","מקרא זה הוא סוד האמונה, \u0003יפה נוף\u0004 זהו יוסף הצדיק. שכתוב בו, ויהי יוסף יפה תאר ויפה מראה. \u0003משוש כל הארץ,\u0004 הוא ששון ושמחה למעלה ולמטה. \u0003הר ציון ירכתי צפון,\u0004 משום שבחלקו של יוסף עומד משכן שילה. \u0003הר ציון\u0004 זהו ירושלים, דהיינו הנוקבא, \u0003ירכתי צפון,\u0004 כן הוא ודאי למעלה ולמטה, אשר הן בית המקדש של מעלה, שהיא הנוקבא, והן בית המקדש של מטה, הם בבחינת צפון, דהיינו בהארת השמאל דבינה, שה\"ס הארת החכמה."],[7,"קרית מלך רב, אתר וכו':","מקום הוא המתוקן לפני מלך רב, זהו מלך העליון על כל קדש הקדשים, כי משם באים כל האורה וכל הברכות וכל חדות כל, שמשם מאירים כל פנים, ובית המקדש מתברך משם, וכשהיא מתברכת יוצאות משם הברכות לכל העולם, כי כל העולם מתברך משם."],[8,"ר' יהודה ור' יסי וכו':","ר\"י ור\"י נפגשו בכפר חנן, בעוד שהיו יושבים במלונם, בא אדם אחד, ומשא חמור אחד לפניו, ונכנס לבית. בתוך כך, אמר ר' יהודה לר' יוסי, הרי למדנו, שדוד המלך היה נם כסוס ושנתו מועטת, ואם כן, איך היה קם בחצות לילה, הרי שיעור הזה, ששים נשימות של שינת הסוס, מעט הוא, ולא היה מקיץ אפילו בשליש לילה."],[9,"אמר ליה בשעתא וכו':","א\"ל בשעה שבא לילה היה יושב עם כל גדולי ביתו ודן דינים, ועסק בדברי תורה, כלומר, שלא הלך לישן בתחילת הלילה אלא סמוך לחצות לילה, ואחר כך היה ישן את שנתו עד חצות לילה, וקם בחצות לילה, והתעורר ועסק בעבודת רבונו בשירות ותשבחות."]],[[0,"","דָּבָר אַחֵר כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ - זֶה יְהוּדָה וְיוֹסֵף שֶׁהִזְדַּמְּנוּ לְהִתְוַכֵּחַ זֶה עִם זֶה, לְהִתְוַכֵּחַ שְׁנֵיהֶם יַחַד, מִשּׁוּם שֶׁיְּהוּדָה הָיָה מֶלֶךְ וְיוֹסֵף הָיָה מֶלֶךְ, וּשְׁנֵיהֶם בָּאוּ יַחַד לְהִתְוַכֵּחַ זֶה עִם זֶה, זֶה עַל בִּנְיָמִין - וְזֶה עַל בִּנְיָמִין."],[1,"","כִּי הִנֵּה הַמְּלָכִים, אָמַר רַבִּי יְהוּדָה, סוֹד הָאֱמוּנָה כָּאן, שֶׁהֲרֵי כְּשֶׁנִּמְצָא הָרָצוֹן, וְהַקֶּשֶׁר מִתְעַטֵּר יַחַד, אֲזַי שְׁנֵי עוֹלָמוֹת נִקְשָׁרִים יַחַד וּמִזְדַּמְּנִים יַחַד, זֶה לִפְתֹּחַ אֶת הָאוֹצָר - וְזֶה לְלַקֵּט וְלִכְנֹס לְתוֹכוֹ. וְאָז, כִּי הִנֵּה הַמְּלָכִים נוֹעֲדוּ, שְׁנֵי עוֹלָמוֹת קְדוֹשִׁים, הָעוֹלָם הָעֶלְיוֹן וְהָעוֹלָם הַתַּחְתּוֹן."],[2,"","עָבְרוּ יַחְדָּו, סוֹד הַדָּבָר - שֶׁכַּאֲשֶׁר מִתְחַבְּרִים יַחַד, אֲזַי עָבְרוּ יַחְדָּו, מִשּׁוּם שֶׁכָּל הַחֲטָאִים שֶׁל הָעוֹלָם לֹא מִתְבַּטְּלִים לְהִכָּנַע עַד שֶׁמִּתְחַבְּרִים יַחַד, כַּכָּתוּב וְעֹבֵר עַל פֶּשַׁע, וְעַל כֵּן עָבְרוּ יַחְדָּו. עָבְרוּ - אוֹתָם הַחֲטָאִים הִתְכַּפְּרוּ, מִשּׁוּם שֶׁהִנֵּה אָז כָּל הַפָּנִים מְאִירוֹת וְכָל הַחֲטָאִים הִתְבַּטְּלוּ."],[3,"","רַבִּי חִיָּיא אָמַר, הַסּוֹד הַזֶּה הוּא בְּתִקּוּן הַקָּרְבָּן, שֶׁהֲרֵי כַּאֲשֶׁר נִקְרָב הַקָּרְבָּן, וְכֻלָּם מְקַבְּלִים הַסְפָּקָתָם כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, אָז הַכֹּל נִקְשָׁר יַחַד וְכָל הַפָּנִים מְאִירוֹת, וְנִמְצָא קֶשֶׁר אֶחָד, וְאָז הַמְּלָכִים נוֹעֲדוּ וּמִזְדַּמְּנִים יַחַד לְכַפֵּר עַל הַחֲטָאִים, לְהַעֲבִיר אוֹתָם. וְאָז הַמְּלָכִים נוֹעֲדוּ וְנִקְשָׁרִים יַחַד. עָבְרוּ יַחְדָּו, לְהָאִיר כָּל הַפָּנִים, וְשֶׁיִּהְיֶה הַכֹּל רָצוֹן אֶחָד."],[4,"","הֵמָּה רָאוּ כֵּן תָּמָהוּ, הֲתַעֲלֶה עַל דַּעְתְּךְ שֶׁהֵם מְלָכִים? אֶלָּא אֵלּוּ בַּעֲלֵי הַדִּינִים, שֶׁשִּׂמְחָתָם לַעֲשׂוֹת אֶת הַדִּין הַהוּא שֶׁהִצְטַוּוּ עָלָיו. וְאָז, כְּשֶׁהַמְּלָכִים מִזְדַּמְּנִים שְׁנֵיהֶם בְּרָצוֹן אֶחָד, אָז הֵמָּה רָאוּ אוֹתוֹ הָרָצוֹן שֶׁל שְׁנֵי עוֹלָמוֹת. כֵּן תָּמָהוּ נִבְהֲלוּ נֶחְפָּזוּ, מִשּׁוּם שֶׁכָּל בַּעֲלֵי הַדִּין נִכְנָעִים וְעוֹבְרִים מִן הָעוֹלָם וְלֹא יְכוֹלִים לִשְׁלֹט, וְאָז קִיּוּמָם עוֹבֵר, וּמַעֲבִירִים אֶת שִׁלְטוֹנָם."],[5,"","רַבִּי אֶלְעָזָר אוֹמֵר: וַיִּגַּשׁ אֵלָיו יְהוּדָה. מָה הַטַּעַם יְהוּדָה? מִשּׁוּם שֶׁכָּךְ צָרִיךְ, שֶׁהוּא עָרֵב, כְּמוֹ שֶׁנֶּאֱמַר כִּי עַבְדְּךְ עָרַב אֶת הַנַּעַר. וְסוֹד הַדָּבָר - יְהוּדָה וְיוֹסֵף כָּךְ הִצְטָרְכוּ לְהִתְקָרֵב יַחַד, מִשּׁוּם שֶׁיּוֹסֵף הוּא צַדִּיק, יְהוּדָה הוּא מֶלֶךְ, וְעַל כֵּן וַיִּגַּשׁ אֵלָיו יְהוּדָה, מִשּׁוּם שֶׁהַקִּרְבָה שֶׁלָּהֶם, שֶׁהִתְקָרְבוּ יַחַד, גָּרְמָה לְכַמָּה טוֹבוֹת בָּעוֹלָם, גָּרְמָה שָׁלוֹם לְכָל הַשְּׁבָטִים, גָּרְמָה לְשָׁלוֹם בֵּינֵיהֶם, גָּרְמָה לְיַעֲקֹב שֶׁהִתְקַיְּמָה רוּחוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מה) וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. וְעַל כֵּן הַהִתְקָרְבוּת שֶׁל זֶה עִם זֶה הֻצְרְכָה בְּכָל הַצְּדָדִים, לְמַעְלָה וּלְמַטָּה."],[6,"","רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים מח) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ הַר צִיּוֹן יַרְכְּתֵי צָפוֹן קִרְיַת מֶלֶךְ רָב. הַפָּסוּק הַזֶּה הוּא סוֹד הָאֱמוּנָה. יְפֵה נוֹף - זֶהוּ יוֹסֵף הַצַּדִּיק, שֶׁכָּתוּב בּוֹ וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה. מְשׂוֹשׂ כָּל הָאָרֶץ - הוּא חֶדְוָה וְשִׂמְחָה לְמַעְלָה וּלְמַטָּה. הַר צִיּוֹן יַרְכְּתֵי צָפוֹן - מִשּׁוּם שֶׁבְּחֶלְקוֹ עוֹמֵד מִשְׁכַּן שִׁילֹה. הַר צִיּוֹן - זוֹ יְרוּשָׁלַיִם. יַרְכְּתֵי צָפוֹן, כָּךְ זֶה וַדַּאי לְמַעְלָה וּלְמַטָּה."],[7,"","קִרְיָת מֶלֶךְ רָב - מָקוֹם מְתֻקָּן הוּא כְּנֶגֶד מֶלֶךְ רָב, זֶה הַמֶּלֶךְ הֶעֶלְיוֹן שֶׁל הַכֹּל, קֹדֶשׁ הַקְּדָשִׁים, שֶׁהֲרֵי מִשָּׁם בָּא כָּל הָאוֹר וְכָל הַבְּרָכוֹת וְכָל הַשִּׂמְחָה שֶׁל הַכֹּל, שֶׁהֲרֵי מִשָּׁם כָּל הַפָּנִים מְאִירוֹת, וּבֵית הַמִּקְדָּשׁ מִתְבָּרֵךְ מִשָּׁם, וּכְשֶׁהִיא מִתְבָּרֶכֶת, מִשָּׁם יוֹצְאוֹת בְּרָכוֹת לְכָל הָעוֹלָם, שֶׁהֲרֵי מִשָּׁם כָּל הָעוֹלָם מִתְבָּרֵךְ."],[8,"","רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי נִפְגְּשׁוּ לִכְפַר חָנָן. בְּעוֹדָם יוֹשְׁבִים בְּבֵית מְלוֹנָם, בָּא אִישׁ אֶחָד, וּמַשָּׂא שֶׁל חֲמוֹר לְפָנָיו, וְנִכְנַס לַבַּיִת. בֵּין כָּךְ אָמַר רַבִּי יְהוּדָה לְרַבִּי יוֹסִי, הִנֵּה שָׁנִינוּ שֶׁדָּוִד הַמֶּלֶךְ הָיָה מִתְנַמְנֵם כְּמוֹ סוּס וּשְׁנָתוֹ מוּעֶטֶת, אֵיךְ הָיָה קָם בַּחֲצוֹת הַלַּיְלָה, הַשִּׁעוּר הַזֶּה הוּא קָטָן, וְלֹא הָיָה מִתְעוֹרֵר אֲפִלּוּ בִּשְׁלִישׁ הַלַּיְלָה?"],[9,"","אָמַר לוֹ, בְּשָׁעָה שֶׁנִּכְנַס הַלַּיְלָה, הָיָה יוֹשֵׁב עִם כָּל גְּדוֹלֵי בֵיתוֹ וְדָן אֶת הַדִּין וְעוֹסֵק בְּדִבְרֵי תוֹרָה, וְאַחַר כָּךְ הָיָה יָשֵׁן שְׁנָתוֹ עַד חֲצוֹת הַלַּיְלָה, וְקָם בַּחֲצוֹת הַלַּיְלָה וּמִתְעוֹרֵר, וּמִשְׁתַּדֵּל בַּעֲבוֹדַת רִבּוֹנוֹ בְּשִׁירִים וְתִשְׁבָּחוֹת."]]],[["אַדְהָכִי אָמַר הַהוּא בַּר נָשׁ, וְכִי הַאי מִלָּה דְקָאַמְרִיתּוּ, הָכִי הוּא. רָזָא דְמִלָּה הָכָא, דְּהָא דָוִד מַלְכָּא חַי וְקַיָּים לְעָלַם וּלְעָלְמֵי עָלְמִין. וְדָוִד מַלְכָּא הֲוָה נָטִיר כָּל יוֹמוֹי דְּלָא יִטְעַם טַעַם מִיתָה. בְּגִין דְּשֵׁינְתָא חַד מִשִּׁתִּין בְּמִיתָה אִיהוּ. וְדָוִד בְּגִין דּוּכְתֵּיהּ דְּאִיהוּ חַי, לָא הֲוָה נָאִים אֶלָּא שִׁיתִּין נִשְׁמֵי. דְּעַד שִׁתִּין נִשְׁמֵי חָסֵר חַד, אִיהוּ חַי. מִתַּמָּן וּלְהָלְאָה, טָעִים בַּר נָשׁ טַעְמָא דְמוֹתָא, וְשַׁלִּיט בֵּיהּ סִטְרָא דְרוּחַ מְסָאֲבָא.","וְדָא הֲוָה נָטִיר דָּוִד מַלְכָּא, דְּלָא יִטְעַם טַעְמָא דְמוֹתָא, וְשַׁלִּיט (ס\"א דלא ישליט) בֵּיהּ סִטְרָא דְרוּחָא אָחֳרָא, בְּגִין דְּשִׁתִּין נִשְׁמֵי חָסֵר חַד, אִיהוּ רָזָא דְחַיִּים דִּלְעֵילָא. עַד שִׁתִּין נִשְׁמֵי, דְּאִינוּן שִׁתִּין (ד\"א ל\"ג חסר חד נשמי) נִשְׁמֵי עִלָּאִין, וְאִילֵין רָזָא דִלְהוֹן, דְּתַלְיָין בְּהוֹן חַיֵּי. וּמִכָּאן וּלְתַתָּא, רָזָא דְמוֹתָא הוּא.","וְעַל דָּא, דָּוִד מַלְכָּא הֲוָה מְשַׁעֵר שִׁעוּרָא דְלֵילְיָא, בְּגִין דְּיִתְקַיֵּים בַּחַיִּים, דְּלָא יִשְׁלוֹט בֵּיהּ טַעְמָא דְמוֹתָא. וְכַד אִתְפְּלִיג לֵילְיָא, הֲוָה דָּוִד מִתְקַיֵּים בְּאַתְרֵיהּ. בְּגִין דְּכַד אִתְעַר פַּלְגוּ לֵילְיָא וְכִתְרָא קַדִּישָׁא אִתְעַר, בָּעָא דְלָא לְאַשְׁכָּחָא לֵיהּ לְדָוִד מִתְקַשַּׁר בְּאֲתַר אָחֳרָא, בְּאֲתַר דְּמוֹתָא.","בְּגִין דְּכַד אִתְפְּלִיג לֵילְיָא וּקְדוּשָּׁה עִלָּאָה אִתְעַר, וּבַר נָשׁ דְּנָאִים בְּעַרְסֵיהּ וְלָא אִתְעַר לְאַשְׁגָּחָא בִּיקָרָא דְמָארֵיהּ. הָא אִיהוּ אִתְקַשַּׁר בְּרָזָא דְמוֹתָא וּמִתְדַּבַּק בְּאֲתַר אָחֳרָא, וְעַל דָּא דָּוִד מַלְכָּא הֲוָה קָאִים לְאַשְׁגָּחָא בִּיקָרָא דְמָארֵיהּ תָּדִיר. חַי לְגַבֵּי חַי, וְלָא נָאִים בְּשֵׁינְתָא לְטָעֲמָא טַעְמָא דְמוֹתָא. וּבְגִין כָּךְ, הֲוָה מִתְנַמְנֵם כְּסוּס שִׁתִּין נִשְׁמֵי, וְלָא בִּשְׁלִימוּ.","אָתוּ רִבִּי יְהוּדָה וְרִבִּי יוֹסֵי וּנְשָׁקוּהָ, אָמְרוּ לֵיהּ, מַה שְּׁמָךְ. אָמַר לְהוֹן, חִזְקִיָּה. אָמְרוּ לֵיהּ, יִתְיַישֵּׁר חֵילָךְ וְיִתְתַּקַּף אוֹרַיְיתָךְ. יְתִיבוּ. אָמַר רִבִּי יְהוּדָה, הוֹאִיל וְשָׁרִית, אֵימָא לָן מֵהַנֵּי רָזִין עִלָּאִין דְּקָאֲמַרְתְּ.","פָּתַח וְאָמַר, (משלי ג׳:י״ט) ה' בְּחָכְמָה יָסַד אֶרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, חָמָא דְלָא יָכִיל לְאִתְקָיְימָא, עַד דְּבָרָא אוֹרַיְיתָא. בְּגִין דְּמִנָּהּ נָפְקִין כָּל נִמּוּסִין עִלָּאִין וְתַתָּאִין, וּבָהּ קָיְימֵי עִלָּאֵי וְתַתָּאֵי. הֲדָא הוּא דִכְתִיב, ה' בְּחָכְמָה יָסַד אָרֶץ כּוֹנִן שָׁמַיִם בִּתְבוּנָה. דְּהָא בְּחָכְמָה קָיְימִין כָּל קִיּוּמִין דְּעַלְמָא, וְכֻלְּהוּ נָפְקֵי מִגַּוָּהּ.","דָּבָר אַחֵר ה' בְּחָכְמָה יָסַד אֶרֶץ, עַלְמָא עִלָּאָה לָא אִתְבְּרֵי אֶלָּא מִגּוֹ חָכְמָה. וְעַלְמָא תַּתָּאָה לָא אִתְבְּרֵי אֶלָּא מִגּוֹ חָכְמָה תַּתָּאָה. וְכֻלְּהוּ נָפְקָן מִגּוֹ חָכְמָה עִלָּאָה וּמִגּוֹ חָכְמָה תַּתָּאָה. כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. כּוֹנֵן, מַאי כּוֹנֵן. אֶלָּא, כּוֹנֵן כָּל יוֹמָא וְיוֹמָא וְלָא פָּסִיק, וְלָא אִתְתַּקַּן בְּזִמְנָא חָדָא, אֶלָּא בְּכָל יוֹמָא וְיוֹמָא אַתְקִין לֵיהּ.","וְהַיְינוּ רָזָא דִּכְתִיב, (איוב ט״ו:ט״ו) וְשָׁמַיִם לֹא זַכּוּ בְעֵינָיו. וְכִי סַלְקָא דַעְתָּךְ, דִּגְרִיעוּתָא אִיהוּ מִשָּׁמַיִם, אֶלָּא חֲשִׁיבוּ מִשָּׁמַיִם אִיהוּ, בְּגִין חֲבִיבוּ וּרְעוּ סַגְיָא, דְּקוּדְשָׁא בְּרִיךְ הוּא רָעֵי בְּהוּ, וַחֲבִיבוּתַיְהוּ לְגַבֵּיהּ. דְּהָא אַף עַל גַּב דְּאִיהוּ מַתְקִין לוֹן כָּל יוֹמָא וְיוֹמָא, לָא דָמֵי בְּעֵינוֹי דְּאִינוּן מִתְתַּקְנָן כְּדְקָא יְאוּת. בְּגִין דִּרְחִימוּתָא דִלְהוֹן לְגַבֵּיהּ, וּרְעוּתֵיהּ לְאַנְהָרָא לוֹן תָּדִיר בְּלָא פְּסִיקוּ. דְּהָא עַלְמָא דְאָתֵי אַפִּיק נְהוֹרִין זְהִירִין כָּל יוֹמָא וְיוֹמָא תָּדִיר בְּלָא פְּסִיקוּ, בְּגִין לְאַנְהָרָא לוֹן תָּדִיר. וְעַל דָּא לא זַכּוּ בְּעֵינָיו. לא זַכּוּ בִּלְחוֹדוֹי לָא כְּתִיב, אֶלָּא לא זַכּוּ בְעֵינָיו. וּבְגִין כָּךְ, כּוֹנֵן שָׁמַיִם בִּתְבוּנָה.","מַאן שָׁמַיִם. דָּא הוּא רָזָא דְּאֲבָהָן, וְרָזָא דְּאֲבָהָן דָּא הוּא יַעֲקֹב דְּאִיהוּ כְּלָלָא דִלְהוֹן. בְּגִין דְּיַעֲקֹב תּוּשְׁבַּחְתָּא דְּאֲבָהָן אִיהוּ, וְאִיהוּ קָיְימָא לְאַנְהָרָא עַל עַלְמָא.","וּבְגִין דְּאִיהוּ אִסְתָּלַּק גּוֹ עַלְמָא דְאָתֵי, נָפַק מִנֵּיהּ עֲנָפָא חָדָא שַׁפִּירָא בְּחֵיזוּ, וְכָל נְהוֹרִין מִינֵיהּ נָפְקִין. וְכָל שָׂבְעָא וּמְשַׁח רְבוּ לְאַנְהָרָא לְאַרְעָא, וּמַאן אִיהוּ. דָּא יוֹסֵף הַצַּדִּיק, דְּאִיהוּ יָהִיב שָׂבְעָא לְכָל עַלְמָא, וְעַלְמָא מִנֵּיהּ אִתְּזָן. וּבְגִין כָּךְ, קוּדְשָׁא בְּרִיךְ הוּא כָּל מַה דְּעָבַד בְּעַלְמָא, כֹּלָּא אִיהוּ בְּרָזָא עִלָּאָה, וְכֹלָּא כְּדְקָא חָזֵי."],[[0,"אדהכי אמר וכו':","בתוך זה אמר אותו אדם, וכי כך הוא דבר זה שאמרתם, סוד הדבר הוא כאן, כי דוד המלך חי וקים לעולם ולעולמי עולמים, ודוד המלך היה שומר עצמו כל ימיו שלא יטעם טעם מיתה, משום ששינה הוא אחד מששים במיתה, ודוד, משום מקומו, שהוא \u0003חי,\u0004 לא ישן אלא ששים נשימות, כי עד ששים נשימות חסר א' הוא חי, משם ולהלאה, טועם האדם טעם המות, ושולט עליו הצד של רוח הטומאה."],[1,"ודא הוה נטיר וכו':","וזה שהיה דוד המלך שומר את עצמו שלא יטעם טעם המות, ולא ישלוט עליו הצד של רוח האחר, משום שששים נשימות חסר אחת, הוא סוד, שהחיים שלמעלה, עד ששים נשימות הן ששים נשימות עליונות, וסודם של אלו, הוא, שהחיים תלוים בהם, ומכאן ולמטה הוא סוד המות."],[2,"וע\"ד דוד מלכא וכו':","ועל כן היה דוד המלך משער השעור של הלילה, עד חצות, כדי שיתקיים בחיים, ולא ישלוט עליו טעם המות. וכשנחצה הלילה היה דוד מתקיים במקומו, היינו במדרגתו, שהוא חי וקיים, כי הקיץ משנתו ואמר שירות ותשבחות. כי כשנתעורר חצות לילה, וכתר הקדוש נתעורר, דהיינו הנוקבא, צריך שלא ימצא את דוד מתקשר במקום אחר, במקום המות."],[3,"בגין דכד אתפליג וכו':","משום כשנחצה הלילה, וקדושה העליונה נתעורר, ואדם הישן במטתו אינו מתעורר, דהיינו שאינו מקיץ משנתו, להשגיח בכבוד רבונו, הרי הוא מתקשר בסוד המות, ומתדבק במקום אחר, בס\"א. ועל כן היה קם תמיד דוד המלך בחצות לילה, להשגיח בכבוד רבונו חי אצל חי, ולא נם בשנתו עד לטעום טעם המות, ומשום זה היה נם כסוס ששים נשימות ולא בשלמות, שהיו חסרים אחת."],[3,"","ביאור המאמר. בתחילה נבאר שינה ויקיצה בשורשם. והנה שינה, פירושו סתימת העינים, שהם המוחין, כמו הישן השוכב בעצימת העינים בלי דעת. ושורשו נמשך, משליטת הארת קו השמאל שהיא חכמה, בעת שהיא במחלוקת עם קו הימין, שהיא חסדים, שמטעם שאין החכמה יכולה להאיר בלי חסדים, המוחין נסתמים. שה\"ס השינה. והיקיצה משינה, נמשכת מקו אמצעי, כי מצב השינה נמשכת עד עלית קו האמצעי עם המסך דחירק שבו, שה\"ס נקודת מנעולא, (כנ\"ל פרשת לך דף י\"ג ד\"ה ונתבאר, עש\"ה) הממעט את קו השמאל ומכללהו בימין, שהחכמה שבשמאל נכללת בחסדים שבימין, ואז נפתחים המוחין והחכמה יכולה להאיר, שה\"ס היקיצה."],[3,"","ומכאן תבין ההפרש הגדול בין חג\"ת דז\"א שמחזה שלו ולמעלה, לבין נה\"י שמחזה שלו ולמטה. כי ג' קוין דז\"א נקראים חג\"ת שבעת שהחסד הוא במחלוקת עם הגבורה, נמשך לו השינה, וכשהת\"ת שלו שהוא קו אמצעי מכריע ועושה שלום ביניהם עם כח המסך דמנעולא שבו, הוא ממשיך \u0003היקיצה,\u0004 דהיינו שהמוחין נפתחים, כי אז החכמה שבשמאל נכללת עתה בחסדים שבימין, ויכולה להאיר כנ\"ל. הרי שהמסך דמנעולא נמצא בת\"ת, שהוא קו אמצעי, ותדע שהיא סוד \u0003נקודת החזה\u0004 אשר בת\"ת, ששם משכן מסך דמנעולא, העושה שלום בין הקוין."],[3,"","ונודע שהמות נמשך ממנעולא, בסוד \u0003לא זכי הא רע\u0004 (לעיל בהקסה\"ז דף קכ\"ד אות קכ\"ג ד\"ה אמאי ע\"ש) שה\"ס גילוי הצמצום שבמלכות שאינה ראויה לקבל אור החכמה, שהוא אור החיים, וע\"כ בגילויה מת האדם, שאור החיים פורח ממנו. אבל כאן בסוד התקון דיקיצה, הוא בהיפך, שהיא נעשה לגורם כל החיים, כי לולא המנעולא שבקו אמצעי שבנקודת החזה, לא היה יכול ז\"א להקיץ משנתו, והעינים שה\"ס החכמה היו סתומים לעולם, מחמת שאינה מאירה בלי חסדים, הרי שכל גילוי המוחין, במסך דמנעולא תלוים."],[3,"","עתה תראה ההפרש בין חג\"ת שמחזה ולמעלה לנה\"י שמחזה ולמטה. כי אין המסך והדין שבו יכול לפעול משהו למעלה ממקום מציאותו, ולפיכך החג\"ת שלמעלה מנקודת החזה אין בו מהדין של המנעולא כלום, שה\"ס המות. כנ\"ל. אבל נה\"י דז\"א הנמצאים למטה מנקודת החזה, כבר המות שבמנעולא פועל עליהם, אלא, כמו שנתבאר, שיש כאן, לנקודת המנעולא שבחזה, פעולה הפוכה, שהיא, בסוד תקון היקיצה, כי נעשתה כאן לגורם החיים, מכח ההכרעה, שהיא בלתי אפשרית זולתה. ולפיכך גם הנה\"י בסוד החיים והקדושה, ואין כח המות שולט בהם ח\"ו אף משהו."],[3,"","והנה הנוקבא, שנקראת \u0003לילה,\u0004 מקבלת בנין ספירותיה מז\"א, ועל כן נחלקת גם היא על נקודת החזה כמוהו שה\"ס נקודת חצות לילה, שמחזה ולמעלה דהיינו שש שעות הראשונות עד חצות לילה, אין שם כח הדין והמות מנקודת המנעולא כלל, אלא מנקודת החזה ולמטה, דהיינו שש שעות השניות, אם יש בהם תקון היקיצה, נעשו גם הם חיים וקדושה כמו החג\"ת שלמעלה כנ\"ל, אבל אם אין בהם תקון היקיצה, שה\"ס ההכרעה שבקו אמצעי, אלא שנמשכת שליטת השמאל בלי ימין, שה\"ס השינה, הנה אז, נתעורר כח המות שבמנעולא שבנקודת החזה, ונמצאים הנה\"י שמחזה ולמטה דהיינו שש שעות השניות אחר חצות לילה, שהם בשליטת המות והס\"א. אמנם \u0003מלכותא דדוד\u0004 ה\"ס מחזה ולמעלה של הנוקבא דהיינו שש שעות הראשונות לפני חצות לילה, כמ\"ש לעיל, (בראשית א' דף ק\"י ד\"ה מלכותא דדוד ע\"ש כל ההמשך) בסוד רביעי לאבות שהם חג\"ת."],[3,"","וזה אמרו. \u0003רזא דמלה הכא, דהא דוד מלכא חי וקיים יעלם ולעלמי עלמין,\u0004 כי מקומו מחזה ולמעלה של הנוקבא, שה\"ס שש שעות הראשונות שלפני חצות, ששם כולו חיים, ואין כח הדין והמות שבנקודת המנעולא שבחזה, יכול להגיע שם אפילו משהו, הרי שהוא חי וקיים. \u0003ודוד מלכא הוה נטיר כל יומוי דלא יטעום טעם מיתה\u0004 דהיינו שהיה שומר עצמו שלא ימשיך בשינה לאחר חצות לילה, ששם כבר שולט המות, \u0003בגין דשינתא חד משתין במיתה,\u0004 כי מכח התכללות הספירות זה בזה, יש ששה ספירות חג\"ת נה\"י שכל אחת כלולה מעשר, שה\"ס ששים נשימות מחזה ולמעלה, וכן ששה ספירות חג\"ת נה\"י שה\"ס ששים נשימות מחזה ולמטה. וכיון שנקודת המנעולא, שהיא גורם המות, עומדת בנקודת החזה, שהוא מלכות דיסוד שמחזה ולמעלה, נמצא שהישן בשש שעות הראשונות שבלילה יש לו שם גורם המות בספירה אחת האחרונה מששים הספירות. הרי שהשינה אחד מששים ממיתה, כלומר, שבספירה אחת מששים שבה יש מיתה, שהיא נקודת החזה. שהיא העשירית של ספירת היסוד."],[3,"","וזה אמרו, \u0003דעד שתין נשמי חסר חד איהו חי,\u0004 שהם שש שעות שכל אחת כלולה מעשר, והם ששים, דהיינו שתין נשמי, שמלפני נקודת חצות לילה, שהיא נקודת החזה שבנוקבא, ששם החיים בלי שום כח דין כלל, אבל \u0003חסר חד\u0004 דהיינו העשירית שביסוד, שהיא נקודת חצות לילה עצמה, ששם שוכנת המנעולא, שהוא גורם המיתה, כנ\"ל, הרי שהחיים הם רק בששים חסר אחת. וחולק על ר' יהודה. שאמר ששתין נשמי הוא שיעור מועט. וז\"ש, \u0003מתמן ולהלאה טעים בר נש טעמא דמותא,\u0004 דהיינו שש שעות השניות, כי כח המות שבנקודת החצות, שהיא המנעולא, שולט על שש שעות שלאחריה, וע\"כ הישן בהם טועם בהכרח טעם המות, וז\"ש \u0003איהו רזא, דחיים דלעילא עד שתין נשמי,\u0004 שהחיים שלמעלה אינו נמשך יותר מששים נשימות, דהיינו עד נקודת החזה, שהיא נקודת חצות לילה, \u0003דאינון שתין נשמי עלאין,\u0004 שהם ששים נשימות העליונות, דהיינו שלמעלה מחזה, שאין כח הדין פועל כלום למעלה ממקום מציאותו כנ\"ל."],[3,"","וז\"ש וע\"ד \u0003דוד מלכא הוה משער שעורא דליליא\u0004 וכו', דהיינו שהיה ישן שתין נשמי חסר אחת, שה\"ס נקודת חצות לילה שהקיץ בה ולא ישן, דהיינו שהיה ממשיך אליה את \u0003תקון היקיצה,\u0004 המהפך את נקודת המנעולא שבחצות לילה, ומה שהיתה גורם המות נעשתה לגורם החיים כנ\"ל. \u0003בגין דכד אתפליג ליליא וקדושה עלאה אתער,\u0004 דהיינו שנעשה למעלה תקון היקיצה, על ידי קו אמצעי, המהפך את נקודת החזה שבנוקבא ממות לגורם החיים, שהוא מטומאה לקדושה, \u0003ובר נש דנאים בערסיה ולא אתער לאשגחא וכו' אתקשר ברזא דמותא,\u0004 כי אותו אדם הישן אז, נמצא ממשיך עי\"ז את שליטת השמאל שהיא שורש השינה, ונקודת המנעולא שבנקודת החצות, נשארת בעדו לגורם המיתה, כי לא נכלל בתקון היקיצה המהפכה ממות לחיים, הרי \u0003שנתקשר ברזא דמותא.\u0004 שהיא שליטת הס\"א והטומאה. וע\"ד, \u0003דוד מלכא וכו' חי לגבי חי,\u0004 כי מדרגתו הוא \u0003חי,\u0004 שהיה מרכבה לבחינת מחזה ולמעלה בסוד רביעי לאבות שאין כח הדין והמות שבנקודת החזה פועל כלום למעלה ממקום מציאותו כנ\"ל. וכשקם ועשה תקון היקיצה, נעשה מרכבה לתקון זה שבנקודת החזה שבנוקבא המתעורר באותו זמן, שה\"ס \u0003חי,\u0004 שהנקודה מוחזרת ממות לחיים כנ\"ל. \u0003ובגין כך הוה מתנמנם כסוס שתין נשמי\u0004 דהיינו ששה שעות שמלפני נקודת החצות, ולא \u0003בשלימו,\u0004 כי בנקודת החצות לא ישן, שה\"ס אחד מששים במיתה, כנ\"ל, אלא שהחזירה ממות לחיים על ידי היקיצה, כמבואר."],[4,"אתו ר' יהודה וכו':","באו ר' יהודה ור' יוסי ונשקו אותו, כי גילה להם ביאור חדש בתקון חצות. אמרו לו מה שמך. אמר להם חזקיה, אמרו לו יתישר כחך ויתחזק תורתך. ישבו. אמר ר' יהודה, כיון שפתחת, אמור לנו מאלו סודות העליונים שאתה אומר."],[5,"פתח ואמר, ה' בחכמה יסד ארץ וגו':","בוא וראה כשברא הקב\"ה את העולם ראה שאינו יכול להתקיים. כי העולם נברא בשליטת קו שמאל, שה\"ס חכמה בלי חסדים, ואין החכמה מאירה בלי חסדים, וע\"כ לא יכול להתקיים. עד שברא את התורה, שהיא קו האמצעי, שנק' ז\"א ונק' תורה, שהכליל ב' הקוין ימין ושמאל זה בזה, ונכללה החכמה בחסדים, ואז האירה החכמה, אשר ממנה דהיינו מקו אמצעי, יוצאים כל הנהגות העליונים והתחתונים, ובה מתקיימים העליונים והתחתונים, וזהו שכתוב \u0003הוי\"ה,\u0004 שהוא ז\"א, שה\"ס קו אמצעי, בחכמה \u0003יסד\u0004 ארץ וגו', הוא \u0003שיסד\u0004 הארץ בחכמה, כי הלביש החכמה בחסדים, ונתקימה הארת החכמה בעולם. ובחכמה מתקימים כל קיומי העולם והכל יוצאים ממנה. כמ\"ש כולם בחכמה עשית."],[6,"ד\"א ה' בחכמה יסד ארץ וגו':","עולם העליון, שהיא תבונה, לא נברא אלא על ידי חכמה, ועולם התחתון שהיא הנוקבא, לא נברא אלא מתוך חכמה תחתונה, שהיא החכמה המתלבשת בנוקבא. נמצא, שכולם יצאו מחכמה העליונה. וחכמה תחתונה. \u0003כונן שמים בתבונה\u0004 שואל כתוב \u0003כונן,\u0004 מהו כונן, ומשיב, אלא, \u0003כונן,\u0004 הוא תבונה, המכוננת את ז\"א, הנקרא שמים, בכל יום ויום ואינו מפסיק. ולא נתתקן בפעם אחת אלא בכל יום ויום מתקן אותו."],[7,"והיינו רזא דכתיב וכו':","והוא הסוד שכתוב, ושמים לא זכו בעיניו. וכי יעלה על דעתך שהוא חסרון לשמים, אלא יתרון הוא לשמים, שהוא משום אהבה ותשוקה הגדולה שהקב\"ה שהוא תבונה, חפץ בשמים שהוא ז\"א, ואהבתו אליו, ואע\"פ שהוא מתקן אותם בכל יום ויום, אינם נראים בעיניו כמתוקנים כראוי, מפני שאהבתו אליו, וחפצו להאיר להם תמיד בלי הפסק. ומפרש, כי עולם הבא, שהוא תבונה, מוציא אורות מתנוצצים בכל יום ויום תמיד בלי הפסק, כדי להאיר אליהם תמיד. ועל כן, \u0003לא זכו בעיניו,\u0004 שלא כתוב \u0003לא זכו,\u0004 בלבד, אלא, לא זכו \u0003בעיניו\u0004, להורות, שבאמת הם זכים, אלא מתוך התשוקה להשפיע להם נראים לו כאינם זכים, כמבואר. ומשום זה, אומר הכתוב, כונן שמים בתבונה."],[8,"מאן שמים וכו':","שואל, מי הוא שמים. שאומר, כונן \u0003שמים\u0004 בתבונה. ומשיב, זה הוא סוד האבות, שהם חג\"ת, וסוד האבות הוא יעקב שהוא קו אמצעי, ת\"ת, שהוא הכולל שלהם, שקו אמצעי כולל בתוכו הימין והשמאל, שה\"ס אברהם ויצחק. כי יעקב, תפארת האבות הוא, והוא עומד להאיר על העולם שהוא הנוקבא."],[9,"ובגין דאיהו אסתלק וכו':","ומשום שהוא מתעלה תוך עולם הבא, כלומר, שעולה ומלביש לישראל סבא, שנקרא עולם הבא, שה\"ס חסדים מכוסים, וע\"כ אין בו מקום לגילוי הארת חכמה, ועל כן, יוצא ממנו ענף אחד יפה מראה, דהיינו באור החכמה, הנקרא ראיה ומראה. וכל האורות, הן חכמה והן חסדים, יוצאים ממנו, וכל שובע ושמן המשחה, להאיר לארץ, שהיא הנוקבא. ומי הוא הענף הזה, הוא יוסף הצדיק, שהוא נותן שובע, שהוא הארת חכמה, לכל העולם. והעולם ממנו נזון. שהוא הארת החסדים. ומפני זה, הקב\"ה, כל מה שעושה, הכל הוא בסוד עליון, והכל הוא כראוי להיות."]],[[0,"","בֵּינְתַיִם אָמַר הָאִישׁ הַהוּא, וְכִי הַדָּבָר הַזֶּה שֶׁאַתֶּם אוֹמְרִים הוּא כָּךְ? סוֹד הַדָּבָר יֵשׁ כָּאן, שֶׁהִנֵּה דָּוִד הַמֶּלֶךְ חַי וְקַיָּם לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים, וְדָוִד הַמֶּלֶךְ הָיָה שׁוֹמֵר כָּל יָמָיו שֶׁלֹּא יִטְעַם טַעַם מִיתָה, מִשּׁוּם שֶׁהַשֵּׁנָה אֶחָד מִשִּׁשִּׁים בְּמִיתָה הִיא, וְדָוִד, מִשּׁוּם מְקוֹמוֹ שֶׁהוּא חַי, לֹא הָיָה יָשֵׁן אֶלָּא שִׁשִּׁים נְשִׁימוֹת, שֶׁעַד שִׁשִּׁים נְשִׁימוֹת חָסֵר אַחַת הוּא חַי, מִשָּׁם וָהָלְאָה טוֹעֵם אָדָם טַעַם מִיתָה וְשׁוֹלֵט בּוֹ הַצַּד שֶׁל רוּחַ הַטֻּמְאָה."],[1,"","וְזֶה הָיָה שׁוֹמֵר דָּוִד הַמֶלֶךְ, שֶׁלֹּא יִטְעַם טַעַם שֶׁל מִיתָה, וְשׁוֹלֵט (שלא ישלט) בּוֹ צַד שֶׁל רוּחַ אַחֶרֶת, מִשּׁוּם שֶׁשִּׁשִּׁים נְשִׁימוֹת חָסֵר אַחַת הוּא הַסּוֹד שֶׁל הַחַיִּים שֶׁלְּמַעְלָה, עַד שִׁשִּׁים נְשִׁימוֹת שֶׁהֵם שִׁשִּׁים (חסר נשימה אחת) נְשִׁימוֹת עֶלְיוֹנוֹת, וְאֵלּוּ הַסּוֹד שֶׁלָּהֶן, שֶׁהַחַיִּים תְּלוּיִים בָּהֶם, וּמִכָּאן וָמַטָּה הוּא סוֹד הַמָּוֶת."],[2,"","וְעַל כֵּן דָּוִד הָיָה מְשַׁעֵר אֶת שִׁעוּר הַלַּיְלָה כְּדֵי שֶׁיִּתְקַיֵּם בַּחַיִּים, שֶׁלֹּא יִשְׁלֹט בּוֹ טַעַם הַמָּוֶת, וּכְשֶׁנֶּחֱלַק הַלַּיְלָה הָיָה דָוִד עוֹמֵד בִּמְקוֹמוֹ, מִשּׁוּם שֶׁכַּאֲשֶׁר מִתְעוֹרֵר חֲצוֹת הַלַּיְלָה וְהַכֶּתֶר הַקָּדוֹשׁ מִתְעוֹרֵר, צָרִיךְ שֶׁלֹּא יִמְצָא אֶת דָּוִד קָשׁוּר בְּמָקוֹם אַחֵר, בִּמְקוֹם הַמָּוֶת."],[3,"","מִשּׁוּם שֶׁכַּאֲשֶׁר נֶחֱלָק הַלַּיְלָה וְהַקְּדֻשָּׁה הָעֶלְיוֹנָה מִתְעוֹרֶרֶת, וְאָדָם שֶׁיָּשֵׁן בְּמִטָּתוֹ וְלֹא מִתְעוֹרֵר לְהַשְׁגִּיחַ בִּכְבוֹד רִבּוֹנוֹ, הִנֵּה הוּא נִקְשָׁר בְּסוֹד הַמָּוֶת, וְנִדְבָּק לְמָקוֹם אַחֵר, וְעַל כֵּן דָּוִד הַמֶּלֶךְ הָיָה עוֹמֵד לְהַשְׁגִּיחַ בִּכְבוֹד רִבּוֹנוֹ תָּמִיד, חַי אֵצֶל חַי, וְלֹא נִרְדַּם בַּשֵּׁנָה לִטְעֹם טַעַם הַמָּוֶת, וּמִשּׁוּם כָּךְ הָיָה מִתְנַמְנֵם כְּמוֹ סוּס, שִׁשִּׁים נְשִׁימוֹת, וְלֹא בִּשְׁלֵמוּת."],[4,"","בָּאוּ רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי וּנְשָׁקוּהוּ. אָמְרוּ לוֹ, מַה שִּׁמְךְ? אָמַר לָהֶם, חִזְקִיָּה. אָמְרוּ לוֹ, יִישַׁר כֹּחֲךְ וְתִתְחַזֵּק תּוֹרָתְךְ. יָשְׁבוּ. אָמַר רַבִּי יְהוּדָה, הוֹאִיל וְהִתְחַלְתָּ, אֱמֹר לָנוּ מֵעַתָּה סוֹדוֹת עֶלְיוֹנִים שֶׁאָמַרְתָּ."],[5,"","פָּתַח וְאָמַר, (משלי ג) ה' בְּחָכְמָה יָסַד אָרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, רָאָה שֶׁלֹּא יָכוֹל לַעֲמֹד, עַד שֶׁבָּרָא אֶת הַתּוֹרָה, מִשּׁוּם שֶׁמִּמֶּנָּה יוֹצְאִים כָּל הַנְהָגוֹת הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וּבָהּ עוֹמְדִים עֶלְיוֹנִים וְתַחְתּוֹנִים. זֶהוּ שֶׁכָּתוּב ה' בְּחָכְמָה יָסַד אָרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה, שֶׁהֲרֵי בְּחָכְמָה עוֹמְדִים כָּל הַקִּיּוּמִים שֶׁל הָעוֹלָם, וְכֻלָּם יוֹצְאִים מִתּוֹכָהּ."],[6,"","דָּבָר אַחֵר ה' בְּחָכְמָה יָסַד אָרֶץ - הָעוֹלָם הָעֶלְיוֹן לֹא נִבְרָא אֶלָּא מִתּוֹךְ הַחָכְמָה, וְהָעוֹלָם הַתַּחְתּוֹן לֹא נִבְרָא אֶלָּא מִתּוֹךְ הַחָכְמָה הַתַּחְתּוֹנָה, וְכֻלָּם יוֹצְאִים מִתּוֹךְ הַחָכְמָה הָעֶלְיוֹנָה וּמִתּוֹךְ הַחָכְמָה הַתַּחְתּוֹנָה. כּוֹנֵן שָׁמַיִם בִּתְבוּנָה. כּוֹנֵן, מַה זֶּה כּוֹנֵן? אֶלָּא כּוֹנֵן כָּל יוֹם וָיוֹם וְלֹא פוֹסֵק, וְלֹא נִתְקָן בִּזְמַן אֶחָד, אֶלָּא בְּכָל יוֹם וָיוֹם מַתְקִין אוֹתוֹ."],[7,"","וְהַיְנוּ סוֹד הַכָּתוּב (איוב טו) וְשָׁמַיִם לֹא זַכּוּ בְעֵינָיו. וְכִי תַעֲלֶה עַל דַּעְתְּךְ שֶׁהַחִסָּרוֹן הוּא מִשָּׁמַיִם? אֶלָּא חֲשִׁיבוּת הַשָּׁמַיִם הִיא מִשּׁוּם הַחֲבִיבוּת וְרָצוֹן רַב שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָהֶם וַחֲבִיבוּתָם אֶצְלוֹ, שֶׁהֲרֵי אַף עַל גַּב שֶׁהוּא מַתְקִין אוֹתָם בְּכָל יוֹם וָיוֹם, אֵין דּוֹמֶה בְעֵינָיו שֶׁהֵם מְתֻקָּנִים כָּרָאוּי, מִשּׁוּם שֶׁאַהֲבָתָם אֶצְלוֹ, וּרְצוֹנוֹ לְהָאִיר לָהֶם תָּמִיד בְּלִי הֶפְסֵק, שֶׁהֲרֵי הָעוֹלָם הַבָּא מוֹצִיא אוֹרוֹת זוֹהֲרִים כָּל יוֹם וָיוֹם תָּמִיד בְּלִי הֶפְסֵק, כְּדֵי לְהָאִיר לָהֶם תָּמִיד, וְעַל כֵּן לֹא זַכּוּ בְעֵינָיו. לֹא זַכּוּ לְבַדּוֹ לֹא כָתוּב, אֶלָּא לֹא זַכּוּ בְעֵינָיו, וּמִשּׁוּם כָּךְ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה."],[8,"","מִי הַשָּׁמַיִם? זֶה הַסּוֹד שֶׁל הָאָבוֹת, וְהַסּוֹד שֶׁל הָאָבוֹת זֶהוּ יַעֲקֹב, שֶׁהוּא הַכְּלָלוּת שֶׁלָּהֶם, מִשּׁוּם שֶׁיַּעֲקֹב הוּא הַבָּחִיר שֶׁבָּאָבוֹת, וְהוּא עוֹמֵד לְהָאִיר עַל הָעוֹלָם."],[9,"","וּמִשּׁוּם שֶׁהוּא הִסְתַּלֵּק לְתוֹךְ הָעוֹלָם הַבָּא, יָצָא מִמֶּנּוּ עָנָף אֶחָד יָפֶה לְמַרְאֶה, וְכָל הָאוֹרוֹת יוֹצְאִים מִמֶּנּוּ וְכָל הַשָּׂבָע וְשֶׁמֶן הַמִּשְׁחָה לְהָאִיר לָאָרֶץ, וּמִי הוּא? זֶה יוֹסֵף הַצַּדִּיק, שֶׁהוא נוֹתֵן שָׂבָע לְכָל הָעוֹלָם, וְהָעוֹלָם נִזּוֹן מִמֶּנּוּ. וּמִשּׁוּם כָּךְ, כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, הַכֹּל הוּא בְּסוֹד עֶלְיוֹן, וְהַכֹּל כָּרָאוּי."]]],[["אַדְהָכִי אֲתָא רִבִּי אֶלְעָזָר, כֵּיוָן דְּחָמָא לוֹן אָמַר, וַדַּאי שְׁכִינְתָּא הָכָא. בְּמַאי עַסְקִיתוּ. אָמְרוּ לֵיהּ כָּל עוֹבָדָא. אָמַר, וַדַּאי שַׁפִּיר קָאֲמַר. אֲבָל אִינוּן שִׁתִּין נִשְׁמֵי, וַדַּאי שִׁתִּין נִשְׁמֵי אִינוּן דְּחַיִּין, בֵּין לְעֵילָא בֵּין לְתַתָּא. מִכָּאן וּלְהָלְאָה, אִיכָּא שִׁתִּין נִשְׁמִין אָחֳרָנִין, דְּאִינוּן כֻּלְּהוּ מִסִּטְרָא דְמוֹתָא, וְדַרְגָּא דְמוֹתָא עֲלַיְיהוּ, וְאִקְרוּן דּוּרְמִיטָא, וְכֻלְּהוּ טַעֲמָא דְמוֹתָא.","וּבְגִין כָּךְ דָּוִד מַלְכָּא הֲוָה אִיהוּ מִתְדְּבַּק בְּאִינוּן שִׁתִּין נִשְׁמִין דְּחַיִּין, וּמִתַּמָּן וּלְהָלְאָה לָא נָאִים כְּלַל. הֲדָא הוּא דִכְתִיב, (תהילים קל״ב:ד׳) אִם אֶתֵּן שְׁנָת לְעֵינָי לְעַפְעַפַּי תְּנוּמָה. וְעַל דָּא שַׁפִּיר קָאֲמַר, בְּגִין דְּיָקוּם דָּוִד חַי, בְּסִטְרָא דְחַי וְלָא בְּסִטְרָא דְמוֹתָא. יָתְבוּ כֻּלְּהוּ וְאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא וְאִתְחַבָּרוּ כְּחֲדָא.","פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (תהילים פ״ח:ב׳) ה' אֱלֹקֵי יְשׁוּעָתִי יוֹם צָעַקְתִּי בַלַּיְלָה נֶגְדֶּךָ. תָּא חֲזֵי, דָּוִד מַלְכָּא הֲוָה קָם בְּפַלְגּוּת לֵילְיָא, וְאִשְׁתְּדָּל בְּאוֹרַיְיתָא בְּשִׁירִין וְתוּשְׁבְּחָן, לְחֶדְוָה דְמַלְכָּא וּמַטְרוֹנִיתָא. וְדָא הֲוָה חֶדְוָה דִמְהֵימְנוּתָא בְּאַרְעָא. בְּגִין דְּהַאי אִיהוּ שְׁבָחָא דִמְהֵימְנוּתָא דְּאִתְחֲזֵי בְּאַרְעָא.","דְּהָא לְעֵילָא פָּתְחֵי בְּחֶדְוָה שִׁירָתָא כַּמָּה מַלְאָכִין עִלָּאִין, בְּכַמָּה זִינִין דְּקָא מְשַׁבְּחָן בְּלֵילְיָא בְּכָל סִטְרִין. כְּהַאי גַּוְונָא לְתַתָּא בְּאַרְעָא, מַאן דִּמְשַׁבַּח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא בְּאַרְעָא בְּלֵילְיָא, רָעֵי בֵּיהּ (בעי) קוּדְשָׁא בְּרִיךְ הוּא. וְכָל אִינוּן מַלְאָכִין קַדִּישִׁין דְּקָא מְשַׁבְּחָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, כֻּלְּהוּ צַיְיתִין לְהַהוּא דְקָא מְשַׁבַּח לֵיהּ בְּלֵילְיָא בְּאַרְעָא. דְּהַאי תּוּשְׁבַּחְתָּא אִיהוּ בִּשְׁלִימוּ, לְסַלְקָא יְקָרֵי דְּקוּדְשָׁא בְּרִיךְ הוּא מִתַּתָּא, וּלְזַמְּרָא בְּחֶדְוָה דְּיִחוּדָא.","תָּא חֲזֵי, דָּוִד מַלְכָּא כָּתַב, ה' אֱלֹהֵי יְשׁוּעָתִי וְגו', ה' אֱלהֵי יְשׁוּעָתִי, אֵימָתַי אִיהוּ יְשׁוּעָתִי. בְּהַהוּא יוֹמָא דְאַקְדֵּמִית תּוּשְׁבַּחְתָּא בְּלֵילְיָא לְגַבָּךְ, כְּדֵין אִיהוּ יְשׁוּעָתִי בִּימָמָא.","וְתָּא חֲזֵי, דְּהָא בְּלֵילְיָא, מַאן דִּמְשַׁבַּח לְמָארֵיהּ בְּתוּשְׁבַּחְתָּא דְאוֹרַיְיתָא, כְּדֵין אַתְקַף בִּתְקִיפוּ בִּיְמָמָא בְּסִטְרָא דִּימִינָא. דְּהָא חוּטָא חַד נַפְקָא מִסִּטְרָא דִּימִינָא, וּכְדֵין אִתְמָשַּׁךְ עֲלֵיהּ וְאִתְתַּקַּף בֵּיהּ. וְעַל דָּא אָמַר, ה' אֱלֹהֵי יְשׁוּעָתִי יוֹם צָעַקְתִּי וְגו'.","וּבְגִין כָּךְ אָמַר, (תהילים קט״ו:י״ז) לא הַמֵּתִים יְהַלְּלוּ יָהּ. לא הַמֵּתִים, בְּגִין דְּאִצְטְרִיךְ לְשַׁבְּחָא חַי לְחַי. וּמֵת לְחַי לָאו הָכִי, דִּכְתִיב לֹא הַמֵּתִים יְהַלְּלוּ יָהּ. וַאֲנַחְנוּ נְבָרֵךְ יָהּ, דְּהָא אֲנַן חַיִּין וְלֵית לָן חוּלָקָא בְּסִטְרָא דְמוֹתָא כְּלַל. חִזְקִיָּהוּ אָמַר, (ישעיהו ל״ח:י״ט) חַי חַי הוּא יוֹדֶךָ כָּמוֹנִי, בְּגִין דְּחַי אִתְקְרַב לְחַי. דָּוִד מַלְכָּא אִיהוּ חַי, וְקוּרְבָא דִילֵיהּ לְחַי הָעוֹלָמִים. וּמַאן דְּאִתְקְרִיב לְגַבֵּיהּ, אִיהוּ חַי. דִּכְתִיב, (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם. וּכְתִיב, (שמואל ב כ״ג:כ׳) וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי רַב פְּעָלִים מִקַּבְצְאֵל.","פָּתַח הַהוּא יוּדָאי אֲבַתְרֵיהּ וְאָמַר, (דברים ח׳:י׳) וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלקֶיךָ. וְכִי לָא מְבָרְכִינָן לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא עַד לָא נִיכוּל, וְהָא אִית לָן לְאַקְדּוּמֵי בְּצַפְרָא וּלְסִדּוּרֵי שְׁבָחָא דִילֵיהּ (דמאריה) כְּדְקָא יְאוּת, וּלְבָרְכָא בִּשְׁמֵיהּ עַד לָא יְבָרֵךְ לְאַחֲרָא בְּעַלְמָא. וּכְתִיב (ויקרא כט) לא תֹאכֵלוּ עַל הַדָּם, אָסוּר לֵיהּ לְמֵיכַל עַד לָא יְבָרֵךְ לְמָארֵיהּ. וְהַשְׁתָּא כְּתִיב וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ.","אֶלָּא, דָּא בִּרְכָתָא דִצְלוֹתָא דְּיִחוּדָא, וְדָא בִּרְכָתָא דִּמְזוֹנָא. לְאַחֲזָאָה לְגַבֵּי דַרְגָּא דִמְהֵימְנוּתָא, שָׂבָע כְּדְקָא יָאוֹת. וּכְדֵין בְּעֵי לְבָרְכָא לֵיהּ כְּדְקָא יְאוּת, דְּהַהוּא דַרְגָּא דִמְהֵימְנוּתָא יִתְרַוֵּי וִיבָרֵךְ, וְיִתְמַלֵּא חֵידוּ מֵחַיִּין דִּלְעֵילָא כְּמָה דְאִצְטְרִיךְ, בְּגִין לְמֵיהַב לָן מְזוֹנֵי.","דְּהָא קָשִׁין מְזוֹנָא דְבַר נָשׁ קַמֵי קוּדְשָׁא בְּרִיךְ הוּא, כִּקְרִיעַת יַם סוּף. מַאי טַעְמָא. בְּגִין דִּמְזוֹנָא דְעַלְמָא דִלְעֵילָא הוּא, דִּתְנַן בָּנֵי חַיֵּי וּמְזוֹנֵי וְכוּ', וּבְגִין כָּךְ קַשְׁיָין קַמֵּיהּ מְזוֹנֵי דְעַלְמָא. דְּהָא בְּמַזָּלָא תַּלְיָא מִילְתָא. דְּמִנֵּיהּ נָפְקֵי מְזוֹנֵי וְחַיֵּי וּבָנֵי. וּבְגִין כָּךְ קָשִׁין קַמֵּיהּ מְזוֹנֵי דְעַלְמָא, דְּהָא לָאו בִּרְשׁוּתֵיהּ קָיְימָא, עַד דְּיִתְבָּרֵךְ אִיהוּ.","כְּגַוְונָא דָא זִיִוְגִּין דְּעַלְמָא קָשִׁין קַמֵּיהּ, וְכֹלָּא בְּגִין דְּרָקִיעַ וִילוֹן לָא מְשַׁמֵּשׁ כְּלוּם. וְכָל שֶׁכֵּן אִלֵּין מִלִּין דְּקָיְימִין לְעֵילָא בְּאֲתַר אָחֳרָא, וְעַל דָּא אִצְטְרִיךְ לְאִתְבָּרְכָא."],[[0,"אדהכי אתא וכו':","בתוך כך בא ר' אלעזר. כיון שראה אותם, אמר, בודאי שהשכינה כאן, במה אתם נושאים ונותנים, ספרו לו כל המעשה עם אותו אדם ומאמרו. אמר ודאי יפה אמר, ומבאר דבריו, אבל אלו ששים נשימות, דהיינו שש השעות שמקודם חצות לילה, הם של חיים, בין למעלה בעולמות העליונים ששם ה\"ס מחזה ולמעלה של הנוקבא, ובין למטה בעולם הזה. מכאן ולהלאה, דהיינו אחר נקודת החצות, יש ששים נשימות אחרות, שהם חג\"ת נה\"י שמחזה ולמטה (כנ\"ל דף י\"ב ד\"ה והנה) שהן כולן מצד המות, ומדרגת המות עליהם, דהיינו נקודה המנעולא שבנקודת החזה (כמ\"ש שם) שהוא גורם כל מות שבעולם. ואלו ששים נשימות שמחזה ולמטה נקראות \u0003דורמיטא,\u0004 וכולן הן טעם המות."],[1,"ובגין כך דוד וכו':","ומשום זה דוד המלך, היה מתדבק באלו ששים נשימות של חיים, דהיינו בשש השעות שמקודם חצות לילה, שה\"ס שלמעלה מחזה. שאין כח הדין והמות שבנקודת החזה יכול להגיע אליהם כנ\"ל, ומשם ולהלאה לא היה ישן כלל. וזהו שכתוב, אם אתן שנת לעיני וגו', ועל כן יפה אמר, אותו אדם, כדי שיקום דוד חי, בצד החי, ולא בצד המות. (כמ\"ש כל זה לעיל דף י\"ג ד\"ה וז\"ש ע\"ש כל ההמשך) ישבו כולם ועסקו בתורה ונתחברו יחד."],[2,"פתח ר' אלעזר וכו':","פתח ר\"א ואמר, ה' אלקי ישועתי יום וגו'. בוא וראה, דוד המלך היה קם בחצות לילה ועסק בתורה בשירות ותשבחות לשמחת המלך והגבירה. וזה הוא שמחת האמונה בארץ, משום שזה הוא שבחה של האמונה, שהיא השכינה, הנראית בארץ."],[3,"דהא לעילא פתחי וכו':","כי למעלה פותחים בשמחה, שירה, כמה מלאכים עליונים בכמה אופנים, שהם משבחים בלילה בכל הצדדים, דהיינו אפילו בהארת צד שמאל, כי אז שליטת הנוקבא בסו\"ה ותקם בעוד לילה. כעין זה למטה בארץ, מי שמשבח בארץ אל הקב\"ה בלילה, חפץ בו הקב\"ה, וכל המלאכים הקדושים המשבחים אל הקב\"ה, כולם מקשיבים לאותו המשבח אל הקב\"ה בלילה בארץ, כי שירה זו היא בשלמות, להגדיל כבוד הקב\"ה מלמטה, ולזמר בשמחת היחוד."],[4,"תא חזי דוד וכו':","בוא וראה דוד המלך כתב, ה' אלקי ישועתי וגו'. שפירושו, מתי \u0003ה' אלקי ישועתי,\u0004 הוא ישועתי ביום ההוא שהקדמתי שירה בלילה אליך, כי אז הוא ישועתי ביום."],[5,"ות\"ח דהא בליליא וכו':","ובוא וראה, כי בלילה מי שמשבח לרבונו ברנה של תורה, מתחזק אז בגבורה ביום בצד ימין, שהוא חסד. כלומר, שהחכמה שקבל בלילה מצד שמאל, מתלבש ביום בחסד מצד ימין. כי חוט אחד של חסד, יוצא מצד ימין, ואז הוא נמשך עליו, ומתחזק בו. וע\"כ אמר דוד, ה' אלקי ישועתי יום צעקתי וגו'."],[6,"ובג\"כ אמר וכו':","ומשום זה אמר, לא המתים יהללו יה. \u0003לא המתים,\u0004 הוא משום שחי לחי צריך לשבח. ומת לחי אינו כן, שכתוב, לא המתים יהללו יה. \u0003ואנחנו נברך יה,\u0004 כי אנחנו חיים, ואין לנו חלק בצד המות כלום. חזקיה אמר, חי חי הוא יודוך כמוני, משום שחי נקרב לחי. וכן דוד המלך הוא חי, ונקרב לחי העולמים, ומי שנקרב אליו, לחי העולמים, הוא חי, שכתוב, ואתם הדבקים בה' אלקיכם חיים כלכם היום. וכתוב, ובניהו בן יהוידע בן איש חי רב פעלים מקבצאל."],[7,"פתח ההוא יודאי וכו':","פתח אותו יהודי אחריו, ואמר, ואכלת ושבעת וברכת וגו', שואל, וכי אין אנו מברכים את הקב\"ה מטרם שאנו אוכלים והרי יש לנו להקדים בבוקר ולסדר שבחו כראוי. מטרם שמברכים לאחר בעולם. וכתוב, לא תאכלו על הדם, שדרשו, שאסור לאכול מטרם שמברך לרבונו. ועתה כתוב, \u0003ואכלת ושבעת וברכת.\u0004 שמשמע, שאין לברך אלא אחר האכילה."],[8,"אלא דא ברכתא וכו':","ומשיב, אלא זה, שאנו מברכים קודם האכילה, הוא, ברכת התפלה ליחוד זו\"ן, וזה, שלאחר האכילה, הוא, ברכת המזון. וצריכים לב' דברים, א) להראות שבע למדרגת האמונה, שהיא הנוקבא, כראוי. ב) ואז צריכים לברך אותה כראוי, כדי שאותה מדרגת האמונה תתרוה ותתברך ותתמלא שמחה מחיים העליונים כפי שצריך, כדי שתתן לנו מזונות."],[9,"דהא קשין מזוני וכו':","כי קשים מזונותיו של אדם לפני הקב\"ה כקריעת ים סוף. מה הטעם, הוא, משום שמזונות העולם מלמעלה הם. מז\"א, בסוד המסך דחירק שבקו אמצעי, (כנ\"ל ב\"א דף קע\"ז אות קצ\"ח) כי למדנו, בנים חיים ומזונות אין הדבר תלוי בזכות אלא הדבר תלוי במזל. ומשום זה קשים לפניו מזונות העולם, משום שהדבר תלוי במזל, שממנו יוצאים בנים חיים ומזונות, וע\"כ קשה לפניו מזונות העולם, כי אינם ברשותו מטרם שהוא מתברך מן המזל."],[9,"","ביאור הדברים. כי בתחילה היתה הנוקבא גדולה וזכה כמו ז\"א, והיתה דבוקה בו מאחוריו. אלא שהמוחין לא היו מאירים אז בנוקבא, מחמת חסרון לבוש דחסדים, ולא היתה משפעת כלום לתחתונים, (כמ\"ש לעיל ב\"א דף ק\"ד ד\"ה את, ע\"ש) ועל כן מיעטה הנוקבא את עצמה, בסוד נקודה תחת יסוד דז\"א, שפירושו שנכללה במסך דחירק שבקו האמצעי שמחזה ולמטה דז\"א, וננסרה לפרצוף נפרד ממנו. שמחמת מיעוט הזה אין לה עוד מעצמה שום אור, וצריכה לקבל הכל מלמעלה, דהיינו מז\"א, (כמ\"ש לעיל בראשית א' דף ק\"ח ד\"ה וכבר, ע\"ש)."],[9,"","וזה אמרו, \u0003בני חיי ומזוני לאו בזכותא תליא מילתא,\u0004 שהרי בזמן שהיתה הנוקבא גדולה \u0003וזכה\u0004 כמו ז\"א, לא יכלה להשפיע בני חיי ומזוני לתחתונים, כנ\"ל, \u0003אלא במזלא תליא מילתא,\u0004 שהדבר תלוי בז\"א, שיסוד שלו נקרא \u0003מזל,\u0004 דהיינו שצריכה להכלל במסך דחירק שביסוד דז\"א, ואז מתלבש החכמה שלה בחסדים, ויכולה להשפיע בני חיי ומזוני לתחתונים. וז\"ש \u0003קשין מזונא דבר נש קמי קב\"ה\u0004 היינו הנוקבא, \u0003כקריעת ים סוף, מ\"ט, בגין דמזונא דעלמא, דלעילא הוא,\u0004 דהיינו שהנוקבא צריכה לקבל \u0003מלמעלה\u0004 דהיינו מז\"א, אשר אז היא מחויבת להתמעט כנ\"ל, וע\"כ קשים לפניה מזונותיו של אדם. כי כדי להשפיע מזונות לעולם היא מתמעטת לבחינת \u0003לית לה מגרמה ולא מידי.\u0004"],[9,"","וזה אמרו (באות נ\"ד) \u0003לאחזאה לגבי דרגא דמהימנותא שבע\u0004 וכו'. כי משום זה צריכים לב' דברים א) \u0003לברכא\u0004 וכו' \u0003דההוא דרגא דמהימנותא יתרוי ויברך ויתמלא חידו מחיין דלעילא בגין למיהב לן מזוני,\u0004 דהיינו להמשיך לה עתה, אחר שנתמעטה, כל החיים והטוב של מעלה, דהיינו מז\"א, כדי שתתן לנו מזונות. ב) \u0003לאחזאה לגבי דרגא דמהימנותא שבע,\u0004 כי בזה שאנו מראים את עצמינו שבע, היא מתנחמת על מיעוטה שנתמעטה בשבילנו."],[10,"כגוונא דא זווגין וכו':","כעין זה, קשים לפניו הזווגים שבעולם. והכל, הן בנים והן חיים והן מזונות הוא משום שהרקיע וילון אינו משמש כלום, וכל שכן אלו הדברים, בנים חיים ומזונות, הנמצאים למעלה במקום אחר, ועל כן נצרכה להתברך. שתקבל משם."],[10,"","פירוש. הרקיע וילון, ה\"ס הנוקבא, \u0003דלית לה מגרמה ולא מידי,\u0004 אחר שנתמעטה, (כמ\"ש בזהר פנחס אות תק\"יז ע\"ש) וז\"ש \u0003וכלא, בגין דרקיע וילון לא משמש כלום,\u0004 דהיינו שנתמעטה עד \u0003דלית לה מגרמה ולא מידי,\u0004 וע\"כ צריכים להראות עצמו שבע כנ\"ל, \u0003וכ\"ש אלין מלין\u0004 וכו', וע\"כ צריכים לברך אותה שתקבל מעליון."]],[[0,"","בֵּינְתַיִם בָּא רַבִּי אֶלְעָזָר. כֵּיוָן שֶׁרָאָה אוֹתָם, אָמַר, וַדַּאי שֶׁהַשְּׁכִינָה כָּאן. אָמַר לָהֶם, בַּמָּה עֲסַקְתֶּם? אָמְרוּ לוֹ אֶת כָּל הַמַּעֲשֶׂה. אָמַר, וַדַּאי שֶׁיָּפֶה אָמַר, אֲבָל אוֹתָם שִׁשִּׁים הַנְּשִׁימוֹת, וַדַּאי שֶׁשִּׁשִּׁים נְשִׁימוֹת הֵן שֶׁל חַיִּים, בֵּין לְמַעְלָה בֵּין לְמַטָּה. מִכָּאן וָהָלְאָה יֵשׁ שִׁשִּׁים נְשִׁימוֹת אֲחֵרוֹת שֶׁהֵן כֻּלָּן מִצַּד הַמָּוֶת, וְדַרְגַּת הַמָּוֶת עֲלֵיהֶן, וְנִקְרָאוֹת תַּרְדֵּמָה, וְכֻלָּן טַעַם הַמָּוֶת."],[1,"","וּמִשּׁוּם כָּךְ דָּוִד הַמֶּלֶךְ הוּא הָיָה נִדְבָּק לְאוֹתָם שִׁשִּׁים הַנְּשִׁימוֹת שֶׁל חַיִּים, וּמִשָּׁם וָהָלְאָה לֹא יָשַׁן כְּלָל. זֶהוּ שֶׁכָּתוּב (תהלים קלב) אִם אֶתֵּן שְׁנָת לְעֵינַי לְעַפְעַפַּי תְּנוּמָה. וְעַל כֵּן יָפֶה אָמַר, כְּדֵי שֶׁיָּקוּם דָּוִד חַי, בַּצַּד שֶׁל הַחַי, וְלֹא בְּצַד הַמָּוֶת. כֻּלָּם יָשְׁבוּ וְהִשְׁתַּדְּלוּ בַתּוֹרָה וְהִתְחַבְּרוּ יַחַד."],[2,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (שם פח) ה' אֱלֹהֵי יְשׁוּעָתִי יוֹם צָעַקְתִּי בַלַּיְלָה נֶגְדֶּךְ. בּא רְאֵה, דָּוִד הַמֶּלֶךְ הָיָה קָם בַּחֲצוֹת הַלַּיְלָה וּמִשְׁתַּדֵּל בַּתּוֹרָה בְּשִׁירִים וְתִשְׁבָּחוֹת לְשִׂמְחַת הַמֶּלֶךְ וְהַגְּבִירָה, וְזוֹ הָיְתָה שִׂמְחַת הָאֱמוּנָה בָּאָרֶץ, מִשּׁוּם שֶׁזֶּהוּ הַשֶּׁבַח שֶׁל הָאֱמוּנָה שֶׁנִּרְאֶה בָאָרֶץ."],[3,"","שֶׁהֲרֵי לְמַעְלָה פּוֹתְחִים בְּשִׂמְחָה שִׁירָה, כַּמָּה מַלְאָכִים עֶלְיוֹנִים בְּכַמָּה מִינִים שֶׁמְּשַׁבְּחִים בַּלַּיְלָה בְּכָל הַצְּדָדִים. כְּמוֹ כֵן לְמַטָּה בָּאָרֶץ, מִי שֶׁמְּשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ בַּלַּיְלָה, בּוֹ חָפֵץ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל אוֹתָם הַמַּלְאָכִים הַקְּדוֹשִׁים שֶׁמְּשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּם מַקְשִׁיבִים לְאוֹתוֹ שֶׁמְּשַׁבֵּחַ אוֹתוֹ בַּלַּיְלָה בָּאָרֶץ, שֶׁהַשֶּׁבַח הַזֶּה הוּא בִּשְׁלֵמוּת, לְהַעֲלוֹת אֶת כְּבוֹד הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְּמַטָּה וּלְזַמֵּר בַּשִּׂמְחָה שֶׁל הַיִּחוּד."],[4,"","בֹּא רְאֵה, דָּוִד הַמֶּלֶךְ כָּתַב, ה' אֱלֹהֵי יְשׁוּעָתִי וְגוֹ'. ה' אֱלֹהֵי יְשׁוּעָתִי, מָתַי הוּא יְשׁוּעָתִי? בְּאוֹתוֹ יוֹם שֶׁהִקְדַּמְתִּי שֶׁבַח בַּלַּיְלָה אֶצְלְךְ, אָז הוּא יְשׁוּעָתִי בַּיּוֹם."],[5,"","וּבֹא רְאֵה, שֶׁהֲרֵי בַּלַּיְלָה, מִי שֶׁמְּשַׁבֵּחַ אֶת רִבּוֹנוֹ בַּשֶּׁבַח שֶׁל הַתּוֹרָה, אָז מִתְחַזֵּק בְּחֹזֶק בַּיּוֹם בְּצַד הַיָּמִין, שֶׁהִנֵּה חוּט אֶחָד יוֹצֵא מִצַּד הַיָּמִין, וְאָז נִמְשָׁךְ עָלָיו וּמִתְגַּבֵּר בּוֹ, וְעַל כֵּן אָמַר ה' אֱלֹהֵי יְשׁוּעָתִי יוֹם צָעַקְתִּי וְגוֹ'."],[6,"","וּמִשּׁוּם כָּךְ אָמַר לֹא הַמֵּתִים יְהַלְלוּ יָהּ. לֹא הַמֵּתִים, מִשּׁוּם שֶׁצָּרִיךְ לְשַׁבֵּחַ חַי לְחַי. וּמֵת לְחַי לֹא כֵן, שֶׁכָּתוּב לֹא הַמֵּתִים יְהַלְלוּ יָהּ, וַאֲנַחְנוּ נְבָרֵךְ יָהּ, שֶׁהֲרֵי אָנוּ חַיִּים, וְאֵין לָנוּ חֵלֶק בְּצַד הַמָּוֶת כְּלָל. חִזְקִיָּהוּ אָמַר, (ישעיה לח) חַי חַי הוּא יוֹדֶךְ כָּמוֹנִי, מִשּׁוּם שֶׁחַי מִתְקָרֵב לְחַי. דָּוִד הַמֶּלֶךְ הוּא חַי, וְהַקִּרְבָה שֶׁלּוֹ לְחַי הָעוֹלָמִים, וּמִי שֶׁנִּקְרָב אֵלָיו הוּא חַי, שֶׁכָּתוּב וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם חַיִּים כֻּלְּכֶם הַיּוֹם, וְכָתוּב וּבְנָיָהוּ בֶּן יְהוֹיָדָע בֶּן אִישׁ חַי רַב פְּעָלִים מִקַּבְצְאֵל."],[7,"","פָּתַח אוֹתוֹ הַיְּהוּדִי אַחֲרָיו וְאָמַר, (דברים ח) וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ. וְכִי לֹא מְבָרְכִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא טֶרֶם נֹאכַל, וַהֲרֵי יֵשׁ לָנוּ לְהַקְדִּים בַּבֹּקֶר, וּלְסַדֵּר אֶת הַשֶּׁבַח שֶׁלּוֹ (של רבונו) כָּרָאוּי, וּלְבָרֵךְ אֶת שְׁמוֹ טֶרֶם שֶׁיְּבָרֵךְ מִישֶׁהוּ אַחֵר בָּעוֹלָם, וְכָתוּב (ויקרא יט) לֹא תֹאכְלוּ עַל הַדָּם, אָסוּר לוֹ לֶאֱכֹל טֶרֶם שֶׁיְּבָרֵךְ אֶת רִבּוֹנוֹ, וְעַכְשָׁו כָּתוּב וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ?"],[8,"","אֶלָּא, זוֹ הַבְּרָכָה שֶׁל תְּפִלַּת הַיִּחוּד, וְזוֹ בִּרְכַּת הַמָּזוֹן, לְהַרְאוֹת כְּלַפֵּי דַרְגַּת הָאֱמוּנָה שָׂבָע כָּרָאוּי. וְאָז צָרִיךְ לְבָרֵךְ אוֹתוֹ כָּרָאוּי, שֶׁאוֹתָהּ הַדַּרְגָּה שֶׁל הָאֱמוּנָה תִּתְרַוֶּה וְתִתְבָּרֵךְ, וְיִתְמַלֵּא שִׂמְחָה מֵהַחַיִּים שֶׁלְּמַעְלָה כְּמוֹ שֶׁצָּרִיךְ, כְּדֵי לָתֵת לָנוּ מְזוֹנוֹת."],[9,"","שֶׁהֲרֵי קָשִׁים מְזוֹנוֹתָיו שֶׁל אָדָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ קְרִיעַת יַם סוּף, מָה הַטַּעַם? מִשּׁוּם שֶׁהַמָּזוֹן שֶׁל הָעוֹלָם שֶׁלְּמַעְלָה הוּא, שֶׁשָּׁנִינוּ בָּנִים חַיִּים וּמְזוֹנוֹת וְכוּ'. וּמִשּׁוּם כָּךְ קָשִׁים לְפָנָיו מְזוֹנוֹת הָעוֹלָם. שֶׁהֲרֵי בְּמַזָּל תָּלוּי הַדָּבָר שֶׁיּוֹצְאִים מִמֶּנּוּ מְזוֹנוֹת וְחַיִּים וּבָנִים. וּמִשּׁוּם כָּךְ קָשִׁים לְפָנָיו הַמְּזוֹנוֹת שֶׁל הָעוֹלָם, שֶׁהֲרֵי זֶה לֹא עוֹמֵד בִּרְשׁוּתוֹ עַד שֶׁהוּא יִתְבָּרֵךְ."],[10,"","כְּמוֹ כֵן הַזִּוּוּגִים שֶׁל הָעוֹלָם קָשִׁים לְפָנָיו, וְהַכֹּל מִשּׁוּם שֶׁרְקִיעַ וִילוֹן אֵינוֹ מְשַׁמֵּשׁ כְּלוּם, וְכָל שֶׁכֵּן הַדְּבָרִים הַלָּלוּ שֶׁעוֹמְדִים לְמַעְלָה בְּמָקוֹם אַחֵר, וְעַל כֵּן צָרִיךְ לְהִתְבָּרֵךְ."]]],[["תָּא חֲזֵי, כָּל זִווּגִין דְּעַלְמָא קָשִׁין קַמֵּיהּ הַאי דַרְגָא, בְּגִין דְּכַד הַאי זִוּוּגָא קַדִּישָׁא אִשְׁתַּכַּח, כָּל נִשְׁמָתִין נָפְקִין מִגּוֹ הַאי מַזָּלָא לְעֵילָא, דְּאִיהוּ הַהוּא נָהָר דְּנָגִיד וְנָפִיק. וְכַד תִּיאוּבְתָּא אִשְׁתַּכַּח מִלְרַע לְעֵילָא, כְּדֵין פָּרְחִין נִשְׁמָתִין, וְאִתְיְיהִיבוּ כֻּלְּהוּ כְּלִילָן דְּכַר וְנוּקְבָא כְּחֲדָא בְּהַאי דַרְגָּא. וּלְבָתַר אִיהוּ פָּרִישׁ לוֹן כָּל חַד וְחַד לְאַתְרֵיהּ כְּדְקָא חָזֵי לֵיהּ. וּלְבָתַר קָשִׁין קַמֵּי הַאי דַרְגָּא לְחַבְּרָא לוֹן כְּקַדְמִיתָא, בְּגִין דְּלָא מִתְחַבְּרָן, בַּר כְּאִינוּן אָרְחֵי דְבַּר נָשׁ, וְכֹלָּא לְעֵילָא תַּלְיָין.","וְעַל דָּא קָשִׁין קַמֵּיהּ כִּקְרִיעַת יַם סוּף. דְּהָא קְרִיעַת יַמָּא לְאִתְפַּתְּחָא בֵּיהּ שְׁבִילִין, לְעֵילָא אִיהוּ. וּכְמָה דְּמִתְפַּתְּחִין שְׁבִילִין וְאוֹרְחִין בֵּיהּ, הָכִי אִתְבַּקַּע וְאִתְפַּתַּח.","וּבְגִין כָּךְ כֹּלָּא תַּלְיָא לְעֵילָא, וּבְעִינָן לְבָרְכָא לֵיהּ, וּלְמֵיהַב לֵיהּ תּוּקְפָא מִתַּתָּא, בְּגִין דְּיִתְבָּרְכָא מִלְּעֵילָא, וְיִתְתַּקַּף כְּדְקָא חָזֵי. וְעַל דָּא כְּתִיב, וּבֵרַכְתָּ אֶת ה', אֶת דַּיְיקָא.","וּלְגַבֵּי הַאי אֲתַר, אִצְטְרִיךְ לְאַחֲזָאָה קַמֵּיהּ שָׂבְעָא וּנְהִירוּ דְאַנְפִּין. וּלְגַבֵּי סִטְרָא אָחֳרָא, בְּזִמְנָא דְאִיהִי שָׁלְטָא בְּעַלְמָא, בְּעֵי לְאַחֲזָאָה קַמֵּיהּ כַּפְנָא. דְּהַהוּא דַרְגָּא רָעָב אִיהוּ, וְאִתְחֲזֵי לְאַחֲזָאָה קַמֵּיהּ כַּפְנָא וְלָא שׂוֹבְעָא, הוֹאִיל וְשָׂבָע לָא שָׁלְטָא בְּעַלְמָא. וְעַל דָּא, וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹקֶיךָ. אָמַר רִבִּי אֶלְעָזָר, הָכִי הוּא וַדַּאי, וְהָכִי אִצְטְרִיךְ.","אָמַר רִבִּי יְהוּדָה, זַכָּאִין אִינוּן צַדִּיקַיָּיא דְּקוּרְבָא דִּלְהוֹן אִיהוּ שְׁלָמָא בְּעַלְמָא. בְּגִין דְּיָדְעֵי לְיַחֲדָא יִחוּדָא, וּמְקַרְבֵי קוּרְבָא לְאַסְגָּאָה שְׁלָמָא בְּעַלְמָא. דְּהָא יוֹסֵף וִיהוּדָה עַד לָא אִתְקְרִיבוּ דָּא עִם דָּא, לָא הֲוָה שְׁלָמָא. כֵּיוָן דְּאִתְקְרִיבוּ יוֹסֵף וִיהוּדָה כְּחֲדָא, כְּדֵין אַסְגִּיאוּ שְׁלָמָא בְּעַלְמָא. וְחֵידוּ אִתּוֹסַף לְעֵילָא וְתַתָּא, כְּמָה דְּקוּרְבָא דִּיהוּדָה וְיוֹסֵף וְכֻלְּהוּ שִׁבְטִין אִשְׁתַּכָּחוּ כְּחֲדָא בֵּיהּ בְּיוֹסֵף. וְהַהוּא קוּרְבָא אַסְגֵּי שְׁלָמָא בְּעַלְמָא, כְּמָה דְאוֹקִימְנָא. דִּכְתִיב, וַיִּגַּשׁ אֵלָיו יְהוּדָה:","וְלֹא יָכוֹל יוֹסֵף לְהִתְאַפֵּק לְכָל הַנִּצָּבִים עָלָיו וְגו', רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים קי״ב:ט׳) פִּזַּר נָתַן לָאֶבְיוֹנִים צִדְקָתוֹ עוֹמֶדֶת לָעַד קַרְנוֹ תָּרוּם בְּכָבוֹד. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא בָּרָא עַלְמָא, וְאַשְׁלִיט עֲלֵיהּ לָאָדָם, דִּיהֵא מַלְכָּא עַל כֹּלָּא.","וְהַאי בַּר נָשׁ, מִתְפָּרְשָׁן מִנֵּיהּ בְּעַלְמָא כַּמָּה זִינִין. מִנְּהוֹן צַדִּיקַיָּא וּמִנְּהוֹן רַשִּׁיעַיָא. מִנְּהוֹן טִפְּשִׁין וּמִנְּהוֹן חַכִּימִין. וְכֻלְּהוּ אִתְקָיְימוּ בְּעַלְמָא, עֲתִירִין וּמִסְכֵּנִין. וְכֻלְּהוּ בְּגִין לְמִזְכֵּי אִלֵּין בְּאִלֵּין, לְמִזְכֵּי צַדִּיקַיָא עִם רַשִּׁיעַיָא, לְמִזְכֵּי חַכִּימִין עִם טִפְּשִׁין, לְמִזְכֵּי עֲתִירִין עִם מִסְכֵּנִין. דְּהָא בְּגִין כָּךְ, זָכֵי בַּר נָשׁ לְחַיֵּי עָלְמָא, וְאִתְקַשַּׁר בְּאִילָנָא דְחַיֵּי. וְלָא עוֹד, אֶלָּא דְּהָא צְדָקָה דְּאִיהוּ עָבִיד, קָאִים לְעָלְמִין. דִּכְתִיב וְצִדְקָתוֹ עוֹמֶדֶת לָעַד.","פִּזַּר נָתַן לָאֶבְיוֹנִים. רִבִּי אֶלְעָזָר אָמַר, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, קָאִים לֵיהּ עַל סַמְכָא חַד, וְצַדִּיק שְׁמֵיהּ, וְהַאי צַדִּיק אִיהוּ קִיּוּמָא דְעַלְמָא, וְדָא אִיהוּ דְאַשְׁקֵי, וְזָן לְכֹלָּא. דִּכְתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֶד וְהָיָה לְאַרְבָּעָה רָאשִׁים.","וּמִשָּׁם יִפָּרֶד, מַהוּ יִפָּרֶד. אֶלָּא, הַהוּא מְזוֹנָא וּמַשְׁקַיָא דְּהַהוּא נָהָר, נָטִיל גִּנְתָא כֹּלָּא, וּלְבָתַר אִתְבַּדַּר הַהוּא מַשְׁקַיָא לְד' סִטְרִין דְּעַלְמָא. וְכַמָּה אִינוּן דִּמְצַפָּאן לְאִתְשַׁקְיָיא וּלְאִתְּזְנָא מִתַּמָּן. כְּמָא דְאַתְּ אָמֵר, (תהילים קמ״ה:ט״ו) עֵינִי כֹל אֵלֶיךָ יְשַׂבֵּרוּ וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ. וּבְגִין כָּךְ פִּזַּר נָתַן לָאֶבְיוֹנִים, דָּא צַדִּיק. צִדְקָתוֹ עוֹמֶדֶת לָעַד, דָּא כְּנֶסֶת יִשְׂרָאֵל. דִּבְגִין כָּךְ, אִיהִי קָיְימָא בְּרָזָא דִשְׁלָם, בְּקִיּוּמָא שְׁלִים. רָשָׁע יִרְאֶה וְכָעַס, דָּא מַלְכוּת עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.","תָּא חֲזֵי, מַלְכוּת שָׁמַיִם, אִיהִי בֵּי מַקְדְּשָׁא. לְקָיְימָא כָּל מִסְכְּנֵי בְּגוֹ צִלָּא דְּשֵׁרוּתָא דִשְׁכִינְתָּא. וְצַדִּיק דָּא אִיהוּ אִקְרֵי גַּבָּאי צְדָקָה, לְמֵיחַן וּלְמֵיזַן לְכֹלָּא. דִּכְתִיב פִּזַּר נָתַן לָאֶבְיוֹנִים. בְּגִין כָּךְ, גַּבָּאֵי צְדָקָה נָטְלֵי אַגְרָא לָקֳבֵיל כֻּלְּהוּ דְּיַהֲבֵי צְדָקָה."],[[0,"ת\"ח כל זווגין וכו':","בוא וראה כל הזווגים שבעולם, קשים לפני מדרגה הזו, דהיינו הנוקבא, משום כשנעשה הזווג הזה, להוליד נשמות, יוצאות כל הנשמות מן מזל הזה שלמעלה, שהוא נהר הנמשך ויוצא מעדן, דהיינו יסוד דז\"א, וכשההשתוקקות נמצא להמשיך ממטה למעלה, דהיינו להמשיך הארת החכמה, שאינה נמשכת רק ממטה למעלה (כנ\"ל ב\"א דף ס' ר\"ה מחלוקת) אז פורחות הנשמות אל הנוקבא, ונעשות כולן באותה המדרגה כלולות זכר ונקבה יחד. ואחר כך הוא מפריד אותם כל אחד ואחד למקומו כראוי לו. ואחר כך קשה לפני מדרגה הזו לחזור ולחבר אותם זכר ונקבה, כבתחילה. משום שאינם מתחברים רק כאלו האורחות של בני אדם, והכל תלוי למעלה."],[0,"","פירוש. כמו שנתבאר לעיל (באות נ\"ה ד\"ה ביאור) אצל הנוקבא, שמתחילה נאצלה גדולה כמו ז\"א ודבוקה באחוריו, ואחר כך ע\"י שנכללה במסך דחירק דז\"א ננסרה לפרצוף נפרד ממנו, כן הוא בנשמות בני אדם הנולדות מן הנוקבא, שמתחילה כשמקבלים מהארת השמאל שבנוקבא, שהיא הארת חכמה, נמצאים כל זכר ונקבה של הנשמות דבוקים זה בזה מאחוריהם ואחר כך הנוקבא מאירה להם המסך דחירק, ואז הם נפרדים זה מזה."],[0,"","וז\"ש \u0003כד תיאובתא אשתכח מלרע לעילא,\u0004 דהיינו כשנמשך הארת החכמה שבשמאל ממטה למעלה כמ\"ש לעיל, \u0003כלהו כלילן דכר ונוקבא כחדא,\u0004 דהיינו שדבוקים זה בזה מאחוריהם כמו הנוקבא שדבוקה באחורי ז\"א בעת שהיא בהארת השמאל. \u0003ולבתר איהו פריש לון,\u0004 דהיינו על ידי שמאירה אליהם המסך דחירק, הם נפרדים זמ\"ז. כמ\"ש אצל הנוקבא, ע\"ש. ונודע שתחילת הארת המסך דחירק הוא בכח המנעולא, (כנ\"ל לך דף י\"ג ד\"ה ונתבאר ע\"ש) ואינה ראויה לקבל מוחין עד שנמתקת בבינה ונתקנה בסוד מפתחא, עש\"ה. וז\"ש \u0003ולבתר קשין קמי האי דרגא לחברא לון כקדמיתא,\u0004 כי מחמת התכללותם במסך דמנעולא אינם ראויים לזווג, \u0003בגין דלא מתחברן בר כאינון ארחי דבר נש,\u0004 משום שאין הם מתחברים לזווג, רק אחר שנתקנו בסוד \u0003אורחין,\u0004 דהיינו אחר שקבלו המסך דמפתחא המכונה אורחא. כי אז אמא אוזיפת מאנהא לברתא, וכן זכר ונקבה דנשמות בני אדם."],[1,"ועל דא קשין קמיה וכו':","ועל כן קשים לפניו כקריעת ים סוף, כי קריעת ים סוף היה, כדי לפתוח בו שבילים למעלה, וכמו שנפתחים שבילים ואורחות בו, כן נתבקע ונתפתח."],[1,"","פירוש. כבר ידעת שהארות המנעולא נקראות \u0003שבילים\u0004 בסו\"ה ושבילך במים רבים. והארות המפתחא נקראות \u0003אורחות,\u0004 בסו\"ה וארח צדיקים כאור נגה וכו'. (כמ\"ש לעיל בראשית א' דף רנ\"א ד\"ה נחית עש\" ה). והנה כל הקושי שבקריעת ים סוף היה, שב' פעולות הפוכות היו בה. שהיה צריך להטביע את המצרים הנמשכים מג\"ר דחכמה שבשמאל, שאין זה אלא בכח גילוי המנעולא שה\"ס \u0003שביל.\u0004 (כנ\"ל לך י\"ג ד\"ה ולפיכך בביאור פעולה ב' מד' הפעולות ע\"ש) והיה צריך להמשיך חיים והצלה לישראל הנמשכים מו\"ק דחכמה שבשמאל. שאין זה אלא בגניזו דמנעולא וגילוי המפתחא, כי אין מוחין נמשכים אלא בסוד המפתחא, שה\"ס \u0003ארח\u0004 (כנ\"ל תולדות דף מ\"ו ד\"ה ובזה ע\"ש)."],[1,"","וזה אמרו. \u0003וע\"ד קשין קמיה כקריעת ים סוף, דהא קריעת ימא לאתפתחא ביה שבילין לעילא איהו,\u0004 שקריעת ים סוף היתה לפתוח \u0003שבילים\u0004 למעלה, דהיינו לגלות המנעולא כדי להטביע את המצרים, ונמצא שהיו נפתחים שבילים בסוד המנעולא להטביע את המצרים, ואורחות בסוד המפתחא בשביל ישראל. הרי, \u0003וכמה דמתפתחין שבילין ואורחין ביה הכי אתבקע ואתפתח,\u0004 כי כלולים כאן ב' פעולות הפוכות זו מזו בקריעת ים סוף, כי כמו שהיו נפתחים \u0003שבילים,\u0004 בכח המנעולא, \u0003ואורחות,\u0004 בכח המפתחא, כן נבקע הים ונפתח להטביע המצרים ולהציל את ישראל. וז\"ס הקושי שבקריעת ים סוף. ואלו ב' פעולות הפוכות הן גם כן בסוד המיעוט של הנוקבא כדי להשפיע מזונות לתחתונים כמבואר לעיל (לך י\"ג ד\"ה ולפיכך) בפעולה ב' ובפעולה ג' שבד' פעולות עש\"ה. וע\"כ קשים מזונותיו של אדם כקריעת ים סוף."],[2,"ובג\"כ כלא תליא וכו':","וע\"כ הכל תלוי למעלה, כי לית לנוקבא מגרמה ולא מידי, אחר שנתמעטה, וצריכים לברך אותה, וליתן לה חוזק מלמעלה, כדי שתתברך ותקבל מלמעלה מז\"א, ותתחזק כראוי, וע\"כ כתוב, וברכת \u0003את\u0004 ה', המלה \u0003את\u0004 הוא בדיוק, הרומזת על הנוקבא הנקראת \u0003את.\u0004"],[3,"ולגבי האי אתר וכו':","ואל המקום הזה, דהיינו הנוקבה, צריכים להראות לפניה שובע והארת הפנים (כמ\"ש לעיל בדף י\"ח ד\"ה וזה אמרו לאחזאה) שצריכים ב' דברים ע\"ש. ואל הסטרא אחרא, בזמן שהיא שולטת בעולם, צריכים להראות לפניה רעב, כי מדרגה ההיא דס\"א, הוא רעב, וראוי להראות לפניה רעב ולא שובע, כי השובע אינו שולט בעולם בסבתה, וע\"כ כתוב \u0003ואכלת ושבעת וברכת את ה' אלקיך.\u0004 כי בזמן שליטת הקדושה יש שובע בעולם. אמר ר' אלעזר, כן הוא בודאי וכן צריך להיות. דהיינו שהשובע יתגלה עם שליטת הקדושה והרעב עם שליטת הס\"א."],[4,"אמר ר' יהודה וכו':","אר\"י, אשרי הם הצדיקים שקרבתם זה לזה מביא שלום בעולם, משום שיודעים ליחד היחוד ולעשות קרבה להרבות שלום בעולם. כי יוסף ויהודה, כל עוד שלא נתקרבו זה לזה, לא היה שלום, כיון שנתקרבו ביחד יוסף ויהודה, אז נתרבה השלום בעולם. ונתוספה שמחה למעלה ולמטה בעת שנתקרבו יהודה ויוסף, וכל השבטים היו נמצאים יחד עם יוסף. וקרבה ההיא הרבתה שלום בעולם, כמו שבארנו, שכתוב, ויגש אליו יהודה."],[5,"ולא יכול יוסף להתאפק וגו':","רבי חייא פתח ואמר, פזר נתן לאביונים וגו'. בוא וראה, הקב\"ה ברא העולם, והמשיל את האדם עליו, שיהיה מלך על הכל."],[6,"והאי בר נש וכו':","ואדם הזה, נפרדים ממנו בעולם כמה מינים, מהם צדיקים מהם רשעים, מהם טפשים מהם חכמים, וכולם כל ארבע מינים הללו, מתקיימים בעולם עשירים ועניים. וכולם הוא, כדי שיזכו וייטיבו אלו עם אלו, שייטיבו הצדיקים עם הרשעים להחזירם בתשובה, וייטיבו החכמים עם הטפשים, ללמדם שכל. וייטיבו העשירים עם העניים, למלאות מחסורם. כי על ידי זה, זוכה האדם לחיי עולם, ומתקשר בעץ החיים. וע\"ז אוה\"כ, פזר נתן לאביונים. ולא עוד, אלא צדקה זו שהוא עושה, עומדת לעד, דהיינו שהנוקבא נבנית ממנה, שהיא נקראת עד, שכתוב. וצדקתו עומדת לעד."],[7,"פזר נתן לאביונים:","רבי אלעזר אמר, כאשר ברא הקב\"ה את העולם, העמיד אותו על עמוד אחד, וצדיק שמו. דהיינו יסוד. וצדיק זה הוא קיום העולם, דהיינו שמקיים את הנוקבא הנקראת עולם. וזה הוא שמשקה, היינו הארת חכמה, וזן, היינו הארת חסדים, לכל. שכתוב, ונהר יוצא מעדן להשקות את הגן ומשם יפרד וגו'. שהוא היסוד המכונה נהר."],[8,"ומשם יפרד:","שואל, מהו יפרד, שאומר הכתוב. ומשיב, אלא, אותו מזון ומשקה של נהר ההוא, מקבל הכל הגן, שהוא הנוקבא, ואחר כך מתפזר המשקה לד' רוחות העולם, כלומר שבאי עולם כולם נשקים ממנה אף אחד מהם לא יחסר. וכמה הם המצפים להשתות ולהזון משם, כמש\"א, עיני \u0003כל\u0004 אליך ישברו ואתה נותן להם את אכלם בעתו. וע\"כ, \u0003פזר נתן לאביונים,\u0004 זהו הצדיק, שהוא יסוד, המפזר ונותן שפעו השלם מחכמה וחסדים המשלים לכל אביונים שבעולם. \u0003צדקתו עומדת לעד,\u0004 זוהי כנסת ישראל, שהיא הנוקבא, הנקראת צדקה. שבשביל זה, שמקבלת שפע השלם ההוא מן היסוד, היא עומדת בסוד השלום, בקיום שלם. דהיינו, עומדת לעד, \u0003רשע יראה וכעס,\u0004 זה היא מלכות עכו\"ם, דהיינו מלכות דס\"א המקנאת אז את המלכות דקדושה."],[9,"תא חזי מלכות וכו':","בוא וראה, מלכות שמים, שהיא הנוקבא דז\"א, היא בית המקדש, המקיימת כל העניים בצל משכנה של השכינה, וצדיק זה, שהוא יסוד דז\"א, הוא נקרא גבאי צדקה, לחונן ולזון את הכל, דהיינו כל העניים שהם בצילה של השכינה כנ\"ל, משום זה, גבאי צדקה מקבלים שכר, נגד כולם שנתנו להם הצדקה, להיותם מרכבה ליסוד דז\"א הנקרא גבאי צדקה, ושהוא כולל לכל הספירות שממעלה הימנו."]],[[0,"","בֹּא רְאֵה, כָּל הַזִּוּוּגִים שֶׁל הָעוֹלָם קָשִׁים לִפְנֵי הַדַּרְגָּה הַזּוֹ, מִשּׁוּם שֶׁכַּאֲשֶׁר הַזִּוּוּג הַקָּדוֹשׁ נִמְצָא, יוֹצְאוֹת כָּל הַנְּשָׁמוֹת מִתּוֹךְ הַמַּזָּל הַזֶּה לְמַעְלָה, שֶׁהוּא אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא. וְכַאֲשֶׁר הַהִשְׁתּוֹקְקוּת נִמְצֵאת מִלְּמַטָּה לְמַעְלָה, וְאָז פּוֹרְחוֹת הַנְּשָׁמוֹת, וְנִתָּנוֹת כֻּלָּן זָכָר וּנְקֵבָה יַחַד בַּדַּרְגָּה הַזּוֹ, וְאַחַר כָּךְ הוּא מַפְרִיד אוֹתָן, כָּל אַחַת וְאַחַת לִמְקוֹמָהּ כָּרָאוּי לָהּ. וְאַחַר כָּךְ קָשִׁים לִפְנֵי הַדַּרְגָּה הַזּוֹ לְחַבֵּר אוֹתָם כְּבָרִאשׁוֹנָה, מִשּׁוּם שֶׁאֵין מִתְחַבְּרִים, רַק בְּאוֹתָם דַּרְכֵי הָאָדָם, וְהַכֹּל תְּלוּיִים לְמַעְלָה."],[1,"","וְעַל כֵּן קָשִׁים לְפָנָיו כִּקְרִיעַת יַם סוּף. שֶׁהֲרֵי קְרִיעַת הַיָּם שֶׁיִּפָּתְחוּ בוֹ שְׁבִילִים הִיא לְמַעְלָה, וּכְמוֹ שֶׁנִּפְתָּחִים בּוֹ שְׁבִילִים וּדְרָכִים, כָּךְ נִבְקָע וְנִפְתָּח."],[2,"","וּמִשּׁוּם כָּךְ הַכֹּל תָּלוּי לְמַעְלָה, וּצְרִיכִים לְבָרֵךְ אוֹתוֹ וְלָתֵת לוֹ חֹזֶק מִלְּמַטָּה כְּדֵי שֶׁיִּתְבָּרֵךְ מִלְמַעְלָה וְיִתְחַזֵּק כָּרָאוּי, וְעַל כֵּן כָּתוּב וּבֵרַכְתָּ אֶת ה', דַּוְקָא אֶת."],[3,"","וּכְלַפֵּי הַמָּקוֹם הַזֶּה צָרִיךְ לְהַרְאוֹת לְפָנָיו שּׁבַע וְהֶאָרַת פָּנִים, וּכְלַפֵּי הַצַּד הָאַחֵר, בִּזְמַן שֶׁשּׁוֹלֵט בָּעוֹלָם, צָרִיךְ לְהַרְאוֹת לְפָנָיו רָעָב, שֶׁאוֹתָהּ הַדַּרְגָּה הִיא שֶׁל רָעָב, וְרָאוּי לְהַרְאוֹת לְפָנֶיהָ רָעָב וְלֹא שָׂבָע, הוֹאִיל וְהַשָּׂבָע לֹא שׁוֹלֵט בָּעוֹלָם, וְעַל כֵּן וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת ה' אֱלֹהֶיךְ. אָמַר רַבִּי אֶלְעָזָר, כָּךְ זֶה וַדַּאי וְכָךְ צָרִיךְ!"],[4,"","אָמַר רַבִּי יְהוּדָה, אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁקִּרְבָתָם הִיא שָׁלוֹם בָּעוֹלָם, מִשּׁוּם שֶׁיּוֹדְעִים לְיַחֵד אֶת הַיִּחוּד וּמְקָרְבִים קִרְבָה לְהַרְבּוֹת שָׁלוֹם בָּעוֹלָם, שֶׁהֲרֵי יוֹסֵף וִיהוּדָה בְּטֶרֶם הִתְקָרְבוּ זֶה עִם זֶה, לֹא הָיָה שָׁלוֹם. כֵּיוָן שֶׁהִתְקָרְבוּ יוֹסֵף וִיהוּדָה יַחַד, אָז הִרְבּוּ שָׁלוֹם בָּעוֹלָם, וְהַשִּׂמְחָה נוֹסְפָה לְמַעְלָה וּלְמַטָּה, כְּמוֹ שֶׁהַקִּרְבָה שֶׁל יְהוּדָה וְיוֹסֵף, וְכָל הַשְּׁבָטִים נִמְצְאוּ יַחַד עִם יוֹסֵף, וְאוֹתָהּ הַקִּרְבָה הִרְבְּתָה שָׁלוֹם בָּעוֹלָם, כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁכָּתוּב וַיִּגַּשׁ אֵלָיו יְהוּדָה."],[5,"","וְלֹא יָכֹל יוֹסֵף לְהִתְאַפֵּק לְכֹל הַנִּצָּבִים עָלָיו וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים קיב) פִּזַּר נָתַן לָאֶבְיוֹנִים צִדְקָתוֹ עֹמֶדֶת לָעַד קַרְנוֹ תָּרוּם בְּכָבוֹד. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הָעוֹלָם וְהִשְׁלִיט עָלָיו אֶת הָאָדָם שֶׁיִּהְיֶה מֶלֶךְ עַל הַכֹּל."],[6,"","וְהָאָדָם הַזֶּה נִפְרָדִים מִמֶּנּוּ בָּעוֹלָם כַּמָּה מִינִים, מֵהֶם צַדִּיקִים וּמֵהֶם רְשָׁעִים, מֵהֶם טִפְּשִׁים וּמֵהֶם חֲכָמִים, וְכֻלָּם מִתְקַיְּמִים בָּעוֹלָם, עֲשִׁירִים וַעֲנִיִּים, וְכֻלָּם כְּדֵי לִזְכּוֹת אֵלּוּ בְאֵלּוּ, לִזְכּוֹת צַדִּיקִים עִם רְשָׁעִים, לִזְכּוֹת חֲכָמִים עִם טִפְּשִׁים, לִזְכּוֹת עֲשִׁירִים עִם עֲנִיִּים, שֶׁהֲרֵי מִשּׁוּם כָּךְ זוֹכֶה הָאָדָם לְחַיֵּי הָעוֹלָם וְנִקְשָׁר בְּעֵץ הַחַיִּים. וְלֹא עוֹד, אֶלָּא שֶׁהִנֵּה הַצְּדָקָה שֶׁהוּא עוֹשֶׂה עוֹמֶדֶת לְעוֹלָמִים, שֶׁכָּתוּב וְצִדְקָתוֹ עֹמֶדֶת לָעַד."],[7,"","פִּזַּר נָתַן לָאֶבְיוֹנִים. רַבִּי אֶלְעָזָר אָמַר, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הֶעֱמִיד אוֹתוֹ עַל עַמּוּד אֶחָד וּשְׁמוֹ צַדִּיק, וְהַצַּדִּיק הַזֶּה הוּא הַקִּיּוּם שֶׁל הָעוֹלָם, וְזֶה הוּא שֶׁמַּשְׁקֶה וְזָן לַכֹּל, שֶׁכָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים."],[8,"","וּמִשָּׁם יִפָּרֵד, מַה זֶּה יִפָּרֵד? אֶלָּא הַמָּזוֹן הַהוּא וְהַמַּשְׁקֶה שֶׁל הַנָּהָר הַהוּא נוֹטֵל הַגָּן הַכֹּל, וְאַחַר כָּךְ מִתְפַּזֵר הַמַּשְׁקֶה הַהוּא לְאַרְבָּעָה צְדָדִים שֶׁל הָעוֹלָם, וְכַמָּה הֵם שֶׁמְּצַפִּים לִהְיוֹת מֻשְׁקִים וּלְהִזּוֹן מִשָּׁם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמה) עֵינֵי כֹל אֵלֶיךְ יְשַׂבֵּרוּ וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ. וּמִשּׁוּם כָּךְ פִּזַּר נָתַן לָאֶבְיוֹנִים - זֶה צַדִּיק. צִדְקָתוֹ עֹמֶדֶת לָעַד - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁמִּשּׁוּם כָּךְ הִיא עוֹמֶדֶת בְּסוֹד שֶׁל שָׁלוֹם בְּקִיּוּם שָׁלֵם. רָשָׁע יִרְאֶה וְכָעָס - זוֹ מַלְכוּת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת."],[9,"","בֹּא רְאֵה, מַלְכוּת שָׁמַיִם הִיא בֵּית הַמִּקְדָּשׁ, לְקַיֵּם כָּל הָעֲנִיִּים בְּתוֹךְ הַצֵּל שֶׁל רֵאשִׁית הַשְּׁכִינָה, וְהַצַּדִּיק הַזֶּה הוּא נִקְרָא גַּבַּאי צְדָקָה, לָחֹן וְלָזוּן אֶת הַכֹּל, שֶׁכָּתוּב פִּזַּר נָתַן לָאֶבְיוֹנִים, מִשּׁוּם כָּךְ גַּבָּאֵי צְדָקָה נוֹטְלִים שָׂכָר כְּנֶגֶד כָּל הַנּוֹתְנִים צְדָקָה."]]],[["תָּא חֲזֵי, וְלֹא יָכוֹל יוֹסֵף לְהִתְאַפֵּק לְכָל הַנִּצָּבִים, אִלֵּין אִינוּן כָּל דְּקָיְימֵי לְאִתְּזָנָא וּלְאִתְשַׁקְיָיא מִנֵּיהּ. וְלֹא עָמַד אִישׁ אִתּוֹ בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו. אִתּוֹ, דָּא כְּנֶסֶת יִשְׂרָאֵל. אֶחָיו, אִלֵּין שְׁאָר רְתִיכִין חֲיָילִין, דִּכְתִיב בְּהוּ (תהילים קכ״ב:ח׳) לְמַעַן אֲחַי וְרֵעָי. דָּבָר אַחֵר, וְלֹא עָמַד אִישׁ אִתּוֹ. בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְאִזְדַּוְּוגָא בִּכְּנֶסֶת יִשְׂרָאֵל. בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו, בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה מִתְחַבֵּר בְּהוּ בְּיִשְׂרָאֵל, בְּגִין דְּאִינוּן נָטְלֵי בִּלְחוֹדַיְיהוּ, וְלָא חִבּוּרָא דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת בַּהֲדַיְיהוּ. בְּגִין כָּךְ (במדבר כ״ט:ל״ה) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם. דְּהָא בְּזִמְנָא דָא, אִיהוּ קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי, בְּחִבּוּרָא חָדָא עִם יִשְׂרָאֵל, דִּכְתִיב בְּהוּ אֲחַי וְרֵעָי כְּמָה דְאוּקְמוּהָ.","רִבִּי יֵיסָא פָּתַח קְרָא, בְּזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לָהּ לִכְנֶסֶת יִשְׂרָאֵל מֵעַפְרָא, וְיִבָּעֵי לְאִנָּקְמָא נִקְמָתָא מֵעַמְּמַיָא עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, כְּדֵין כְּתִיב, (ישעיהו ס״ג:ג׳) וּמֵעַמִים אֵין אִישׁ אִתִּי. וּכְתִיב הָכָא, וְלֹא עָמַד אִישׁ אִתּוֹ בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ס״ג:ט׳) וַיְנַטְּלֵם וַיְנַשְּׂאֵם כָּל יְמֵי עוֹלָם.","וְלֹא יָכוֹל יוֹסֵף לְהִתְאַפֵּק, רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (תהילים קכ״ג:א׳) שִׁיר הַמַּעֲלוֹת אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי הַיּוֹשְׁבִי בַּשָּׁמָיִם, הַאי קְרָא אוּקְמוּהָ וְאִתְּמָר. אֲבָל תָּא חֲזֵי, אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי, וּכְתִיב, (תהילים קכ״א:א׳) אֶשָּׂא עֵינַי אֶל הֶהָרִים. אֶלָּא, דָּא לְעֵילָא וְדָא לְתַתָּא. אֶשָּׂא עֵינַי אֶל הֶהָרִים, דָּא לְעֵילָא. בְּגִין לְאַמְשָׁכָא בִּרְכָאן מֵעֵילָא לְתַתָּא, מֵאִלֵּין הָרִים עִלָּאִין, לְאַמְשָׁכָא מִנַּיְיהוּ בִּרְכָאן לִכְנֶסֶת יִשְׂרָאֵל דְּאִתְבָּרְכָא מִנַּיְיהוּ. אֵלֶיךָ נָשָׂאתִי אֶת עֵינַי, לְמִצְפֵּי וּלְחַכָּאָה לְאִנּוּן בִּרְכָאן דְּנָחֲתוּ מִתַּמָּן לְתַתָּא.","הַיּוֹשְׁבִי בַּשָּׁמָיִם, דְּכָל תּוּקְפָהָא וְחֵילָאָה וְקִיּוּמָהָא, אִיהוּ בַּשָּׁמַיִם. בְּגִין דְּכַד יוֹבֵלָא אַפְתַּח מַבּוּעֵי דְּכָל אִינוּן תַּרְעִין, כֻּלְּהוּ קָיְימֵי בַּשָּׁמַיִם. וְכֵיוָן דְּשָׁמַיִם נָטִיל כָּל אִינוּן נְהוֹרִין דְּנָפְקֵי מִיּוֹבֵלָא, כְּדֵין אִיהוּ זָן וְאַשְׁקֵי לָהּ לִכְנֶסֶת יִשְׂרָאֵל עַל יְדָא דְצַדִּיק חַד.","וְכֵיוָן דְּדָא אִתְעַר לְגַבָּהּ, כַּמָּה אִינוּן דְּקָיְימָן בְּכָל סִטְרִין לְאִתְשַׁקְאָה וּלְאִתְבָּרְכָא מִתַּמָּן. כְּמָא דְאַתְּ אָמֵר, (תהילים ק״ד:כ״א) הַכְּפִירִים שׁוֹאֲגִים לַטֶּרֶף וּלְבַקֵּשׁ מֵאֵל אָכְלָם. וּכְדֵין, אִיהִי סָלְקָא בְּרָזָא דְרָזִין כְּדְקָא חָזֵי (ד\"א ל\"ג ליה), וּמְקַבְּלָא עִדּוּנִין מִבַעֲלָהּ כְּדְקָא יְאוּת, וְכֻלְּהוּ דְּקָיְימִין בְּכָל סִטְרִין עָמְדֵי בִּלְחוֹדַיְיהוּ. כְּמָא דְאַתְּ אָמֵר, וְלֹא עָמַד אִישׁ אִתּוֹ. דִּכְתִיב, וַיִּקְרָא הוֹצִיאוּ כָּל אִישׁ מֵעָלַי, וּלְבָתַר דְּאִיהִי מְקַבְּלָא עִדּוּנִין מִבַּעֲלָהּ, כֻּלְּהוּ אִתְשַׁקְיָין לְבָתַר וְאִתְּזָנוּ. כְּמָא דְאַתְּ אָמֵר, (תהילים ק״ד:י״א) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם.","רִבִּי יוֹסֵי פָּתַח קְרָא בְּאֵלִיָּהוּ, דִּכְתִיב, (מלכים א י״ז:כ׳) וַיִּקְרָא אֶל ה' וַיֹּאמַר ה' אֱלהָי הֲגַם עַל הָאַלְמָנָה אֲשֶׁר אֲנִי מִתְגּוֹרֵר עִמָּהּ הֲרֵעוֹתָ לְהָמִית אֶת בְּנָהּ. תָּא חֲזֵי, תְּרֵי הֲווּ דְּקָאָמְרִין מִלִּין לָקֳבֵיל קוּדְשָׁא בְּרִיךְ הוּא, משֶׁה וְאֵלִיָּהוּ. משֶׁה אָמַר, (שמות ה׳:כ״ב) לָמָּה הֲרֵעוֹתָ לָעָם הַזֶּה. וְאֵלִיָּהוּ אָמַר, הֲרֵעוֹתָ לְהָמִית אֶת בְּנָהּ, וְתַרְוַיְיהוּ מִלָּה חָדָא קָאֲמְרוּ.","מַאי טַעְמָא. אֶלָּא רָזָא אִיהוּ. משֶׁה אָמַר, לָמָּה הֲרֵעוֹתָ, מַאי טַעְמָא. אֶלָּא, בְּגִין דְּאִתְיְהִיב רְשׁוּ לְסִטְרָא אָחֳרָא לְשַׁלְּטָאָה עֲלַיְיהוּ דְיִשְׂרָאֵל, הֲרֵעוֹתָ, יְהַבְתְּ רְשׁוּ לְסִטְרָא אָחֳרָא דְרַע, לְמִשְׁלַט עֲלַיְיהוּ. אֵלִיָּהוּ אָמַר, הֲרֵעוֹתָ יְהַבְתְּ רְשׁוּ לְסִטְרָא דְרַע, לִיטוֹל נִשְׁמָתָא דְּדָא. וְדָא הוּא הֲרֵעוֹתָ, וְכֹלָּא רָזָא חָדָא.","תָּא חֲזֵי, אֵלִיָּהוּ אָמַר, הֲגַם עַל הָאַלְמָנָה אֲשֶׁר אֲנִי מִתְגּוֹרֵר עִמָּהּ. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ לְאֵלִיָּהוּ, הִנֵּה צִוִּיתִי שָׁם אִשָּׁה אַלְמָנָה לְכַלְכְּלֶךָ. וְכָל מַאן דְּזָן וּמְפַרְנֵס לְמַאן דְּאִצְטְרִיךְ לֵיהּ, וְכָל שֶׁכֵּן בְּיוֹמָא דְכַפְנָא. הָא אִתְאַחִיד בְּאִילָנָא דְחַיֵּי, וְגָרִים לֵיהּ חַיִּים וְלִבְנוֹי, וְהָא אוֹקִימְנָא. וְהַשְׁתָּא אֵלִיָּהוּ אָמַר, כָּל מַאן דְּקִיֵּים נַפְשָׁא בְּעַלְמָא, זָכֵי לֵיהּ חַיִּים וְזָכֵי לְאִתְאַחֲדָא בְּאִילָנָא דְחַיֵּי. וְהַשְׁתָּא שָׁלְטָא אִילָנָא דְמוֹתָא סִטְרָא דְרַע עַל הָאַלְמָנָה דְּאַנְתְּ פְּקַדְתְּ לְמֵיזַן לִי. בְּגִין כָּךְ הֲרֵעוֹתָ (למה הרעות).","וְאִי תֵימָא דְּרַע לָא אִתְעֲבִיד לְבַר נָשׁ מֵעִם קוּדְשָׁא בְּרִיךְ הוּא. תָּא חֲזֵי, בְּזִמְנָא דְבַר נָשׁ אָזִיל לִימִינָא, נְטִירוּ דְקוּדְשָׁא בְּרִיךְ הוּא תָּדִיר לְגַבֵּיהּ, וְלָא יָכִיל סִטְרָא אָחֳרָא לְשַׁלְטָאָה עֲלֵיהּ. וְהַאי רָע אִתְכַּפְיָא קַמֵּיהּ, וְלָא יָכִיל לְשַׁלְּטָאָה. וְכֵיוָן דִּנְטִירָא דְקוּדְשָׁא בְּרִיךְ הוּא אִתְעַבְרָא מִנֵּיהּ, בְּגִין דְּאִיהוּ אִתְדָּבַּק בְּרָע, כְּדֵין הַהוּא רָע, כֵּיוָן דְּחָמֵי דְּלָאו עִמֵּיהּ נְטִירוּ, כְּדֵין שַׁלִּיט עֲלֵיהּ, וְאָתֵי לְשֵׁיצָאָה לֵיהּ, וּכְדֵין אִתְיְהִיב לֵיהּ רְשׁוּ, וְנָטִיל נִשְׁמָתֵיהּ."],[[0,"תא חזי, ולא יכול וגו' לכל הנצבים עליו:","אלו הם, כל העומדים להזון ולהשתות ממנו, שהיסוד שנקרא יוסף לא יכול להתאפק שלא לתת להם שפעם. ולא עמד איש אתו בהתודע יוסף אל אחיו. \u0003אתו\u0004 זוהי כנסת ישראל, שהיא הנוקבא, שלא עמד איש אתה, בהתודע וגו', דהיינו בעת הזווג, כי זווג מכונה ידיעה. \u0003אחיו,\u0004 אלו הם שאר המרכבות והצבאות, שכתוב בהם למען אחי ורעי. כלומר שבשבילם נזדווג עם הנוקבא, לתת להם שפעם. ושיעור הכתוב הוא, \u0003בהתודע יוסף,\u0004 בעת שנזדווג יוסף עם השכינה, בשביל אחיו. כי \u0003אל\u0004 פירושו בשביל."],[0,"דבר אחר ולא עמד איש אתו:","פירושו, בזמן שהקב\"ה בא להזדווג עם כנסת ישראל, \u0003בהתודע יוסף אל אחיו\u0004 פירושו, בזמן שהקב\"ה היה מתחבר בישראל, כלומר, בזמן שהקב\"ה היה מחובר עם ישראל \u0003לא עמד איש\u0004 מהאומות \u0003אתו\u0004 בעת זווגו עם הנוקבא. משום שהם בלבדם מקבלים אז מהארת הזווג, ואין חיבור מהעמים עעכו\"ם עמהם, משום זה אוה\"כ, ביום השמיני עצרת תהיה \u0003לכם,\u0004 כי בזמן ההוא, הקב\"ה הוא בחיבור אחד עם ישראל בלבדם, שכתוב בהם אחי ורעי. כמו שבארוהו. בפרשת אמור אות רפ\"ח."],[1,"ר' ייסא וכו':","ר\"י פתח הכתוב, בזמן שהקב\"ה יקום את כנסת ישראל מעפר, דהיינו בזמן הגאולה, וירצה לנקום נקמתו מעמים עובדי עכו\"ם, אז כתוב, ומעמים אין איש אתי. והיינו שכתוב כאן, ולא עמד איש אתו בהתודע יוסף אל אחיו, כמו שאתה אומר, וינטלם וינשאם כל ימי עולם."],[1,"","פירוש. כמו שנאמר בזמן הגאולה ומעמים אין איש אתי, שפירושו, שאין שום כח מס\"א שיוכל להפריעו מזה, כן הוא פירוש הכתוב, \u0003ולא עמד איש אתו,\u0004 ששום כח מס\"א לא עמד אתו להפריעו מלהתודע אל אחיו. וכן נאמר וינטלם וינשאם כל ימי עולם, דהיינו שהגביה את ישראל למעלה, באופן שכל כח שבעולם לא יזיק אותם."],[2,"ולא יכול יוסף להתאפק:","רבי חזקיה פתח ואמר, שיר המעלות אליך נשאתי את עיני היושבי בשמים. מקרא זה בארוהו ולמדנו. אבל בוא וראה, אליך נשאתי את עיני, וכתוב, אשא עיני אל ההרים. מהו ההפרש ביניהם. אלא זה למעלה וזה למטה, ומפרש, \u0003אשא עיני אל ההרים,\u0004 הוא למעלה, לז\"א, כדי להמשיך ברכות ממעלה למטה, אל הנוקבא, מאלו הרים עליונים, בסוד אין הרים אלא אבות, שהם חג\"ת דז\"א, להמשיך מהם ברכות לכנסת ישראל המתברכת מהם. \u0003אליך נשאתי את עיני,\u0004 הוא למטה לנוקבא, לצפות ולחכות לאלו הברכות היורדים משם, מז\"א, למטה לנוקבא."],[3,"היושבי בשמים:","הוקשה לו, כיון שהמדובר הוא בנוקבא, למה אומר בשמים שהוא ז\"א. ומשיב, שע\"כ אומר היושבי בשמים, משום שכל גבורותיה וכחותיה וקיומיה של הנוקבא, הם בשמים, דהיינו שמקבלתם מז\"א הנקרא שמים. כי כאשר היובל, שהוא בינה, פותח המעינות של כל אלו השערים, דהיינו השפע של נ' שערי הבינה, כולם נמצאים בשמים, שהוא ז\"א, ואחר שהשמים מקבל כל אלו האורות היוצאים מיובל, אז הוא זן ומשקה את כנסת ישראל, שהיא הנוקבא, על ידי צדיק אחד, שהוא יסוד."],[4,"וכיון דדא אתער וכו':","וכיון שזה, דהיינו היסוד, נתעורר אליה, כמה הם, העומדים בכל הצדדים, להשתות ולהתברך משם, דהיינו לקבל מהארת הזווג, כמש\"א, הכפירים שואגים לטרף וגו'. ואז היא עולה לזווג בסודי סודות כראוי, ומקבלת עדונים מבעלה כראוי לה."],[4,"וכלהו דקיימין בכל סטרין וכו':","וכל אלו העומדים בכל הצדדים, המצפים לקבל ממנה, כנ\"ל, עומדים בלבדם, ואינם עולים עם הנוקבא, כמו שאתה אומר, ולא עמד איש אתו, שכתוב ויקרא הוציאו כל איש מעלי. אלא אחר שקבלה עדנים מבעלה, דהיינו אחר הזווג, כולם נשקים אז וניזונים, כמש\"א, ישקו כל חיתו וגו'."],[5,"ר' יוסי פתח קרא באליהו דכתיב ויקרא וגו':","בוא וראה שנים היו שהטיחו דברים כנגד הקב\"ה, משה, ואליהו. משה אמר למה הרעות לעם הזה. ואליהו אמר הרעות להמית את בנה. ושניהם אמרו דבר אחד."],[6,"מ\"ט, אלא רזא איהו וכו':","שואל, מהו הטעם שאמרו שניהם, למה הרעות. ומשיב, אלא הוא סוד. משה, מהו הטעם שאמר למה הרעות, הוא משום שניתן רשות לס\"א לשלוט על ישראל, \u0003הרעות,\u0004 פירושו נתת רשות לצד האחר של ה \u0003רע\u0004 לשלוט עליהם. אליהו אמר הרעות, פירושו גם כן, נתת רשות לסטרא אחרא לטול נשמתו של זה. וזהו שאמר הרעות, והכל הוא סוד אחד, שהרעות, הוא סוד נתינת רשות לס\"א שנקרא \u0003רע.\u0004"],[7,"תא חזי אליהו אמר, הגם על האלמנה וגו':","משום שהקב\"ה אמר לאליהו, הנה צויתי שם אשה אלמנה לכלכלך. וכל מי שזן ומפרנס, למי שנצרך לו, וכל שכן בימי רעב, הוא מתאחד ונאחז בעץ החיים, וגורם חיים לעצמו ולבניו. ובארוהו. ועתה, אמר אליהו, כל מי שמקיים נפש בעולם זוכה חיים לעצמו, וזוכה להתאחד בעץ החיים, ועתה שולט עץ המות, צד הרע, על האלמנה, אשר צוית אותה לכלכלני. משום זה אמר \u0003הרעות.\u0004"],[8,"ואי תימא דרע וכו':","שואל, ואם תאמר, שלא נעשה רע לאדם מן הקב\"ה. ומשיב, בוא וראה, בזמן שאדם הולך לימין, שמירתו של הקב\"ה נמצא לו תמיד, והסטרא אחרא אינו יכול לשלוט עליו, ו \u0003רע\u0004 הזה נכנע לפניו ואינו יכול לשלוט. ומתוך ששמירתו של הקב\"ה הוסר ממנו אם הוא מתדבק ברע, אז \u0003רע\u0004 ההוא, כיון שרואה שאין עמו שמירה, שולט עליו אז ובא להשמידו, ואז ניתן לו רשות ונוטל נשמתו."]],[[0,"","בֹּא רְאֵה, וְלֹא יָכֹל יוֹסֵף לְהִתְאַפֵּק לְכָל הַנִּצָּבִים - אֵלּוּ הֵם כָּל הָעוֹמְדִים לְהִזּוֹן וּלְהִשָּׁקוֹת מִמֶּנּוּ. וְלֹא עָמַד אִישׁ אִתּוֹ בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו. אִתּוֹ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. אֶחָיו - אֵלּוּ שְׁאָר הַמֶּרְכָּבוֹת הַחֲיָלוֹת, שֶׁכָּתוּב בָּהֶם לְמַעַן אַחַי וְרֵעַי. דָּבָר אַחֵר וְלֹא עָמַד אִישׁ אִתּוֹ - בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִתְחַבֵּר עִם כְּנֶסֶת יִשְׂרָאֵל. בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מִתְחַבֵּר בָּהֶם בְּיִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם נוֹטְלִים לְבַדָּם, וְלֹא חִבּוּר שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת עִמָּם. מִשּׁוּם כָּךְ, (במדבר כט) בַּיּוֹם הַשְּׁמִינִי עֲצֶרֶת תִּהְיֶה לָכֶם, שֶׁהֲרֵי בַּזְּמַן הַזֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַדּוֹ בְּחִבּוּר אֶחָד עִם יִשְׂרָאֵל, שֶׁכָּתוּב בָּהֶם לְמַעַן אַחַי וְרֵעַי, כְּמוֹ שֶׁבֵּאֲרוּהָ."],[1,"","רַבִּי יֵיסָא פָּתַח הַפָּסוּק, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יָקִים אֶת כְּנֶסֶת יִשְׂרָאֵל מִן הֶעָפָר וְיִרְצֶה לְהִנָּקֵם נְקָמָה מֵעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, אֲזַי כָּתוּב (ישעיה סג) וּמֵעַמִּים אֵין אִישׁ אִתִּי, וְכָתוּב כָּאן וְלֹא עָמַד אִישׁ אִתּוֹ בְּהִתְוַדַּע יוֹסֵף אֶל אֶחָיו, כְּמוֹ שֶׁנֶּאֱמַר וַיְנַטְּלֵם וַיְנַשְּׂאֵם כָּל יְמֵי עוֹלָם."],[2,"","וְלֹא יָכֹל יוֹסֵף לְהִתְאַפֵּק. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (תהלים קכג) שִׁיר הַמַּעֲלוֹת אֵלֶיךְ נָשָׂאתִי אֶת עֵינַי הַיֹּשְׁבִי בַּשָּׁמָיִם. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ וְנִתְבָּאֵר, אֲבָל בּא רְאֵה, אֵלֶיךְ נָשָׂאתִי אֶת עֵינַי, וְכָתוּב (תהלים קכא) אֶשָּׂא עֵינַי אֶל הֶהָרִים. אֶלָּא, זֶה לְמַעְלָה וְזֶה לְמַטָּה. אֶשָּׂא עֵינַי אֶל הֶהָרִים - זֶה לְמַעְלָה, כְּדֵי לְהַמְשִׁיךְ בְּרָכוֹת מִמַּעְלָה לְמַטָּה, מֵהֶהָרִים הַלָּלוּ הָעֶלְיוֹנִים לִמְשֹׁךְ מֵהֶם בְּרָכוֹת לִכְנֶסֶת יִשְׂרָאֵל שֶׁמִּתְבָּרֶכֶת מֵהֶם. אֵלֶיךְ נָשָׂאתִי אֶת עֵינַי, לְצַפּוֹת וּלְחַכּוֹת לְאוֹתָן בְּרָכוֹת שֶׁיּוֹרְדוֹת מִשָּׁם לְמַטָּה."],[3,"","הַיּשְׁבִי בַּשָּׁמָיִם, שֶׁכָּל תָּקְפָּהּ וְקִיּוּמָהּ וְחֵילָהּ הוּא בַּשָּׁמַיִם. מִשּׁוּם שֶׁכַּאֲשֶׁר הַיּוֹבֵל פּוֹתֵחַ הַמַּעְיָנוֹת שֶׁל כָּל אוֹתָם הַשְּׁעָרִים, כֻּלָּם עוֹמְדִים בַּשָּׁמַיִם. וְכֵיוָן שֶׁשָּׁמַיִם נוֹטְלִים כָּל אוֹתָם אוֹרוֹת שֶׁיּוֹצְאִים מֵהַיּוֹבֵל, אָז הוּא זָן וּמַשְׁקֶה אֶת כְּנֶסֶת יִשְׂרָאֵל עַל יְדֵי צַדִּיק אֶחָד."],[4,"","וְכֵיוָן שֶׁזֶּה מִתְעוֹרֵר אֵלֶיהָ, כַּמָּה הֵם שֶׁעוֹמְדִים בְּכָל הַצְּדָדִים לִהְיוֹת מֻשְׁקִים וּלְהִתְבָּרֵךְ מִשָּׁם, כְּמוֹ שֶׁנֶּאֱמַר הַכְּפִירִים שּאֲגִים לַטָּרֶף וּלְבַקֵּשׁ מֵאֵל אָכְלָם. וְאָז הִיא עוֹלָה בְּסוֹד הַסּוֹדוֹת כָּרָאוּי (לו), וּמְקַבֶּלֶת עִדּוּנִים מִבַּעְלָהּ כָּרָאוּי, וְכָל הָעוֹמְדִים בְּכָל הַצְּדָדִים עוֹמְדִים לְבַדָּם, כְּמוֹ שֶׁנֶּאֱמַר וְלֹא עָמַד אִישׁ אִתּוֹ, שֶׁכָּתוּב וַיִּקְרָא הוֹצִיאוּ כָל אִישׁ מֵעָלָי. וְאַחַר שֶׁהִיא מְקַבֶּלֶת עִדּוּנִים מִבַּעְלָהּ, כֻּלָּם נִשְׁקִים לְאַחַר מִכֵּן וְנִזּוֹנִים, כְּמוֹ שֶׁנֶּאֱמַר יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם."],[5,"","רַבִּי יוֹסֵי פָּתַח הַפָּסוּק בְּאֵלִיָּהוּ, שֶׁכָּתוּב (מלכים א יז) וַיִּקְרָא אֶל ה' וַיֹּאמַר ה' אֱלֹהָי הֲגַם עַל הָאַלְמָנָה אֲשֶׁר אֲנִי מִתְגּוֹרֵר עִמָּהּ הֲרֵעוֹתָ לְהָמִית אֶת בְּנָהּ. בֹּא רְאֵה, שְׁנַיִם הָיוּ שֶׁאָמְרוּ דְבָרִים כְּנֶגֶד הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה וְאֵלִיָּהוּ. מֹשֶׁה אָמַר (שמות ה) לָמָה הֲרֵעֹתָה לָעָם הַזֶּה. וְאֵלִיָּהוּ אָמַר, הֲרֵעוֹתָ לְהָמִית אֶת בְּנָהּ. וּשְׁנֵיהֶם אָמְרוּ דָבָר אֶחָד."],[6,"","מָה הַטַּעַם? אֶלָּא סוֹד הוּא. מֹשֶׁה אָמַר לָמָה הֲרֵעֹתָה, מָה הַטַּעַם? אֶלָּא מִשּׁוּם שֶׁנִּתְּנָה רְשׁוּת לַצַּד הָאַחֵר לִשְׁלֹט עַל יִשְׂרָאֵל. הֲרֵעֹתָה - נָתַתָּ רְשׁוּת לַצַּד הָאַחֵר שֶׁל רַע לִשְׁלֹט עֲלֵיהֶם. אֵלִיָּהוּ אָמַר הֲרֵעוֹתָ - נָתַן רְשׁוּת לַצַּד הָרָע לִטֹּל נִשְׁמָתוֹ שֶׁל זֶה, וְזֶהוּ הוּא הֲרֵעוֹתָ, וְהַכֹּל סוֹד אֶחָד."],[7,"","בֹּא רְאֵה, אֵלִיָּהוּ אָמַר, הֲגַם עַל הָאַלְמָנָה אֲשֶׁר אֲנִי מִתְגּוֹרֵר עִמָּהּ. מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ לְאֵלִיָּהוּ, הִנֵּה צִוִּיתִי שָׁם אִשָּׁה אַלְמָנָה לְכַלְכְּלֶךְ, וְכָל מִי שֶׁזָּן וּמְפַרְנֵס לְמִי שֶׁצָּרִיךְ לוֹ, וְכָל שֶׁכֵּן בִּימֵי רָעָב, הֲרֵי נֶאֱחָז בְּעֵץ הַחַיִּים, וְגוֹרֵם לוֹ וּלְבָנָיו חַיִּים, וְהִנֵּה בֵּאַרְנוּ. וְעַכְשָׁו אֵלִיָּהוּ אָמַר, כָּל מִי שֶׁמְּקַיֵּם נֶפֶשׁ בָּעוֹלָם, זוֹכֶה לוֹ חַיִּים, וְזוֹכֶה לְהֵאָחֵז בְּעֵץ הַחַיִּים, וְעַכְשָׁו שׁוֹלֵט עֵץ הַמָּוֶת, הַצַּד שֶׁל רַע, עַל הָאַלְמָנָה שֶׁאַתָּה צִוִּיתָ לָזוּן אוֹתִי, מִשּׁוּם כָּךְ הֲרֵעוֹתָ (למה הרעתה)."],[8,"","וְאִם תֹּאמַר שֶׁרַע לֹא נַעֲשֶׂה לְאִישׁ מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא - בֹּא רְאֵה, בִּזְמַן שֶׁאָדָם הוֹלֵךְ לְיָמִין, שְׁמִירָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד אֶצְלוֹ, וְלֹא יָכוֹל הַצַּד הָאַחֵר לִשְׁלֹט עָלָיו, וְהָרָע הַזֶּה נִכְנָע לְפָנָיו וְלֹא יָכוֹל לִשְׁלֹט. וְכֵיוָן שֶׁשְּׁמִירַת הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹבֶרֶת מִמֶּנּוּ, מִשּׁוּם שֶׁהוּא נִדְבָּק בָּרָע, אָז אוֹתוֹ הָרָע, כֵּיוָן שֶׁרוֹאֶה שֶׁאֵין עִמּוֹ שְׁמִירָה, אָז שׁוֹלֵט עָלָיו וּבָא לְהַשְׁמִיד אוֹתוֹ, וְאָז נִתֶּנֶת לוֹ רְשׁוּת וְנוֹטֵל אֶת נִשְׁמָתוֹ."]]],[["משֶׁה אָמַר לָמָּה הֲרֵעוֹתָ, דְּאִתְיְהִיב לֵיהּ רְשׁוּ לְסִטְרָא דְרָע, לְמִשְׁלַט עֲלַיְיהוּ דְיִשְׂרָאֵל, לְמֶהֱוֵי בְּשִׁעְבּוּדָא דִילֵיהּ. דָּבָר אַחֵר לָמָּה הֲרֵעוֹתָ, דְּחָמָא כַּמָּה מִנְהוֹן דְּהֲווּ מֵתִין, וְאִתְמְסָרוּ בְּסִטְרָא דְרָע.","תָּא חֲזֵי, בְּשַׁעְתָּא דְּטוֹב אִתְעַר, דְּאִיהוּ יְמִינָא, כָּל חֵידוּ, וְכָל טִיבוּ, וְכָל בִּרְכָאן מִשְׁתַּכְּחָן, וְכֹלָּא בַּחֲשַׁאי אִיהוּ, כְּמָה דְאוּקְמוּהָ, דְּאָמְרֵי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד בַּחֲשַׁאי, וְרָזָא דָא בְּגִין (ס\"א דהאי איהו יחודא) דְּאִיהוּ כְּדֵין יִחוּדָא כְּדְקָא חָזֵי.","אָמַר רִבִּי חִיָּיא, וְכִי אֵלִיָּהוּ, כֵּיוָן דְּאִיהוּ גָּזַר, וְקוּדְשָׁא בְּרִיךְ הוּא מְקַיֵּים. וְאִיהוּ גָּזִיר עַל שְׁמַיָא, דְּלָא לַאֲחָתָא מִטְרָא וְטַלָּא, הֵיךְ דָּחִיל אִיהוּ מֵאִיזֶבֶל, דְּשַׁדְּרַת לֵיהּ. דִּכְתִיב, (מלכים א י״ט:ב׳) כִּי כָעֵת מָחָר אָשִׂים אֶת נַפְשְׁךָ כְּנֶפֶשׁ אַחַד מֵהֶם, וּמִיָּד דָּחִיל וְעָרַק עַל נַפְשֵׁיהּ.","אָמַר לֵיהּ רִבִּי יוֹסֵי, הָא אוּקְמוּהָ, דְּצַדִּיקַיָא לָא בָּעָאן לְאַטְרָחָא לְמָארֵיהוֹן, בְּאֲתַר דְּנִזְקָא אִשְׁתַּכְּחַת (ליה) לְעֵינָא. כְּגַוְונָא דִשְׁמוּאֵל, דִּכְתִיב, (שמואל א ט״ז:ב׳) אֵיךְ אֵלֵךְ וְשָׁמַע שָׁאוּל וַהֲרָגָנִי, אָמַר לֵיהּ, עֶגְלַת בָּקָר תִּקַּח בְּיָדֶךָ. בְּגִין דְּצַדִּיקַיָּא לָא בָּעָאן לְאַטְרָחָא לְמָארֵיהוֹן בְּאֲתַר דְּנִזְקָא אִשְׁתַּכַּח. אוּף הָכִי אֵלִיָּהוּ, כֵּיוָן דְּחָמָא דְּנִזְקָא אִשְׁתַּכַּח, לָא בָּעֵי לְאַטְרָחָא לְמָארֵיהּ.","אָמַר לֵיהּ, אֲנָא מִלָּה שְׁמַעְנָא, דְּהָא בְּאֵלִיָּהוּ לָא כְּתִיב בֵּיהּ וַיִּירָא וַיֵּלֶךְ אֶל נַפְשׁוֹ, אֶלָּא (מלכים א י״ט:ג׳) וַיַּרְא. רְאִיָה חָמָא. וּמַה חָמָא, אֶלָּא חָמָא דְּהָא מִכַּמָּה שְׁנִין אֲזַל בַּתְרֵיהּ מַלְאַךְ הַמָּוְת, וְלָא אִתְמָסַר בִּידֵיהּ. וְהַשְׁתָּא וַיֵּלֶךְ אֶל נַפְשׁוֹ, מַאי וַיֵּלֶךְ אֶל נַפְשׁוֹ, אֲזַל לְקִיּוּמָא דְנַפְשָׁא, וּמַאן אִיהוּ אִילָנָא דְחַיֵּי לְאִתְדַּבְּקָא תַּמָּן.","תָּא חֲזֵי, כֻּלְּהוּ כְּתִיב אֶת נַפְשׁוֹ, וְהָכָא כְּתִיב אֶל נַפְשׁוֹ, וְרָזָא דָא שְׁמַעְנָא, דְּאָמַר רִבִּי שִׁמְעוֹן, כָּל נִשְׁמָתִין דְּעַלְמָא, כֻּלְּהוּ נָפְקֵי מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק, וְכֻלְּהוּ נָקִיט לוֹן הַהוּא צְרוֹרָא דְחַיָּיא (דחיי), וְכַד נוּקְבָא אִתְעַבְּרַת מִן דְּכוּרָא, כֻּלְּהוּ בְּתִיאוּבְתָּא דִּתְרֵין סִטְרִין, בְּתִיאוּבְתָּא דְּנוּקְבָא לְגַבֵּי דְכוּרָא. וְכַד תִּיאוּבְתָּא דִּדְכוּרָא נָפְקָא בִּרְעוּתָא, כְּדֵין אִינוּן נִשְׁמָתִין בְּקִיּוּמָא יַתִּיר, בְּגִין דְּכֹלָּא בְּתִיאוּבְתָּא וּרְעוּ דְּאִילָנָא דְּחַיָּיא. וְאֵלִיָּהוּ, בְּגִין דְּהֲוָה מֵהַהוּא רְעוּתָא יַתִּיר מִבַּר נָשׁ אָחֳרָא, אִתְקְיַּים.","וּבְגִין כָּךְ אֶל נַפְשׁוֹ כְּתִיב, וְלָא כְּתִיב אֶת נַפְשׁוֹ. דְּהָא אֶת נַפְשׁוֹ דָּא הִיא נוּקְבָא. וְאִי תֵימָא וְאֶל הָאִשָּׁה אָמַר, כְּלָלָא דִּדְּכַר וְנוּקְבָא. כַּד הִיא בְּגוֹ דְּכוּרָא, כְּדֵין וְאֶל הָאִשָּׁה אָמַר. אֶת הָאִשָּׁה, נוּקְבָא בִּלְחוּדָהָא, וְלָא דִּדְּכוּרָא. כְּגַוְונָא דָא אֶל נַפְשׁוֹ, דָּכָר בִּלְחוֹדוֹי, אֶת נַפְשׁוֹ נוּקְבָא בִּלְחוּדָהָא וְלָא כְּלִילוּ דִּדְּכוּרָא. וּבְגִין דְּאִיהוּ מִסִּטְרָא דִּדְּכוּרָא יַתִּיר מִכָּל בְּנֵי עַלְמָא, אִתְקְיַּים בְּקִיּוּמֵיהּ יַתִּיר, וְלָא מִית כִּשְׁאָר בְּנֵי עַלְמָא. בְּגִין דְּכֹלָּא אִיהוּ מֵאִילָנָא דְחַיֵּי, וְלָא מִגּוֹ עַפְרָא. וּבְגִין דָּא אִסְתַּלַּק לְעֵילָא, וְלָא מִית כְּאֹרַח כָּל בְּנֵי עַלְמָא. דִּכְתִיב, (מלכים ב ב׳:י״א) וַיַּעַל אֵלִיָּהוּ בִּסְעָרָה הַשָּׁמַיִם.","תָּא חֲזֵי, מַה כְּתִיב וְהִנֵּה רֶכֶב אֵשׁ וְסוּסֵי אֵשׁ וְגו', (שמות קצז ע\"א) דְּהָא כְּדֵין אִתְפַּשַּׁט גּוּפָא מִן רוּחָא, וְאִסְתַּלַּק דְּלָא כִּשְׁאָר אֹרַח בְּנֵי עַלְמָא. וְאִשְׁתָּאַר מַלְאֲכָא קַדִּישָׁא, כִּשְׁאָר קַדִּישֵׁי עֶלְיוֹנִין, וְעָבִיד שְׁלִיחוּתָא בְעַלְמָא. וְהָא אוּקְמוּהָ, דְּנִסִּין דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּעַלְמָא, עַל יְדֵיהּ אִתְעֲבִידָן.","וְתָא חֲזֵי, מַה כְּתִיב, (מלכים א י״ט:ג׳) וַיִּשְׁאַל אֶת נַפְשׁוֹ. בְּקַדְמִיתָא, וַיֵּלֶךְ אֶל נַפְשׁוֹ, כְּמָה דְאִתְּמָר בְּקִיּוּמָא. וְהָכָא אֶת נַפְשׁוֹ לָמוּת, אִילָנָא דְבֵיהּ שַׁרְיָא מוֹתָא. וְתַמָּן אִתְגְּלִי עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דִכְתִיב, (מלכים א י״ט:י״ב) צֵא וְעָמַדְתָּ בָּהָר. מַה כְּתִיב בַּתְרֵיהּ, וְאַחַר הָרַעַשׁ אֵשׁ לא בָאֵשׁ ה' וְאַחַר הָאֵשׁ קוֹל דְּמָמָה דַקָּה, דָּא הוּא אֲתַר פְּנִימָאָה דְּכֹלָּא, דְּמִנֵּיהּ נָפְקִין כָּל נְהוֹרִין.","מַה כְּתִיב, (מלכים א י״ט:י״ג) וַיְהִי כִּשְׁמֹעַ אֵלִיָּהוּ וַיָּלֶט פָּנָיו בְּאַדַּרְתּוֹ וְהִנֵּה אֵלָיו קוֹל וַיֹּאמֶר (תשא ק\"ץ ע\"א) מַה לְּךָ פֹה אֵלִיָּהוּ וַיֹּאמֶר קַנֹּא קִנֵּאתִי, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, עַד מָתַי אַתָּה מְקַנֵּא לִי, טְרָקַת גַּלָּא דְּלָא יָכִיל לְשַׁלְּטָאָה בָּךְ מוֹתָא לְעָלְמָא, וְעַלְמָא לָא יָכִיל לְמִסְבְּלָךְ עִם בָּנַי (נשא). אָמַר לֵיהּ, כִּי עָזְבוּ בְרִיתְךָ בְּנִי יִשְׂרָאֵל וְגו'. אָמַר לֵיהּ, חַיֶּיךָ, דְּבְּכָל אֲתַר דְּבָנַי (נשא) יְקַיְּימוּ קְיָים קַדִּישָׁא, אַנְתְּ תְּהֵא זַמִּין תַּמָּן. (ד\"א והא אתמר בגין כך מתקנין כורסיא לאליהו דאיהו זמין תמן)"],[[0,"משה אמר למה הרעות:","משום שניתן רשות לצד הרע לשלוט על ישראל, להיות תחת השעבוד שלו. פירוש אחר, ע\"כ אמר, למה הרעות, כי ראה כמה מהם מישראל, שהם מתים, ונמסרו בצד \u0003הרע.\u0004"],[1,"תא חזי בשעתא וכו':","בוא וראה בשעה שהטוב נתעורר, שהוא ימין, כל שמחה וכל טוב וכל הברכות נמצאות, והכל הוא בחשאי, כמו שבארו, שאמרו בני יעקב, ברוך שם כבוד מלכותו לעולם ועד, בחשאי. (פסחים נ\"ו ע\"א) וסוד זה הוא משום, שאז הוא יחוד כראוי. ובזה מתבאר הכתוב למה אמר יוסף בעת היחוד, הוציאו כל איש מעלי, משום שהיחוד צריך להיות בחשאי."],[2,"אמר ר' חייא וכו':","אר\"ח, וכי אליהו, כיון שהוא גזר והקב\"ה מקיים, והוא גזר על השמים שלא להוריד טל ומטר, איך היה מפחד מאזבל, ששלחה אליו ככתוב, כי כעת מחר אשים את נפשך כנפש אחד מהם, ומיד פחד וברח על נפשו."],[3,"א\"ל רבי יוסי וכו':","אמר לו ר\"י, הרי בארוהו, שהצדיקים אינם רוצים להטריח לאדונם במקום שהנזק מצוי לעין. כמו שמואל, שאמר, איך אלך ושמע שאול והרגני אמר לו עגלת בקר וגו'. משום שהצדיקים אינם רוצים להטריח את אדונם במקום שהנזק מצוי, וגם כן אליהו, כיון שראה שהנזק מצוי לא רצה להטריח את אדונו."],[4,"א\"ל אנא מלה וכו':","אמר לו, אני שמעתי כאן דבר. כי באליהו לא כתוב בו, \u0003ויירא\u0004 וילך אל נפשו, אלא \u0003וירא,\u0004 שפירושו שראה ראיה, ומה ראה, אלא שראה, שמכמה שנים הלך אחריו מלאך המות, ולא נמסר בידו, ועתה \u0003וילך אל נפשו,\u0004 מה פירושו של וילך אל נפשו, הוא, שהלך לקיום של הנפש ומי הוא, הוא עץ החיים, כדי להתדבק שם, ומלאך המות לא ילך אחריו יותר."],[5,"תא חזי כלהו וכו':","בוא וראה, בכל מקום כתוב \u0003את\u0004 נפשו, וכאן כתוב \u0003אל\u0004 נפשו. וסוד הזה שמעתי, כי אמר ר' שמעון, כל הנשמות שבעולם יוצאות כולן מאותו הנהר הנמשך ויוצא, שהוא יסוד דז\"א, וכולן לוקח אותן אותו צרור החיים, שהוא הנוקבא, וכשהנוקבא מתעברת מן הזכר, כולן הן בהשתוקקות מב' הצדדים, מהשתוקקות הנקבה אל הזכר, ומהשתוקקות הזכר אל הנקבה, (כנ\"ל לך אות ר\"ה) וכשהשתוקקות הזכר יוצאת בחשק גדול, אז הנשמות הן יותר בקיום, משום שהכל תלוי בהשתוקקות וחשק של עץ החיים, שהוא ז\"א, ואליהו, מתוך שהיה מאותו החשק של הזכר, יותר מאנשים אחרים, הוא נתקיים ולא מת."],[6,"ובגין כך אל וכו':","ומשום זה כתוב, \u0003אל\u0004 נפשו ולא כתוב \u0003את\u0004 נפשו, כי \u0003את\u0004 נפשו היא נקבה, שהנוקבא נקראת \u0003את,\u0004 אבל \u0003אל\u0004 הוא זכר. ואם תאמר, הרי כתוב \u0003ואל\u0004 האשה אמר, שהיא נקבה. ומשיב, הוא כלל של זכר ונקבה, כי כאשר הנוקבא כלולה בתוך הזכר, נאמר אז, \u0003ואל\u0004 האשה אמר. \u0003את\u0004 האשה, יורה נקבה בלבדה, בלי התכללות עם הזכר. כעין זה אל נפשו, יורה זכר בלבד. את נפשו יורה נקבה בלבדה, בלי התכללות עם הזכר. ומשום שאליהו הוא מצד הזכר יותר מכל בני העולם, נתקיים בקיומו יותר, מכל בני העולם, ולא מת כשאר בני העולם. משום שכולו הוא מעץ החיים, ולא מן עפר כשאר אנשים, ומשום זה נסתלק למעלה ולא מת כדרך כל בני העולם, שכתוב, ויעל אליהו בסערה השמים."],[7,"תא חזי מה כתיב וכו':","בוא וראה מה כתוב, והנה רכב אש וסוסי אש וגו'. כי אז נתפשט הגוף מן הרוח, ונסתלק שלא כדרך שאר בני אדם, ונשאר מלאך קדוש כשאר קדושים עליונים, ועושה שליחות בעולם כמו מלאך, ובארוה, שהנסים שעושה הקב\"ה בעולם, על ידו נעשים."],[8,"ותא חזי מה כתיב, וישאל את נפשו.","מקודם לכן כתוב וילך \u0003אל\u0004 נפשו, כמו שלמדנו, שהוא בקיום, וכאן כתוב, \u0003את\u0004 נפשו למות. יורה על העץ שבו שורה המות, דהיינו הנוקבא, בסו\"ה ורגליה יורדות מות, ושם נגלה עליו הקב\"ה, כמ\"ש, צא ועמדת בהר."],[8,"מה כתיב בתריה וכו':","מה כתוב אחריו, ואחר הרעש אש וגו' קול דממה דקה. זה הוא מקום הפנימי מכולם שממנו כל האורות יוצאים."],[9,"מה כתיב, ויהי כשמוע אליהו וגו':","אמר לו הקב\"ה עד מתי אתה מקנא לי, סגרת הדלת, שהמות לא ישלוט עליך לעולם, והעולם אינו יכול לסבלך שתמצא עם בני, שאתה מקטרג עליהם, א\"ל כי עזבו בריתך בני ישראל וגו'. אמר לו, חייך, שבכל מקום שבני אדם יקיימו ברית הקדוש, דהיינו שיעשו ברית מילה, אתה תהיה מצוי שם. (וביאור הדברים תמצא בהקדמת ספר הזהר דף ר\"י ד\"ה למהוי)."]],[[0,"","מֹשֶׁה אָמַר לָמָה הֲרֵעֹתָה, שֶׁנִּתְּנָה רְשׁוּת לַצַּד הָרָע לִשְׁלֹט עַל יִשְׂרָאֵל, לִהְיוֹת בַּשִּׁעְבּוּד שֶׁלּוֹ. דָּבָר אַחֵר לָמָה הֲרֵעֹתָה - שֶׁרָאָה כַּמָּה מֵהֶם שֶׁהָיוּ מֵתִים וְנִמְסְרוּ לַצַּד הָרָע."],[1,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁהַטּוֹב מִתְעוֹרֵר, שֶׁהוּא הַיָּמִין, כָּל הַשִּׂמְחָה וְכָל הַטּוּב וְכָל הַבְּרָכוֹת נִמְצָאוֹת, וְהַכֹּל הוּא בַּחֲשַׁאי, כְּמוֹ שֶׁבֵּאֲרוּהָ שֶׁאוֹמְרִים בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד בַּחֲשַׁאי, וְזֶה הַסּוֹד, מִשּׁוּם (שזהו יחוד) שֶׁאָז הוּא הַיִּחוּד כָּרָאוּי."],[2,"","אָמַר רַבִּי חִיָּיא, וְכִי אֵלִיָּהוּ, כֵּיוָן שֶׁהוּא גּוֹזֵר וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְקַיֵּם, וְהוּא גָּזַר עַל הַשָּׁמַיִם שֶׁלֹּא לְהוֹרִיד טַל וּמָטָר, אֵיךְ הוּא פָּחַד מֵאִיזֶבֶל שֶׁשָּׁלְחָה לוֹ, שֶׁכָּתוּב (מלכים א יט) כִּי כָעֵת מָחָר אָשִׂים אֶת נַפְשְׁךְ כְּנֶפֶשׁ אַחַד מֵהֶם, וּמִיָּד פָּחַד וּבָרַח עַל נַפְשׁוֹ?"],[3,"","אָמַר לוֹ רַבִּי יוֹסֵי, הִנֵּה פֵּרְשׁוּהָ שֶׁהַצַּדִּיקִים לֹא רוֹצִים לְהַטְרִיחַ אֶת רִבּוֹנָם בְּמָקוֹם שֶׁנֵּזֶק נִמְצָא (לו) לָעַיִן, כְּמוֹ שֶׁשְּׁמוּאֵל, שֶׁכָּתוּב (שמואל א טז) אֵיךְ אֵלֵךְ וְשָׁמַע שָׁאוּל וַהֲרָגָנִי. אָמַר לוֹ, עֶגְלַת בָּקָר תִּקַּח בְּיָדֶךְ, מִשּׁוּם שֶׁצַּדִּיקִים לֹא רוֹצִים לְהַטְרִיחַ אֶת רִבּוֹנָם בְּמָקוֹם שֶׁנִּמְצָא נֶזֶק. אַף כָּךְ אֵלִיָּהוּ, כֵּיוָן שֶׁרָאָה שֶׁנֶּזֶק נִמְצָא, לֹא רָצָה לְהַטְרִיחַ אֶת רִבּוֹנוֹ."],[4,"","אָמַר לוֹ, אֲנִי שָׁמַעְתִּי דָבָר, שֶׁהִנֵּה בְּאֵלִיָּהוּ לֹא כָתוּב בּוֹ וַיִּירָא וַיֵּלֶךְ אֶל נַפְשׁוֹ, אֶלָּא וַיַּרְא, רְאִיָּה רָאָה. וּמָה רָאָה? אֶלָּא רָאָה שֶׁהִנֵּה מִכַּמָּה שָׁנִים הוֹלֵךְ אַחֲרָיו מַלְאַךְ הַמָּוֶת, וְלֹא נִמְסָר בְּיָדוֹ, וְעַכְשָׁו וַיֵּלֶךְ אֶל נַפְשׁוֹ. מַה זֶּה וַיֵּלֶךְ אֶל נַפְשׁוֹ? הָלַךְ לְקִיּוּם הַנֶּפֶשׁ, וּמִי הוּא? עֵץ הַחַיִּים לְהִדָּבֵק שָׁם."],[5,"","בֹּא רְאֵה, כֻּלָּם כָּתוּב אֶת נַפְשׁוֹ, וְכָאן כָּתוּב אֶל נַפְשׁוֹ, וְסוֹד זֶה שָׁמַעְתִּי, שֶׁאָמַר רַבִּי שִׁמְעוֹן, כָּל הַנְּשָׁמוֹת שֶׁל הָעוֹלָם, כֻּלָּם יוֹצְאִים מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, וְאֶת כֻּלָּם הוּא לוֹקֵחַ אוֹתוֹ צְרוֹר הַחַיִּים, וּכְשֶׁהַנְּקֵבָה מִתְעַבֶּרֶת מִן הַזָּכָר, כֻּלָּם בִּתְשׁוּקַת שְׁנֵי הַצְּדָדִים, בִּתְשׁוּקַת הַנְּקֵבָה לַזָּכָר, וּכְשֶׁתְּשׁוּקַת הַזָּכָר יוֹצֵאת בְּרָצוֹן, אָז אוֹתָן הַנְּשָׁמוֹת בְּקִיּוּם יוֹתֵר, מִשּׁוּם שֶׁהַכֹּל בִּתְשׁוּקָה וְרָצוֹן שֶׁל עֵץ הַחַיִּים. וְאֵלִיָּהוּ, מִשּׁוּם שֶׁהָיָה מֵאוֹתוֹ רָצוֹן יוֹתֵר מֵאָדָם אַחֵר, הִתְקַיֵּם."],[6,"","וּמִשּׁוּם כָּךְ כָּתוּב אֶל נַפְשׁוֹ, וְלֹא כָתוּב אֶת נַפְשׁוֹ, שֶׁהֲרֵי אֶת נַפְשׁוֹ - זוֹ הַנְּקֵבָה. וְאִם תֹּאמַר וְאֶל הָאִשָּׁה אָמַר - הַכְּלָלוּת שֶׁל זָכָר וּנְקֵבָה כְּשֶׁהִיא בְּתוֹךְ הַזָּכָר, אָז וְאֶל הָאִשָּׁה אָמַר. אֶת הָאִשָּׁה - הַנְּקֵבָה לְבַדָּהּ, וְלֹא שֶׁל הַזָּכָר. כְּמוֹ זֶה אֶל נַפְשׁוֹ - הַזָּכָר לְבַדּוֹ. אֶת נַפְשׁוֹ - הַנְּקֵבָה לְבַדָּהּ וְלֹא הִתְכַּלְּלוּת שֶׁל זָכָר. וּמִשּׁוּם שֶׁהוּא מִצַּד הַזָּכָר יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם, הִתְקַיֵּם בְּקִיּוּמוֹ יוֹתֵר, וְלֹא מֵת כִּשְׁאָר בְּנֵי הָעוֹלָם, מִשּׁוּם שֶׁהַכֹּל הוּא מֵעֵץ הַחַיִּים, וְלֹא מִתּוֹךְ הֶעָפָר. וּמִשּׁוּם כָּךְ הִסְתַּלֵּק לְמַעְלָה וְלֹא מֵת כְּדֶרֶךְ כָּל בְּנֵי הָעוֹלָם, שֶׁכָּתוּב (מלכים ב ב) וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמָיִם."],[7,"","בֹּא רְאֵה מַה כָּתוּב, וְהִנֵּה רֶכֶב אֵשׁ וְסוּסֵי אֵשׁ וְגוֹ', שֶׁהֲרֵי אָז הִתְפַּשֵּׁט הַגּוּף מִן הָרוּחַ וְהִסְתַּלֵּק שֶׁלֹּא כִּשְׁאָר דֶּרֶךְ בְּנֵי הָעוֹלָם, וְנִשְׁאָר מַלְאָךְ קָדוֹשׁ כִּשְׁאָר קְדוֹשִׁים עֶלְיוֹנִים, וְעוֹשֶׂה שְׁלִיחוּת בָּעוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁהַנִּסִּים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם, נַעֲשִׂים עַל יָדוֹ."],[8,"","וּבֹא וּרְאֵה מַה כָּתוּב, וַיִּשְׁאַל אֶת נַפְשׁוֹ. בָּרִאשׁוֹנָה וַיֵּלֶךְ אֶל נַפְשׁוֹ, כְּמוֹ שֶׁנִּתְבָּאֵר בַּקִּיּוּם, וְכָאן אֶת נַפְשׁוֹ לָמוּת, הָעֵץ שֶׁבּוֹ שׁוֹרֶה הַמָּוֶת, וְשָׁם נִגְלָה עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא, כַּכָּתוּב צֵא וְעָמַדְתָּ בָהָר. מַה כָּתוּב אַחֲרָיו? וְאַחַר הָרַעַשׁ אֵשׁ לֹא בָאֵשׁ ה' וְאַחַר הָאֵשׁ קוֹל דְּמָמָה דַקָּה. זֶהוּ הַמָּקוֹם הַפְּנִימִי שֶׁל הַכֹּל, שֶׁמִּמֶּנּוּ יוֹצְאִים כָּל הָאוֹרוֹת."],[9,"","מַה כָּתוּב? וַיְהִי כִּשְׁמֹעַ אֵלִיָּהוּ וַיָּלֶט פָּנָיו בְּאַדַּרְתּוֹ וְגוֹ' וְהִנֵּה אֵלָיו קוֹל וַיֹּאמֶר מַה לְּךְ פֹה אֵלִיָּהוּ. וַיֹּאמֶר קַנֹּא קִנֵּאתִי. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, עַד מָתַי אַתָּה מְקַנֵּא לִי? סָגַרְתָּ אֶת הַדֶּלֶת שֶׁלֹּא יָכוֹל לִשְׁלֹט בְּךְ הַמָּוֶת לְעוֹלָם, וְהָעוֹלָם לֹא יָכוֹל לִסְבֹּל אוֹתְךְ עִם בָּנַי (אדם). אָמַר לוֹ, כִּי עָזְבוּ בְרִיתְךְ בְּנֵי יִשְׂרָאֵל וְגוֹ'. אָמַר לוֹ, חַיֶּיךְ שֶׁבְּכָל מָקוֹם שֶׁבָּנַי (אדם) יְקַיְּמוּ אֶת בְּרִית הַקֹּדֶשׁ, אַתָּה תִהְיֶה מְזֻמָּן לְשָׁם. (והרי נתבאר שמשום כך מתקנים כסא לאליהו, שהוא מזמן לשם,)"]]],[["תָּא חֲזֵי, מַה גָּרַם הַהִיא מִלָּה דְאֵלִיָּהוּ, דִּכְתִיב, (מלכים א י״ט:י״ח) וְהִשְׁאַרְתִּי בְּיִשְׂרָאֵל שִׁבְעַת אֲלָפִים כָּל הַבִּרְכַּיִם אֲשֶׁר לא כָּרְעוּ לַבַּעַל וְכָל הַפֶּה אֲשֶׁר לֹא נָשַׁק לוֹ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מִכָּאן וּלְהָלְאָה, דְּלָא יָכִיל עַלְמָא לְמִסְבְּלָךְ עִם בָּנַי (נשא). וְאֶת אֱלִישָׁע בֶּן שָׁפָט מֵאָבֵל מְחוֹלָה תִּמְשַׁח לְנָבִיא תַּחְתֶּיךָ. יְהֵא נְבִיאָה אָחֳרָא לְגַבֵּי בָּנַי (נשא), וְאַתְּ תִּסְתַּלַּק לְאַתְרָךְ.","וְתָּא חֲזֵי, כָּל הַהוּא בַּר נָשׁ דִּמְקַנִּי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, לָא יָכִיל מַלְאֲכָא דְמוֹתָא לְשַׁלְּטָאָה בֵּיהּ, כִּשְׁאָר בְּנֵי נָשָׁא. וְיִתְקַיֵּים בֵּיהּ שְׁלָם, וְהָא אוּקְמוּהָ. כְּמָה דְאִתְּמָר בְּפִנְחָס, (במדבר כ״ה:י״ב) לָכֵן אֱמוֹר הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם:","וַיִּפּוֹל עַל צַוְּארֵי בִּנְיָמִן אָחִיו וַיֵּבְךִ וּבִנְיָמִן בָּכָה עַל צַוָּארָיו. רִבִּי יִצְחָק אָמַר, הָא אוּקְמוּהָ, דְּבָכָה עַל מִקְדָּשׁ רִאשׁוֹן וְעַל מִקְדָּשׁ שֵׁנִי.","פָּתַח וְאָמַר, (שיר השירים ד׳:ד׳) כְּמִגְדַּל דָּוִד צַוָּארֵךְ בָּנוּי לְתַלְפִּיּוֹת אֶלֶף הַמָּגֵן תָּלוּי עָלָיו כֹּל שִׁלְטֵי הַגִּבּוֹרִים. כְּמִגְדַּל דָּוִד, מַאן מִגְדַּל דָּוִד. דָּא מִגְדַּל דָּוִד וַדַּאי, דְּבָנָה לֵיהּ דָּוִד, וְסָלִיק לֵיהּ גּוֹ יְרוּשָׁלַיִם. אֶלָּא כְּמִגְדַּל דָּוִד, דָּא יְרוּשָׁלֵם דִּלְעֵילָא, דִּכְתִיב בֵּיהּ, (משלי י״ח:י׳) מִגְדַּל עֹז שֵׁם ה' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. מַאן נִשְׂגָּב, אֶלָּא הַהוּא מִגְדַּל נִשְׂגָּב, בְּגִין דְּבֵיהּ יָרוּץ צַדִּיק.","צַוָּארֵךָ, דָּא בֵּית מַקְדְּשָׁא דִלְתַתָּא, דְּאִיהוּ קָאִים בְּתִקּוּנָא דְּשַׁפִּירוּ, כְּקַדְלָא לְגוּפָא. מַה צַּוָּאר, אִיהוּ שַׁפִּירוּ דְּכָל גּוּפָא, הָכִי נָמֵי בֵּי מַקְדְּשָׁא, אִיהוּ שַׁפִּירוּ דְּכָל עַלְמָא.","בָּנוּי לְתַלְפִּיּוֹת, תִּלָּא דְּכָל בְּנֵי עַלְמָא הֲווּ מִסְתַּכְּלָן בֵּיהּ, וְהָכִי אוּקְמוּהָ, תַּלְפִּיּוֹת, תֵּל דְּכָל פִּיּוֹת דְּעַלְמָא מְשַׁבְּחָן וּמְצַלָּאן לְגַבֵּיהּ.","אֶלֶף הַמָּגֵן תָּלוּי עָלָיו, אִלֵּין אֶלֶף תִּקּוּנִין, דִּמְתַקְּנִין בֵּיהּ כְּדְקָא יְאוּת. כֹּל שִׁלְטֵי הַגִּבּוֹרִים, דְּכֻלְּהוּ קָא אַתְיָין מִסִּטְרָא דְּדִינָא קַשְׁיָא.","מַה צַּוָּאר, כָּל תִּקּוּנִין דְּאִתְּתָא בֵּיהּ תַּלְיָין. כָּךְ בְּמַקְדְּשָׁא, כָּל תִּקּוּנִין דְּעַלְמָא בֵּיהּ תַּלְיָין וְשָׁרְיָין. וְהָא אוּקְמוּהָ, דִּכְתִיב, (איכה ה׳:ה׳) עַל צַוָּארֵינוּ נִרְדָּפְנוּ, עַל בֵּי מַקְדְּשָׁא, דְּאִיהוּ צַוָּאר וְשַׁפִּירוּ דְּכָל עַלְמָא. נִרְדָּפְנוּ, יָגַעְנוּ לְמִבְנֵי לֵיהּ תְּרֵין זִמְנִין, וְלֹא הוּנַח לָנוּ. דְּהָא לָא שָׁבְקוּהָ לָן, וְאִתְחָרַב וְלָא אִתְבְּנֵי לְבָתַר.","מַה צַּוָּאר, כֵּיוָן דְּאִשְׁתֵּצֵי, כָּל גּוּפָא אִשְׁתֵּצֵי עִמֵּיהּ. הָכִי נָמֵי בֵּי מַקְדְּשָׁא, כֵּיוָן דְּאִיהוּ אִשְׁתֵּצֵי וְאִתְחַשַּׁךְ, כָּל עַלְמָא הָכִי נָמֵי אִתְחַשַּׁךְ, וְלָא נָהִיר שִׁמְשָׁא, וְלָא שְׁמַיָא וְאַרְעָא וְכֹכְבַיָא.","בְּגִין כָּךְ בָּכָה יוֹסֵף עַל דָּא. וּלְבָתַר דְּבָכָה עַל דָּא, בָּכָה עַל שִׁבְטִין דְּאִתְגָּלוּ. כַּד אִתְחָרִיב בֵּי מַקְדְּשָׁא, כֻּלְּהוּ שִׁבְטִין אִתְגָּלוּ מִיָּד, וְאִתְבַּדְּרוּ בֵּינֵי עַמְמַיָא. הֲדָא הוּא דִכְתִיב וַיְנַשֵּׁק לְכָל אֶחָיו וַיֵּבְךִ עֲלֵיהֶם, עֲלֵיהֶם וַדַּאי.","עַל כֻּלָּם בָּכָה, עַל בֵּי מַקְדְּשָׁא דְּאִתְחָרִיב תְּרֵין זִמְנִין, וְעַל אֲחוֹי עֲשֶׂרֶת הַשְּׁבָטִים, דְּאִתְגָּלוּ בְּגָלוּתָא וְאִתְבַּדְּרוּן בֵּינֵי עַמְמַיָא. וְאַחֲרֵי כֵן דִּבְּרוּ אֶחָיו אִתּוֹ, וְלָא כְּתִיב וַיִּבְכּוּ, דְּהָא אִיהוּ בָּכָה, דְּנִצְנְצָה בֵּיהּ רוּחָא קַדִּישָׁא, וְאִינוּן לָא בָּכוּ, דְּלָא שָׁרָא עֲלַיְיהוּ רוּחַ קוּדְשָׁא:","וְהַקֹּל נִשְׁמַע בֵּית פַּרְעֹה. רִבִּי (אלעזר) אַבָּא פָּתַח וְאָמַר, (תהילים פ״ד:ג׳) נִכְסְפָה וְגַם כָּלְתָה נַפְשִׁי לְחַצְרוֹת ה' לִבִּי וּבְשָׂרִי יְרַנְּנוּ אֶל אֵל חָי. תָּא חֲזֵי, כָּל בַּר נָּשׁ דְּצַלֵּי צְלוֹתֵיהּ (וקם) קַמֵּי מָארֵיהּ, אִצְטְרִיךְ לֵיהּ לְאַקְדָּמָא לֵיהּ בִּרְכָאן בְּכָל יוֹמָא וְיוֹמָא, וּלְצַלֵּי צְלוֹתֵיהּ קַמֵּי מָארֵיהּ בְּזִמְנָא דְאִצְטְרִיךְ.","בְּצַפְרָא, לְאַחֲדָא בִּימִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא. בְּמִנְחָה, לְאַחֲדָא בִּשְׂמָאלָא. וּצְלוֹתָא וּבָעוּתָא, אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ בְּכָל יוֹמָא וְיוֹמָא בְּגִין לְאִתְאַחֲדָא בֵּיהּ. וְאוֹקִימְנָא, מַאן דְּצַלֵּי צְלוֹתֵיהּ, (וקם) קַמֵּי מָארֵיהּ, אִצְטְרִיךְ לֵיהּ דְּלָא לְמִשְׁמַע קָלֵיהּ בִּצְלוֹתֵיהּ. וּמַאן דְּאַשְׁמַע קָלֵיהּ בִּצְלוֹתֵיהּ, צְלוֹתֵיהּ לָא אִשְׁתְּמַע."],[[0,"ת\"ח מה גרם וכו':","בוא וראה, מה גרם דבר ההוא של אליהו, שכתוב, והשארתי בישראל וגו'. אמר לו הקב\"ה, מכאן ולהלאה, שלא יכול העולם לסובלך עם בני, כי תקטרג עליהם, \u0003ואת אלישע\u0004 וגו', יהיה נביא אחר לבני, ואתה תסתלק למקומך."],[1,"ות\"ח כל ההוא וכו':","ובוא וראה, כל אדם המקנא להקב\"ה אין מלאך המות יכול לשלוט עליו כמו על שאר בני אדם, ויהיה לו שלום, כמו שנאמר בפנחס, הנני נותן לו את בריתי שלום."],[2,"ויפול על צוארי וגו':","רבי יצחק אמר, הרי בארו, שבכה על מקדש ראשון ועל מקדש שני, שיבנו בחלקו של בנימין, ויחרבו."],[3,"פתח ואמר כמגדל דוד צוארך וגו':","שואל, מאן מגדל דוד. מגדל דוד זה הנמצא בירושלים, ודאי שבנה אותו דוד והעלה לו, כלומר, שהוא עומד, בתוך ירושלים. אלא כמגדל דוד שאומר הכתוב, אינו מגדל דוד הזה, אלא זה הוא ירושלים של מעלה. דהיינו הנוקבא, שכתוב בו מגדל עוז שם ה' בו ירוץ צדיק \u0003ונשגב,\u0004 שואל, מי הוא \u0003נשגב,\u0004 אם סובב על הצדיק אם על המגדל. ומשיב, אלא המגדל נשגב, משום שבו ירוץ צדיק, שהוא יסוד. (עי' לעיל בראשית א' אות תע\"א)."],[4,"צוארך, דא בי מקדשא לתתא וכו':","צוארך, היינו בית המקדש של מטה, הדומה למגדל דוד שהוא הנוקבא, ונקרא כך, משום שהוא נמצא בתקון היופי, כמו הצואר, שהוא היופי של הגוף, מה צואר הוא היופי של כל הגוף, כן בית המקדש הוא היופי של כל העולם."],[5,"בנוי לתלפיות:","פירושו, תל שכל בני העולם מסתכלים בו, לשבח ולהתפלל, וכך בארוהו, תלפיות, הוא אותיות תל-פיות, תל שכל פיות העולם משבחים ומתפללים אליו."],[6,"אלף המגן תלוי עליו:","אלו הם אלף תקונים המתוקנים בו כראוי. דהיינו הארת החכמה המרומזת במספר אלף. \u0003כל שלטי הגבורים,\u0004 שכולם באים מצד הדין הקשה, ע\"כ נקראים גבורים. פירוש. הארת חכמה זו, נמשכת מבינה שחזרה להיות חכמה, ומקו שמאל שלה, שנקרא יצחק, שהוא דינא קשיא. כמ\"ש לעיל, (וישב דף ו' ד\"ה ת\"ח וישב יעקב)."],[7,"מה צואר כל תקונין וכו':","מה צואר, כל תקוני האשה תלוים בו, כך בית המקדש כל תקוני העולם תלוים ושורים בו. ובארוה, שכתוב, על צוארינו נרדפנו, פירושו, על בית המקדש, שהוא צואר, והיופי של כל העולם, \u0003נרדפנו.\u0004 יגענו ולא הונח לנו, פירושו, \u0003יגענו\u0004 לבנות אותו שתי פעמים. דהיינו בית מקדש ראשון והשני, \u0003ולא הונח לנו\u0004, כי לא הניחו אותנו, ונחרבו, ולא נבנו אחר כך."],[8,"מה צואר כיון וכו':","מה צואר כיון שנשחת, נשחת עמו כל הגוף, כך בית המקדש, כיון שהוא נשחת ונחשך, נחשך גם כן כל העולם, והשמש אינו מאיר, ולא שמים וארץ והככבים."],[9,"בגין כך בכה וכו':","משום כך בכה יוסף על זה, דהיינו על ב' מקדשים שנחרבו, ואחר שבכה על זה, בכה על השבטים שנגלו. כשנחרב בית המקדש, נגלו מיד כל השבטים, ונתפזרו בין העמים. וזהו שכתוב וינשק לכל אחיו ויבך עליהם, \u0003עליהם\u0004 ודאי, דהיינו על שנגלו."],[10,"על כלם וכו':","על כלם בכה, על בית המקדש שנחרב ב' פעמים, ועל אחיו, שהם עשרת השבטים שיצאו בגלות, ונתפזרו בין העמים. \u0003ואחרי כן דברו אחיו אתו.\u0004 ולא כתוב בהם \u0003ויבכו,\u0004 כי הוא בכה משום שהופיעה עליו רוח הקודש, וראה את כל זה, והם לא בכו, כי לא שרה עליהם רוח הקדש, ולא ראו את זה."],[11,"והקל נשמע בית פרעה:","רבי אבא פתח ואמר, נכספה וגם כלתה נפשי וגו'. בוא וראה, כל אדם המתפלל תפלתו לפני אדונו, צריך להקדים לו ברכות בכל יום ויום, ולהתפלל תפלתו בזמן שצריך."],[12,"בצפרא, לאחדא וכו':","בבוקר יתאחד בימינו של הקב\"ה, שהוא חסד. במנחה יתאחד בשמאלו של הקב\"ה, ונצרך לאדם תפלה ובקשה בכל יום ויום, כדי שיתאחד בו, בהקב\"ה, ובארוהו."],[12,"מאן דצלי צלותיה וכו':","מי שמתפלל תפלתו לפני אדונו, צריך שלא ישמיע קולו בתפלתו, ומי שמשמיע קולו בתפלתו, תפלתו אינה מתקבלת."]],[[0,"","בֹּא רְאֵה מַה גָּרַם אוֹתוֹ הַדִּבּוּר שֶׁל אֵלִיָּהוּ, שֶׁכָּתוּב וְהִשְׁאַרְתִּי בְיִשְׂרָאֵל שִׁבְעַת אֲלָפִים כָּל הַבִּרְכַּיִם אֲשֶׁר לֹא כָרְעוּ לַבַּעַל וְכָל הַפֶּה אֲשֶׁר לֹא נָשַׁק לוֹ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מִכָּאן וָהָלְאָה, שֶׁאֵין הָעוֹלָם לִסְבֹּל אוֹתְךְ עִם בָּנַי (אדם). וְאֶת אֱלִישָׁע בֶּן שָׁפָט מֵאָבֵל מְחוֹלָה תִּמְשַׁח לְנָבִיא תַּחְתֶּיךְ, יִהְיֶה נָבִיא אַחֵר אֵצֶל בָּנַי (אדם), וְאַתָּה תִּסְתַּלֵּק לִמְקוֹמְךְ."],[1,"","וּבֹא רְאֵה, כָּל אוֹתוֹ אָדָם שֶׁמְּקַנֵּא לַקָּדוֹשׁ-בָּרוּךְ-הוּא, לֹא יָכוֹל מַלְאַךְ הַמָּוֶת לִשְׁלֹט בּוֹ כִּשְׁאָר בְּנֵי אָדָם, וְיִתְקַיֵּם בּוֹ שָׁלוֹם, וְהִנֵּה פֵּרְשׁוּהָ כְּמוֹ שֶׁנֶּאֱמַר בְּפִנְחָס, (במדבר כה) לָכֵן אֱמֹר הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם."],[2,"","וַיִּפֹּל עַל צַוְּארֵי בִנְיָמִן אָחִיו וַיֵּבְךָּ וּבִנְיָמִן בָּכָה עַל צַוָּארָיו. רַבִּי יִצְחָק אָמַר, הִנֵּה פֵּרְשׁוּהָ שֶׁבָּכָה עַל מִקְדָּשׁ רִאשׁוֹן וְעַל מִקְדָּשׁ שֵׁנִי."],[3,"","פָּתַח וְאָמַר, כְּמִגְדַּל דָּוִיד צַוָּארֵךְ בָּנוּי לְתַלְפִּיּוֹת אֶלֶף הַמָּגֵן תָּלוּי עָלָיו כֹּל שִׁלְטֵי הַגִּבּרִים. כְּמִגְדַּל דָּוִיד, מִי מִגְדַּל דָּוִיד? זֶה וַדַּאי מִגְדַּל דָּוִד שֶׁבָּנָה אוֹתוֹ דָּוִד וְהֶעֱלָה אוֹתוֹ לְתוֹךְ יְרוּשָׁלַיִם. אֶלָּא כְּמִגְדַּל דָּוִיד - זוֹ יְרוּשָׁלַיִם שֶׁל מַעְלָה, שֶׁכָּתוּב בָּהּ (משלי יא) מִגְדַּל עֹז שֵׁם ה' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. מִי הַנִּשְׂגָּב? אֶלָּא אוֹתוֹ מִגְדָּל נִשְׂגָּב, מִשּׁוּם שֶׁבּוֹ יָרוּץ צַדִּיק."],[4,"","צַוָּארֵךָ - זֶה בֵּית הַמִּקְדָּשׁ שֶׁלְּמַטָּה, שֶׁעוֹמֵד בְּתִקּוּן שֶׁל יֹפִי כְּצַוָּאר לַגּוּף. מָה הַצַּוָּאר הוּא הַיֹּפִי שֶׁל כָּל הַגּוּף - כָּךְ גַּם בֵּית הַמִּקְדָּשׁ הוּא הַיֹּפִי שֶׁל כָּל הָעוֹלָם."],[5,"","בָּנוּי לְתַלְפִּיּוֹת - תֵּל שֶׁכָּל בְּנֵי הָעוֹלָם הָיוּ מִסְתַּכְּלִים בּוֹ. וְכָךְ בֵּאֲרוּהוּ, תַּלְפִּיּוֹת - תֵּל שֶׁכָּל הַפִּיּוֹת שֶׁל הָעוֹלָם מְשַׁבְּחִים וּמִתְפַּלְלִים אֵלָיו."],[6,"","אֶלֶף הַמָּגֵן תָּלוּי עָלָיו - אֵלּוּ אֶלֶף הַתִּקּוּנִים שֶׁמְּתַקְנִים בּוֹ כָּרָאוּי. כֹּל שִׁלְטֵי הַגִּבֹּרִים - שֶׁכֻּלָּם בָּאִים מִצַּד הַדִּין הַקָּשֶׁה."],[7,"","מָה הַצַּוָּאר כָּל תִּקּוּנֵי הָאִשָּׁה תְּלוּיִים בּוֹ - כָּךְ בַּמִּקְדָּשׁ כָּל תִּקּוּנֵי הָעוֹלָם תְּלוּיִים וּשְׁרוּיִים בּוֹ. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (איכה ה) עַל צַוָּארֵנוּ נִרְדָּפְנוּ, עַל בֵּית הַמִּקְדָּשׁ, שֶׁהוּא הַצַּוָּאר וְהַיֹּפִי שֶׁל כָּל הָעוֹלָם. נִרְדָּפְנוּ יָגַעְנוּ, לִבְנוֹת אוֹתוֹ פַּעֲמַיִם. וְלֹא הוּנַּח לָנוּ, שֶׁהֲרֵי לֹא הִשְׁאִירוּהוּ לָנוּ, וְנֶחֱרַב וְלֹא נִבְנָה לְאַחַר מִכֵּן."],[8,"","מָה הַצַּוָּאר, כֵּיוָן שֶׁהֻשְׁמַד, כָּל הַגּוּף מֻשְׁמָד עִמּוֹ - כָּךְ גַּם בֵּית הַמִּקְדָּשׁ, כֵּיוָן שֶׁהֻשְׁמַד וְנֶחְשַׁךְ, כָּל הָעוֹלָם כָּךְ גַּם נֶחְשַׁךְ, וְלֹא מֵאִיר הַשֶּׁמֶשׁ, וְלֹא שָׁמַיִם וְאֶרֶץ וְכוֹכָבִים."],[9,"","מִשּׁוּם כָּךְ בָּכָה עַל זֶה יוֹסֵף, וְאַחַר שֶׁבָּכָה עַל זֶה, בָּכָה עַל הַשְּׁבָטִים שֶׁיֵּגֶלוּ. כְּשֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, כָּל הַשְּׁבָטִים גָּלוּ מִיָּד וְהִתְפַּזְּרוּ בֵּין הָעַמִּים. זֶהוּ שֶׁכָּתוּב וַיְנַשֵּׁק לְכָל אֶחָיו וַיֵּבְךָּ עֲלֵהֶם. עֲלֵהֶם וַדַּאי."],[10,"","עַל כֻּלָּם בָּכָה, עַל בֵּית הַמִּקְדָּשׁ שֶׁנֶּחֱרַב פַּעֲמַיִם, וְעַל אֶחָיו עֲשֶׂרֶת הַשְּׁבָטִים שֶׁהֻגְלוּ לַגָּלוּת וְהִתְפַּזְּרוּ בֵּין הָעַמִּים. וְאַחֲרֵי כֵן דִּבְּרוּ אֶחָיו אִתּוֹ, וְלֹא כָתוּב וַיִּבְכּוּ, שֶׁהֲרֵי הוּא בָּכָה, שֶׁנִּצְנְצָה בּוֹ רוּחַ הַקֹּדֶשׁ, וְהֵם לֹא בָכוּ, שֶׁלֹּא שָׁרְתָה עֲלֵיהֶם רוּחַ הַקֹּדֶשׁ."],[11,"","וְהַקֹּל נִשְׁמַע בֵּית פַּרְעֹה. רַבִּי (אלעזר) אַבָּא פָּתַח וְאָמַר, (תהלים פד) נִכְסְפָה וְגַם כָּלְתָה נַפְשִׁי לְחַצְרוֹת ה' לִבִּי וּבְשָׂרִי יְרַנְּנוּ אֶל אֵל חָי. בּא רְאֵה, כָּל אָדָם שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ (וקם) לִפְנֵי רִבּוֹנוֹ, צָרִיךְ לוֹ לְהַקְדִּים לוֹ בְּרָכוֹת בְּכָל יוֹם וָיוֹם וּלְהִתְפַּלֵּל תְּפִלָּתוֹ לִפְנֵי רִבּוֹנוֹ בַּזְּמַן שֶׁצָּרִיךְ."],[12,"","בַּבֹּקֶר לֶאֱחֹז בַּיָּמִין שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּמִנְחָה לֶאֱחֹז בַּשְּׂמֹאל. וּתְפִלָּה וּבַקָּשָׁה צָרִיךְ לָאָדָם בְּכָל יוֹם וָיוֹם כְּדֵי לְהֵאָחֵז בּוֹ. וּבֵאַרְנוּ, מִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ (ועומד) לִפְנֵי רִבּוֹנוֹ, צָרִיךְ לוֹ שֶׁלֹּא לִשְׁמֹעַ קוֹלוֹ בִּתְפִלָּתוֹ, וּמִי שֶׁשּׁוֹמֵעַ קוֹלוֹ בִּתְפִלָּתוֹ, תְּפִלָּתוֹ לֹא נִשְׁמַעַת."]]],[["מַאי טַעְמָא. בְּגִין (שמות ר\"ב ע\"ב) דִּצְלוֹתָא, לָאו אִיהִי הַהִיא קָלָא דְּאִשְׁתְמַע. דְּהַהוּא קוֹל דְּאִשְׁתַּמַּע לָאו הִיא צְלוֹתָא. וּמַאן אִיהִי צְלוֹתָא. דָּא קָלָא אָחֳרָא, דְּתַלְיָא בְּקָלָא דְאִשְׁתְּמַע, וּמַאן הוּא קָלָא דְּאִשְׁתְּמַע. דָּא הַהוּא קוֹל דְּהוּא בְּוא\"ו, קָלָא דְתַלְיָא בֵּיהּ, דָּא הַהוּא קֹל בְּלָא וא\"ו.","וּבְגִין כָּךְ, לָא אִצְטְרִיךְ לֵיהּ לְבַר נָשׁ לְמִשְׁמַע קָלֵיהּ בִּצְלוֹתֵיהּ, אֶלָּא לְצַלָּאָה בְּלַחַשׁ, בְּהַהוּא קָלָא דְּלָא אִשְׁתְּמַע. וְדָא הִיא צְלוֹתָא דְּאִתְקַבָּלַת תָּדִיר. וְסִימָנִיךְ, וְהַקֹּל נִשְׁמַע, קֹל בְּלָא וא\"ו, נִשְׁמַע. דָּא הִיא צְלוֹתָא דְּהִיא בַּחֲשַׁאי. דִּכְתִיב בְּחַנָּה, (שמואל א א׳:י״ג) וְקוֹלָהּ לא יִשָּׁמַע. דָּא הִיא צְלוֹתָא דְּקוּדְשָׁא בְּרִיךְ הוּא קַבִּיל, כַּד אִתְעֲבִיד גּוֹ רְעוּתָא וְכַוָּונָה וְתִקּוּנָא כְּדְקָא יְאוּת, וּלְיַחֲדָא יִחוּדָא דְמָרֵיהּ כְּדְקָא יָאוֹת בְּכָל יוֹמָא. (והקל נשמע בית פרעה. והקל נשמע חסר וא\"ו, מאי טעמא, אמר רבי אלעזר, דא היא שכינתא דבכאת על חרוב בי מקדשא ועל גלותהון דישראל. כתיב הכא, והקל נשמע, וכתיב התם, (ירמיהו ל״א:ט״ו) קול ברמה נשמע. מה להלן שכינתא, אף כאן נמי שכינתא).","רִבִּי אֶלְעָזָר אָמַר, קָלָא בַּחֲשַׁאי, דָּא הִיא קָלָא עִלָּאָה, דְּכָל קָלִין נָפְקִין מִתַּמָּן. אֲבָל קֹל בְּלָא ו', דָּא הִיא צְלוֹתָא דִלְתַתָּא, דְּאִיהִי אָזְלָא לְאִסְתַּלְּקָא בְּוא\"ו וּלְאִתְחַבְּרָא בֵּיהּ.","תָּא חֲזֵי, וְהַקֹּל נִשְׁמַע, דָּא הוּא קֹל בְּלָא וא\"ו. דָּא הִיא קָלָא דְּבָּכַאת עַל מִקְדָּשׁ רִאשׁוֹן וְעַל מִקְדָּשׁ שֵׁנִי. נִשְׁמַע, כְּמָה דְאַתְּ אָמֵר, קוֹל בְּרָמָה נִשְׁמָע. בְּרָמָה, מַאי בְּרָמָה. דָּא הוּא עַלְמָא עִלָּאָה, עַלְמָא דְאָתֵי. וְסִימָנִיךְ, מִן הָרָמָה וְעַד בֵּית אֵל, (תהילים ק״ו:מ״ח) מִן הָעוֹלָם וְעַד הָעוֹלָם. הָכָא בְּרָמָה, דָּא עַלְמָא עִלָּאָה. דְּהָא בְּהַהִיא שַׁעְתָּא דִּי בְּרָמָה נִשְׁמַע. כְּדֵין מַה כְּתִיב, (ישעיהו כ״ב:י״ב) וַיִּקְרָא ה' אֱלהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וְגו'.","וְהַקֹּל נִשְׁמַע, לְעֵילָא לְעֵילָא. מַאי טַעְמָא. בְּגִין דְּוא\"ו אִתְרַחַק וְאִסְתַּלַּק מִנֵּיהּ, וּכְדֵין רָחֵל מְבַכָּה עַל בָּנֶיהָ מֵאֲנָה לְהִנָּחֵם עַל בָּנֶיהָ כִּי אֵינֶנוּ. כִּי אֵינֶנּוּ, כִּי אֵינָם מִבָּעֵי לֵיהּ. אֶלָּא כִּי אֵינֶנּוּ, וְהָא אוֹקִימְנָא, כִּי אֵינֶנּוּ, דְּבַעֲלָהּ לָא אִשְׁתַּכַּח עִמָּהּ. דְּאִלְּמָלֵא בַּעֲלָהּ יִשְׁתַּכַּח עִמָּהּ, תִּתְנַחֵם עֲלַיְיהוּ. דְּהָא כְּדֵין בְּנָהָא, לָא יְהוֹן בְּגָלוּתָא. וּבְגִין דְּאֵינֶנּוּ, לָאו אִיהִי מִתְנַחֲמָא עַל בְּנָהָא, בְּגִין דִּבְנָהָא אִתְרַחֲקוּ מִנָּהּ, עַל דְּאֵינֶנּוּ עִמָּהּ.","תָּא חֲזֵי, בֵּית פַּרְעֹה, דָּא הוּא סִימָנִיךְ לְעֵילָא, בֵּיתָא דְּאִתְפְּרָעוּ וְאִתְגַּלְּיָין מִנֵּיהּ כָּל נְהוֹרִין וְכָל בּוּצִינִין, כָּל מַה דְּהֲוָה סָתִים, מִתַּמָּן אִתְגְּלִי. וּבְגִין כָּךְ, קוּדְשָׁא בְּרִיךְ הוּא אַפִּיק כָּל נְהוֹרִין וְכָל בּוּצִינִין, בְּגִין לְאַנְהָרָא לְהַהוּא קוֹל, דְּאִקְרֵי קֹל בְּלָא וא\"ו.","תָּא חֲזֵי, כַּד יָקִים קוּדְשָׁא בְּרִיךְ הוּא לְהַאי קֹל מֵעַפְרָא, וְיִתְחַבַּר בְּוא\"ו, כְּדֵין כָּל מַה דְּאִתְאֲבִיד מִנַּיְיהוּ בְּזִמְנָא דְגָלוּתָא, יִתְהֲדַר וְיִתְעַדְּנוּן בִּנְהוֹרִין עִלָּאִין דְּאִתּוֹסְפָן מִגּוֹ עַלְמָא עִלָּאָה. כְּמָא דְאַתְּ אָמֵר, (ישעיהו כ״ז:י״ג) וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וּבָאוּ הָאוֹבְדִים בְּאֶרֶץ אַשּׁוּר וְהַנִּדָּחִים בְּאֶרֶץ מִצְרַיִם וְהִשְׁתַּחֲווּ לַה' בְּהַר הַקֹּדֶשׁ בִּירוּשָׁלָם:","וְאַתָּה צֻוֵּיתָה זֹאת עֲשׂוּ קְחוּ לָכֶם מֵאֶרֶץ מִצְרַיִם וְגו'. רִבִּי חִיָּיא פָּתַח, (ישעיהו ס״ו:י׳) שִׂמְחוּ אֶת יְרוּשָׁלַם וְגִילוּ בָהּ כָּל אוֹהֲבֶיהָ שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ וְגו'. תָּא חֲזֵי, כַּד אִתְחָרַב בֵּי מַקְדְּשָׁא וְגָרְמוּ חוֹבִין, וְאִתְגָּלוּ יִשְׂרָאֵל מֵאַרְעָא, (ויקרא ע\"ה ע\"א) אִסְתַּלַּק קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָא לְעֵילָא, וְלָא אַשְׁגַּח עַל חָרוּב בֵּי מַקְדְּשָׁא, וְעַל עַמֵּיהּ דְּאִתְגָּלוּ, וּכְדֵין שְׁכִינְתָּא אִתְגַּלְּיָיא עִמְּהוֹן.","כַּד נָחַת, אַשְׁגַּח עַל בֵּיתֵיהּ דְּאִתּוֹקַד, אִסְתַּכַּל עַל עַמֵּיהּ וְהָא אִתְגְּלִי. שָׁאַל עַל מַטְרוֹנִיתָא וְאִתְתָּרְכַת. כְּדֵין וַיִּקְרָא ה' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וּלְקָרֵחָה וְלַחֲגֹר שָׂק. וְהִיא גַּם הִיא מַה כְּתִיב בָּהּ, (יואל א׳:ח׳) אֱלִי כִּבְתוּלָה חֲגֻרַת שַׂק עַל בַּעַל נְעוּרֶיהָ. כְּמָא דְאַתְּ אָמֵר כִּי אֵינֶנּוּ, בְּגִין דְּאִסְתַּלַּק מִינָהּ, וְאִשְׁתַּכַּח פִּירוּדָא.","וְאֲפִילּוּ שְׁמַיָא וְאַרְעָא, כֻּלְּהוּ אִתְאַבָּלוּ, דִּכְתִיב, (ישעיהו נ׳:ג׳) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. מַלְאֲכֵי עִלָּאֵי כֻּלְּהוּ אִתְאַבָּלוּ עֲלֵיהּ, דִּכְתִיב, (ישעיהו ל״ג:ז׳) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָּה מַלְאַכֵי שָׁלוֹם מַר יִבְכָּיוּן. שִׁמְשָׁא וְסִיהֲרָא אִתְאַבָּלוּ וְחָשְׁכוּ נְהוֹרֵיהוֹן. דִּכְתִיב, (ישעיהו י״ג:י׳) חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ וְגו', וְכֹלָּא עִלָּאֵי וְתַתָּאֵי, בָּכוּ עֲלָהּ וְאִתְאַבָּלוּ. מַאי טַעְמָא, בְּגִין דְּשָׁלְטָא עֲלָהּ סִטְרָא אָחֳרָא, דְּשָׁלְטָא עַל אַרְעָא קַדִּישָׁא."],[[0,"מ\"ט בגין וכו':","מה הטעם. הוא, משום שהתפלה אינה אותו קול הנשמע, כי קול הנשמע אינו תפלה, ומה היא תפלה, היא קול אחר התלוי בקול הנשמע. ומה הוא קול הנשמע, זה הוא אותו הקול שהוא עם \u0003ו'.\u0004 וקול התלוי בו בקול הנשמע, הוא \u0003קל\u0004 בלא \u0003ו'.\u0004"],[0,"","פירוש. \u0003קול שאינו נשמע,\u0004 ה\"ס חסדים מכוסים מהארת חכמה, וה\"ס קול בינה. \u0003וקול הנשמע,\u0004 ה\"ס חסדים מגולים בהארת חכמה, וה\"ס ז\"א, שמחזה ולמטה מתגלה בו החכמה. (כמ\"ש לעיל בראשית ב' דף קמ\"ו אות רל\"ז רל\"ח ובהסולם שם) אמנם יש עוד בחינת \u0003קול שאינו נשמע,\u0004 שהיא הנוקבא, בעת שהיא חכמה בלי חסדים, שאין החכמה יכולה להאיר בלי לבוש החסדים, וע\"כ היא קול שאינו נשמע. ונקראת \u0003תפלה בלחש,\u0004 (כנ\"ל חיי שרה דף ע\"א ד\"ה פירוש, ע\"ש.) וכן הוא נקראת \u0003קל\u0004 חסר \u0003ו',\u0004 שה \u0003ו'\u0004 היא ז\"א המשפיע לה חסדים, שאז היא נשמעת. וכשחסרה \u0003ו'\u0004 שהוא ז\"א, היא נמצאת בלי חסדים ואינה נשמעת. דהיינו שאינה משפעת לחוץ ממנה."],[0,"","וז\"ש \u0003דצלותא לאו איהי ההיא קלא דאשתמע,\u0004 כי ה\"ס חכמה בלי חסדים שאינה נשמע, \u0003ומאן איהי צלותא, דא קלא אחרא דתליא בקלא דאשתמע,\u0004 שצריכה לקבל חסדים מז\"א שהוא קול דאשתמע, ואז החכמה שבה מתלבשת בחסדים והיא נשמעת. \u0003קלא דאשתמע דא ההיא קול דהוא\u0004 ב \u0003ו',\u0004 שהוא ז\"א. \u0003קלא דתליא ביה,\u0004 שתלוי בזווג שלו, \u0003דא ההוא קל בלא ו',\u0004 שהיא הנוקבא שמחוסרת חסדים. כמבואר."],[1,"ובגין כך לא וכו':","ומשום זה אין אדם צריך להשמיע קולו בתפלתו, אלא להתפלל בלחש, בקול שאינו נשמע, כבחינת הנוקבא, שה\"ס תפלה, ועל ידי תפלתינו מיחדים הקול שאינו נשמע, עם ז\"א שהוא קול הנשמע. וזו היא תפלה המתקבלת תדיר, להיותה משתוקקת אז ביותר להזדווג עם ז\"א, וסימנך, \u0003והקל נשמע,\u0004 קל בלא \u0003ו',\u0004 נשמע, כלומר שמתקבלת, זו היא תפלה שהוא בלחש, שכתוב בחנה וקולה לא ישמע. זו היא תפלה שהקב\"ה מקבל, כשנעשית ברצון וכונה ובתקון כראוי, וכשמיחד יחוד רבונו בכל יום כראוי להיות."],[2,"רבי אלעזר וכו':","ר\"א אמר, קול בחשאי, זה הוא קול העליון דהיינו קול שבבינה, שכל הקולות יוצאים משם, שהיא בחינה א' דקלא דלא אשתמע כנ\"ל. אבל \u0003קל\u0004 בלא \u0003ו'\u0004 זו היא תפלה שלמטה, דהיינו הנוקבא, שהיא בחינה ב' דקלא דלא אשתמע כנ\"ל, שהיא הולכת להתעלות אל ה \u0003ו'\u0004 שהוא ז\"א, ולהתחבר עמו, כדי לקבל ממנו חסדים כמ\"ש לעיל."],[3,"ת\"ח, והקל נשמע:","זהו \u0003קל\u0004 בלי \u0003ו'\u0004 דהיינו הנוקבא כשהיא נפרדת מז\"א, זהו קול שבוכה על בית ראשון ועל בית שני. \u0003נשמע,\u0004 הוא כמו שאתה אומר, \u0003קול ברמה נשמע,\u0004 שואל, \u0003ברמה,\u0004 מהו \u0003ברמה.\u0004 ומשיב, זה הוא עולם העליון, עולם הבא. בינה. והסימן שלך. מן \u0003הרמה\u0004 ועד \u0003בית אל,\u0004 שפירושו מן העולם ועד העולם, דהיינו מן הבינה שנקראת \u0003רמה,\u0004 והוא עולם העליון, עד הנוקבא שנקראת \u0003בית אל,\u0004 והיא עולם התחתון, אף כאן, \u0003ברמה,\u0004 זהו עולם העליון, בינה. כי באותה שעה שנשמע ברמה, אז מה כתוב, ויקרא ה' אלקים צבאות ביום ההוא לבכי ולמספד וגו'."],[3,"","ביאור הדברים. נודע שבתחילת זווג זו\"ן נוהג פיוסא, שז\"א ממשיך לה הארת חכמה מקו שמאל דבינה, שעל ידי זה הנוקבא מתפייסת להזדווג עמו, כמ\"ש לעיל. (בראשית ב' דף קל\"ו ד\"ה פנימיות ובדף קל\"ה ד\"ה ביאור עש\"ה) והמשכה זו הוא על ידי עלייתם לבינה, שז\"א מלביש קו ימין שלה, שה\"ס חסדים, והנוקבא מלבשת קו שמאל שלה, שה\"ס הארת החכמה."],[3,"","ויש בזה הרבה תקונים: א) שמתפייסת עמו, בשביל שהמשיך לה הארת השמאל מבינה, שהיא בחינתה עצמה, שהיא חכמה, כמ\"ש שם. ב) כי עם הלבשתה את קו השמאל דבינה, מתעוררים שם הדינים הנוראים שבקו שמאל הזה, הסותמים לכל האורות שלה, ונעשתה כמו אש שורפת, שעי\"ז מתעוררת בה השתוקקות גדולה להזדווג עם ז\"א, ולקבל ממנו חסדים להלביש את הארת השמאל שלה. ג) שמחמת הדינים הקשים, היא מנחת את הג\"ר דהארת השמאל, ומקבלת רק הו\"ק דהארת השמאל. ועוד תקונים ואין להאריך."],[3,"","וזה אמרו, \u0003והקל נשמע, דא הוא קל בלי ו',\u0004 דהיינו בעת עליית הנוקבא לקו שמאל דבינה, שאז נפרדת מז\"א שנק' \u0003ו',\u0004 כי ז\"א, כולו ימין דבינה, והנוקבא, כולה שמאל דבינה, ורחוקים זה מזה מקצה אל הקצה, \u0003דא היא קלא דבכאת על מקדש ראשון ועל מקדש שני,\u0004 כי עם הלבשתה את קו השמאל דבינה, מתעוררים שם כל הדינים עד שכל אורותיה נסתמים, כנ\"ל בסוד תקון הב' להתעוררות הזווג. ואז נאמר ונהר יחרב ויבש, \u0003יחרב\u0004 בבית ראשון, שה\"ס בינה מבחינת ז\"ת שלה, \u0003ויבש\u0004 ה\"ס בית שני, שהוא הנוקבא. והיא בוכה על ב' חורבנות הללו. וז\"ש \u0003נשמע, כמה דאת אמר קול ברמה נשמע.\u0004 דהיינו שה \u0003קל\u0004 שהיא הנוקבא עלתה \u0003ונשמעת\u0004 בבינה, שנקראת \u0003רמה,\u0004 כמ\"ש, \u0003מאי ברמה, דא הוא עלמא עלאה\u0004 וכו', דהיינו שמלבשת את קו שמאל דבינה כנ\"ל. וז\"ש, דהא בההיא שעתא די ברמה נשמע, כדין מה כתיב, \u0003ויקרא ה' אלקים צבאות ביום ההוא לבכי ולמספד וגו'.\u0004 שזה הוא מחמת התעוררות הדינים הגדולים אשר שם. שסותמים כל אורותיה, כנ\"ל בסוד תקון הב'. ואז ונהר יחרב ויבש, שב' המקדשים נחרבים, כנ\"ל."],[4,"והקל נשמע:","שנשמע למעלה למעלה, דהיינו שהנוקבא עלתה למעלה לקו שמאל דבינה שאז נחרבים ב' המקדשים כנ\"ל בדיבור הסמוך. מה הטעם שנחרבים, משום שה \u0003ו',\u0004 שהוא ז\"א. נתרחק ונסתלק מן הנוקבא, שהוא מלביש לימין דבינה, והנוקבא לשמאל דבינה, ונתרחקו זה מזה מקצה אל הקצה כנ\"ל בסמוך, ואז רחל מבכה על בניה וגו' כי איננו. כי נסתמו כל אורותיה ואין לה מה להשפיע אל הבנים, וע\"כ הלכו בגלות. ושואל, הכתוב אומר, \u0003כי איננו,\u0004 כי אינם היה צריך לומר, דהיינו לשון רבים. ומשיב, אלא אומר, \u0003כי איננו,\u0004 כמו שבארוהו, אשר \u0003כי איננו,\u0004 פירושו, שבעלה אינו עמה, שאם בעלה היה נמצא עמה, שהוא ז\"א, היתה מתנחמת על הבנים. כי אז היו נפתחים ארותיה, ובניה לא היו בגלות, ומשום \u0003שאיננו,\u0004 אינה מתנחמת על הבנים שלה, כי הבנים נתרחקו ממנה משום שבעלה איננו עמה. וע\"כ אוה\"כ, כי איננו, ולא כי אינם."],[5,"ת\"ח בית פרעה:","הוא סימנך, כלומר שהוא מרמז למעלה, על הבינה, שהיא \u0003בית\u0004 שממנו מתפרעים ומתגלים כל האורות וכל הנרות. היינו ספירות הנוקבא המכונות נרות, וכל מה שהיה סתום נגלה משם. וע\"כ נקראת הבינה, בית פרעה. ושיעור הכתוב, והקל נשמע בית פרעה, הוא, שהנוקבא עלתה לקו שמאל דבינה, שאז כל הדינים מתעוררים שם עליה, שה\"ס תקון ב' להתעוררות הזווג, כנ\"ל (דף ל\"ב בד\"ה ויש בזה הרבה תקונים) ומשום כך, הקב\"ה מוציא כל האורות וכל הנרות להאיר לקול הזה שנקרא \u0003קל\u0004 בלא \u0003ו',\u0004 שהוא הנוקבא. כלומר, משום זה שנתעוררו עליה הדינים דשמאל, נתגברה בה ההשתוקקות אל הזווג, ונזדווגה עם ז\"א והשפיע לה כל האורות וכל הנרות."],[6,"ת\"ח כד יקים וכו':","בוא וראה, כשהקב\"ה יקים ל \u0003קל\u0004 הזה, שהוא הנוקבא, מעפר, ותתחבר עם ה \u0003ו',\u0004 שהוא ז\"א, אז כל מה שנאבד מהם, מישראל, בזמן הגלות, יחזור וישוב להם. ויתעדנו באורות עליונים הנוספים להם מעולם העליון, כמו שאתה אומר, והיה ביום ההוא יתקע וגו'."],[7,"ואתה צויתה זאת עשו וגו':","רבי חייא פתח, שמחו את ירושלים וגו'. בוא וראה, כשנחרב בית המקדש, והחטאים גרמו שהגלו ישראל מן הארץ, נסתלק הקב\"ה, למעלה למעלה. ולא השגיח על החורבן של בית המקדש ועל עמו שהגלו, ואז השכינה הגלתה עמהם."],[8,"כד נחת וכו':","כאשר ירד, השגיח על ביתו והנה נשרף, הסתכל על עמו והנה הגלו, שאל על הגבירה, דהיינו השכינה. והיא הגלתה. אז ויקרא ה' אלקים צבאות ביום ההוא לבכי ולמספד ולקרחה ולחגור שק, והיא גם היא, השכינה, מה כתוב בה, אלי כבתולה חגורת שק על בעל נעוריה. כמו שאתה אומר, \u0003כי איננו.\u0004 דהיינו בעלה כנ\"ל, משום שנסתלק ממנה, ונעשה פירוד."],[9,"ואפילו שמיא וארעא וכו':","ואפילו שמים וארץ התאבלו כולם, שכתוב, אלביש שמים קדרות ושק אשים כסותם, מלאכים העליונים כולם, התאבלו עליה, שכתוב הן אראלם צעקו וגו'. השמש והלבנה התאבלו ונחשכו אורותיהם, שכתוב, חשך השמש בצאתו וגו'. וכל העליונים ותחתונים בכו עליה, והתאבלו, מהו הטעם, משום שהסטרא אחרא שלטה עליה, ששלטה על ארץ הקדושה."]],[[0,"","מָה הַטַּעַם? מִשּׁוּם שֶׁהַתְּפִלָּה אֵינָהּ אוֹתוֹ הַקּוֹל שֶׁנִּשְׁמָע, שֶׁאוֹתוֹ קוֹל שֶׁנִּשְׁמָע אֵינוֹ תְפִלָּה. וּמַה הִיא תְּפִלָּה? זֶהוּ קוֹל אַחֵר שֶׁתָּלוּי בַּקּוֹל שֶׁנִּשְׁמָע. וּמִי הוּא הַקּוֹל שֶׁנִּשְׁמָע? זֶה אוֹתוֹ הַקּוֹל שֶׁהוּא בְּוָא\"ו, הַקּוֹל שֶׁתָּלוּי בּוֹ, זֶהוּ קֹל בְּלִי וָא\"ו."],[1,"","וּמִשּׁוּם כָּךְ לֹא צָרִיךְ לָאָדָם לִשְׁמֹעַ קוֹלוֹ בִּתְפִלָּתוֹ, אֶלָּא לְהִתְפַּלֵּל בְּלַחַשׁ בְּאוֹתוֹ הַקּוֹל שֶׁלֹּא נִשְׁמָע, וְזוֹ הַתְּפִלָּה שֶׁמִּתְקַבֶּלֶת תָּמִיד, וְסִימָן לַדָּבָר - וְהַקֹּל נִשְׁמַע. קֹל בְּלִי וָא\"ו, נִשְׁמַע. זוֹ הִיא הַתְּפִלָּה שֶׁהִיא בַּחֲשַׁאי, שֶׁכָּתוּב בְּחַנָּה וְקוֹלָהּ לֹא יִשָּׁמֵעַ. זוֹ הִיא הַתְּפִלָּה שֶׁמְּקַבֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁנַּעֲשֵׂית בְּתוֹךְ רָצוֹן וְכַוָּנָה וְתִקּוּן כָּרָאוּי, וּלְיַחֵד אֶת הַיִּחוּד שֶׁל רִבּוֹנוֹ כָּרָאוּי בְּכָל יוֹם. (והקל נשמע בית פרעה, והקל נשמע, חסר וא\"ו, מה הטעם? אמר רבי אלעזר, זו היא השכינה שבוכה על חרבן בית המקדש ועל גלותם של ישראל, כתוב כאן והקל נשמע, וכתוב שם, (ירמיה לא) קול ברמה נשמע, מה לפנינו שכינה, אף כאן גם כן שכינה)."],[2,"","רַבִּי אֶלְעָזָר אָמַר, הַקּוֹל בַּחֲשַׁאי זֶהוּ קוֹל עֶלְיוֹן שֶׁכָּל הַקּוֹלוֹת יוֹצְאִים מִשָּׁם. אֲבָל קֹל בְּלִי וָא\"ו, זוֹהִי הַתְּפִלָּה שֶׁל מַטָּה, שֶׁהִיא הוֹלֶכֶת לְהִתְעַלּוֹת בְּוָא\"ו וּלְהִתְחַבֵּר בּוֹ."],[3,"","בֹּא רְאֵה, וְהַקֹּל נִשְׁמַע, זֶה הוּא הַקֹּל בְּלִי וָא\"ו, זֶהוּ הַקּוֹל שֶׁבָּכָה עַל מִקְדָּשׁ רִאשׁוֹן וְעַל מִקְדָּשׁ שֵׁנִי. נִשְׁמַע, כְּמוֹ שֶׁנֶּאֱמַר קוֹל בְּרָמָה נִשְׁמָע. בְּרָמָה, מַה זֶּה בְּרָמָה? זֶה הוּא הָעוֹלָם הָעֶלְיוֹן, הָעוֹלָם הַבָּא, וְסִימָן לַדָּבָר - מִן הָרָמָה וְעַד בֵּית אֵל, (תהלים קו) מִן הָעוֹלָם וְעַד הָעוֹלָם. כָּאן בְּרָמָה - זֶה הָעוֹלָם הָעֶלְיוֹן, שֶׁהֲרֵי בַּשָּׁעָה הַהִיא שֶׁבְּרָמָה נִשְׁמָע, אָז מַה כָּתוּב? (ישעיה כב) וַיִּקְרָא ה' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וְגוֹ'."],[4,"","וְהַקֹל נִשְׁמַע, לְמַעְלָה לְמַעְלָה. מָה הַטַּעַם? מִשּׁוּם שֶׁוָּא\"ו הִתְרַחֵק וְהִסְתַּלֵּק מִמֶּנָּה, וְאָז רָחֵל מְבַכָּה עַל בָּנֶיהָ מֵאֲנָה לְהִנָּחֵם עַל בָּנֶיהָ כִּי אֵינֶנּוּ. כִּי אֵינֶנּוּ? כִּי אֵינָם צָרִיךְ הָיָה לִהְיוֹת! אֶלָּא כִּי אֵינֶנּוּ, וְהִנֵּה בֵּאַרְנוּ כִּי אֵינֶנּוּ, שֶׁבַּעְלָהּ לֹא נִמְצָא עִמָּהּ, שֶׁאִלְמָלֵא הָיָה בַּעְלָהּ נִמְצָא עִמָּהּ, תִּתְנַחֵם עֲלֵיהֶם, שֶׁהֲרֵי אָז בָּנֶיהָ לֹא יִהְיוּ בַּגָּלוּת, וּמִשּׁוּם שֶׁאֵינֶנּוּ, אֵינָהּ מִתְנַחֶמֶת עַל בָּנֶיהָ, מִשּׁוּם שֶׁבָּנֶיהָ הִתְרַחֲקוּ מִמֶּנָּה עַל שֶׁאֵינֶנּוּ עִמָּהּ."],[5,"","בֹּא רְאֵה, בֵּית פַּרְעֹה - זֶה הוּא סִימָן לַדָּבָר לְמַעְלָה, הַבַּיִת שֶׁנִּפְרָעִים וּמִתְגַּלִּים מִמֶּנּוּ כָּל הָאוֹרוֹת וְכָל הַמְּאוֹרוֹת, כָּל מַה שֶּׁהָיָה סָתוּם מִשָּׁם הִתְגַּלָּה, וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא אֶת כָּל הָאוֹרוֹת וְכָל הַמְּאוֹרוֹת, כְּדֵי לְהָאִיר לְאוֹתוֹ הַקּוֹל שֶׁנִּקְרָא קֹל בְּלִי וָא\"ו."],[6,"","בֹּא רְאֵה, כַּאֲשֶׁר יָקִים הַקָּדוֹשׁ בָּרוּךְ הוּא לְזֶה הַקּוֹל מֵהֶעָפָר וְיִתְחַבֵּר בָּאוֹת וָא\"ו, אָז כָּל מַה שֶּׁנֶּאֱבַד מֵהֶם בִּזְמַן הַגָּלוּת יַחֲזֹר, וְיִתְעַדְּנוּ בְּאוֹרוֹת עֶלְיוֹנִים שֶׁנּוֹסָפִים מִתּוֹךְ הָעוֹלָם הָעֶלְיוֹן, כְּמוֹ שֶׁנֶּאֱמַר וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וּבָאוּ הָאֹבְדִים בְּאֶרֶץ אַשּׁוּר וְהַנִּדָּחִים בְּאֶרֶץ מִצְרָיִם וְהִשְׁתַּחֲווּ לַה' בְּהַר הַקֹּדֶשׁ בִּירוּשָׁ לם."],[7,"","וְאַתָּה צֻוֵּיתָה זאת עָשׂוּ קְחוּ לָכֶם מֵאֶרֶץ מִצְרַיִם וְגוֹ'. רַבִּי חִיָּיא פָּתַח, שִׂמְחוּ אֶת יְרוּשָׁלם וְגִילוּ בָהּ כָּל אֹהֲבֶיהָ שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ וְגוֹ'. בֹּא רְאֵה, כְּשֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ וְגָרְמוּ הַחֲטָאִים וְגָלוּ יִשְׂרָאֵל מִן הָאָרֶץ, הִסְתַּלֵּק הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה לְמַעְלָה, וְלֹא הִשְׁגִּיחַ עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ וְעַל עַמּוֹ שֶׁגָּלוּ, וְאָז הַשְּׁכִינָה גָּלְתָה עִמָּהֶם."],[8,"","כְּשֶׁיָּרַד, הִשְׁגִּיחַ עַל בֵּיתוֹ שֶׁנִּשְׂרַף, הִסְתַּכֵּל עַל עַמּוֹ - וְהִנֵּה הָגְלָה. שָׁאַל עַל הַגְּבִירָה - וְהִיא גֹּרְשָׁה. אָז וַיִּקְרָא ה' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וּלְקָרְחָה וְלַחֲגֹר שַׂק. וְהִיא גַם הִיא מַה כָּתוּב בָּהּ? (יואל א) אֱלִי כִּבְתוּלָה חֲגֻרַת שַׂק עַל בַּעַל נְעוּרֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר כִּי אֵינֶנּוּ, מִשּׁוּם שֶׁהִסְתַּלֵּק מִמֶּנָּה וְנִמְצָא פֵרוּד."],[9,"","וַאֲפִלּוּ שָׁמַיִם וָאָרֶץ כֻּלָּם הִתְאַבְּלוּ עָלָיו, שֶׁכָּתוּב (ישעיה כ) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. מַלְאָכִים עֶלְיוֹנִים כֻּלָּם הִתְאַבְּלוּ עָלֶיהָ, שֶׁנֶּאֱמַר הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. הַשֶּׁמֶשׁ וְהַלְּבָנָה הִתְאַבְּלוּ וְהֶחְשִׁיכוּ אֶת אוֹרָם, שֶׁכָּתוּב חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ וְגוֹ', וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים בָּכוּ עָלֶיהָ וְהִתְאַבְּלוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁשּׁוֹלֵט עָלֶיהָ הַצַּד הָאַחֵר שֶׁשּׁוֹלֵט עַל הָאָרֶץ הַקְּדוֹשָׁה."]]],[["פָּתַח וְאָמַר, (יחזקאל ז׳:ב׳) וְאַתָּה בֶּן אָדָם כֹּה אָמַר ה' אֱלֹהִים לְאַדְמַת יִשְׂרָאֵל קֵץ בָּא הַקֵּץ עַל אַרְבַּע כַּנְפוֹת הָאָרֶץ. הַאי קְרָא רָזָא עִלָּאָה אִיהוּ. לְאַדְמַת יִשְׂרָאֵל קֵץ, מַאי אִיהוּ. וְכִי אַדְמַת יִשְׂרָאֵל קֵץ הִיא. אֶלָּא הָכִי הוּא וַדַּאי וְאִתְּמָר, קֵץ אִיהוּ לִימִינָא, קֵץ אִיהוּ לִשְׂמָאלָא. קֵץ לִימִינָא, דִּכְתִיב, (דניאל יב) לְקֵץ הַיָּמִין. קֵץ לִשְׂמָאלָא, דִּכְתִיב, (איוב כ״ח:ג׳) קֵץ שָׂם לַחשֶׁךְ וּלְכָל תַּכְלִית הוּא חוֹקֵר, וְדָא הוּא (בראשית ו׳:י״ג) קֵץ כָּל בָּשָׂר, כְּמָה דְאִתְּמָר.","קֵץ דִּימִינָא, הַיְינוּ דִכְתִיב לְאַדְמַת יִשְׂרָאֵל קֵץ. בָּא הַקֵּץ, דָּא קֵץ דִּשְׂמָאלָא. קֵץ דִּימִינָא, דָּא קֵץ דְּיֵצֶר הַטּוֹב. קֵץ דִּשְׂמָאלָא, דָּא קֵץ דְּיֵצֶר הָרָע, וְדָא אִיהוּ דְּכַד חוֹבִין גָּרְמוּ וְאִתְגַּבְּרוּ, אִתְגְּזַר וְאִתְיְיהִיב שָׁלְטָנָא לְמַלְכוּת הָרְשָׁעָה לְשַׁלְטָאָה, וּלְחָרָבָא בֵּיתֵיהּ וּמִקְדְּשֵׁיהּ. וְדָא הוּא דִכְתִיב, (יחזקאל ז׳:ה׳) כֹּה אָמַר ה' אֱלהִים רָעָה אַחַר רָעָה הִנֵּה בָאָה, וְכֹלָּא חַד.","וּבְגִין כָּךְ, אִתְאַבָּלוּ עִלָּאֵי וְתַתָּאֵי עַל דְּאִתְיְיהִיב שָׁלְטָנוֹ לְהַאי קֵץ דִּשְׂמָאלָא. וּבְגִין כָּךְ, כֵּיוָן דְּמַלְכוּ קַדִּישָׁא, מַלְכוּת שָׁמַיִם אִתְכַּפְיָא, וּמַלְכוּת חַיָּיבָא (אחרא) אִתְגַּבַּר. (כדין) אִית לֵיהּ לְכָל בַּר נָשׁ, לְאִתְאַבָּלָא עִמָּהּ, וּלְאִתְכַּפְיָא עִמָּהּ. וּבְגִין דְּכַד אִיהִי יִזְדַּקְּפָא, וְעַלְמָא יִתְחַדֵּי, יִתְחַדֵּי אִיהוּ בַּהֲדָהּ. דִּכְתִיב, (ישעיהו ס״ו:י׳) שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ כָּל הַמִּתְאַבְּלִים עָלֶיהָ.","תָּא חֲזֵי, כְּתִיב בְּהוּ בְּמִצְרַיִם, (ירמיה מו) עֶגְלָה יְפִיפִיָה מִצְרַיִם. וְרָזָא דְּעֶגְלָה דָא, הֲווּ יִשְׂרָאֵל תְּחוֹת שָׁלְטָנֵיהּ כַּמָּה זִמְנִין וְכַמָּה שְׁנִין. וּבְגִין דִּזְמִינִין יִשְׂרָאֵל לְשַׁלְּטָאָה לְבָתַר עֲלָהּ, אִתְרְמִיז לוֹן הַשְׁתָּא עֲגָלוֹת.","רִבִּי אֶלְעָזָר אָמַר, רֶמֶז רָמַז לֵיהּ יוֹסֵף לְיַעֲקֹב עַל עֶגְלָה עֲרוּפָה. דְּהָא בְּהַהוּא פִּרְקָא אִתְפְּרַשׁ מִנֵּיהּ. וְאוּקְמוּהָ, עֶגְלָה עֲרוּפָה, דְּאִיהִי אַתְיָא עַל דְּאִשְׁתַּכַּח קָטוֹלָא, וְלָא אִתְיְידַע מַאן קָטִיל לֵיהּ. וּבְגִין דְּלָא יִשְׁלְטוּן עַל אַרְעָא רוּחִין בִּישִׁין דְּלָא אִצְטְרִיכוּ, יַהֲבִין הַאי עֶגְלָה לְתִקּוּנָא, בְּגִין דְּלָא יִשְׁתְּמוֹדְעוּן לְגַבֵּיהּ, וְלָא יִשְׁלְטוּ עֲלַיְיהוּ. (לעיל קיד ע\"א)","תָּא חֲזֵי, כָּל בְּנֵי נָשָׁא כֻּלְּהוּ עָבְרִין עַל יְדֵי דְּמַלְאַךְ הַמָּוֶת, בַּר מֵהַאי דְּאַקְדִּימוּ לֵיהּ בְּנֵי נָשָׁא, עַד לָא יִמְטֵי זִמְנָא לְשַׁלְּטָאָה בֵּיהּ וְלִיטוֹל רְשׁוּ. דְּהָא לָא שַׁלִּיט בְּבַר נָשׁ, עַד דְּנָטִיל רְשׁוּ.","וּבְגִין כָּךְ, אִית לֵיהּ דִּינָא לְשַׁלְּטָאָה עַל הַהוּא אֲתַר. כְּמָה דְאַתְּ אָמֵר, (דברים כ״א:א׳) לא נוֹדַע מִי הִכָּהוּ. הָכִי נָמֵי אִית לֵיהּ דִּינָא דְּלָא אִתְיְידַע, בְּגִין לְקַטְרְגָא עַל הַהוּא אֲתַר. וְעַל דָּא, (דברים כ״א:ג׳) וְלָקְחוּ זִקְנֵי הָעִיר הַהִיא עֶגְלַת בָּקָר וְגו'. בְּגִין לְאַעֲבָרָא דִינֵיהּ דְּהַהוּא אֲתַר, וּלְאִתְתַּקָּנָא דְּלָא יִשְׁלוֹט בֵּיהּ מְקַטְרְגָא, וּלְאִשְׁתְּזָבָא מִנֵּיהּ.","תָּא חֲזֵי, יוֹסֵף כַּד אִתְפְּרַשׁ מֵאֲבוֹי, בְּלָא לְוָיָה, וּבְלָא אֲכִילָה אִשְׁתַּדַּר, וְהֲוָה מַה דְּהֲוָה. וְכַד אָמַר יַעֲקֹב, (בראשית ל״ז:ל״ה) טָרוֹף טוֹרַף יוֹסֵף, אָמַר, כִּי אֵרֵד אֶל בְּנִי אָבֵל שְׁאוֹלָה, דְּאֲנָא גָרִימְנָא לֵיהּ. וְתוּ, דַּהֲוֵינָא יָדַע דַּאֲחוֹי סַנְיָין לֵיהּ, וְשַׁדַּרְנָא לֵיהּ. וְרֶמֶז קָא רָמִיז לֵיהּ.","אָמַר לֵיהּ רִבִּי יְהוּדָה, אִינוּן עֲגָלוֹת עַל פִּי פַּרְעֹה שַׁדַּר לוֹן, דִּכְתִיב וַיִּתֵּן לָהֶם יוֹסֵף עֲגָלוֹת עַל פִּי פַּרְעֹה. אָמַר לֵיהּ, דִּיּוּקָא דְמִלָּה, דִּכְתִיב וְאַתָּה צֻוֵּיתָה זֹאת עֲשׂוּ. וְאַתָּה צֻוֵּיתָה דַּיְיקָא, וּבְגִין כָּךְ כְּתִיב בְּה\"א, מַשְׁמַע דְּיוֹסֵף תָּבַע לוֹן, וּבְגִין כָּךְ וַיִּתֵּן לָהֶם יוֹסֵף עֲגָלוֹת עַל פִּי פַּרְעֹה. וְיַעֲקֹב לָא אִתְקְיַּים בְּמִלָּה, עַד דְּחָמָא לוֹן. דִּכְתִיב, וַיַּרְא אֶת הָעֲגָלוֹת אֲשֶׁר שָׁלַח יוֹסֵף לָשֵׂאת אוֹתוֹ וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם.","אָמַר רַבִּי שִׁמְעוֹן, בְּקַדְמִיתָא וַתְּחִי רוּחַ יַעֲקֹב, וּלְבָתַר וַיֹּאמֶר יִשְׂרָאֵל רַב עוֹד יוֹסֵף בְּנִי חָי. אֶלָּא, בְּקַדְמִיתָא קָרֵי לֵיהּ אוֹרַיְיתָא יַעֲקֹב, בְּגִין שׁוּתָּפוּתָא, דְּאִשְׁתַּתְּפוּ שְׁכִינְתָּא בְּהַהוּא חֵרֶם, כַּד אִזְדַּבַּן יוֹסֵף. וְהַשְׁתָּא דִּשְׁכִינְתָּא סָלְקָא, כְּדֵין אִיהוּ, וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם, וְדָא הוּא רָזָא דִשְׁכִינְתָּא. וּבָתַר דְּאִיהִי קָיְימָא בְּקִיּוּמָא, (בגין) כְּדֵין דַּרְגָּא דִלְעֵילָא, אִתְעֲבַר לְגַבָּהּ, דַּרְגָּא דְּאִיהוּ יִשְׂרָאֵל. (נ\"א כדין דרגא דלעילא, אתער לגבה, ואיהו דרגא דישראל) מִכָּאן, דְּדַרְגָּא דִלְעֵילָא לָא אִתְעַר לְעֵילָא, עַד דְּאִתְעַר בְּקַדְמִיתָא לְתַתָּא, דְּהָא הָכָא וַתְּחִי רוּחַ יַעֲקֹב בְּקַדְמִיתָא, וּלְבָתַר וַיֹּאמֶר יִשְׂרָאֵל."],[[0,"פתח ואמר ואתה בן אדם וגו' לאדמת ישראל קץ וגו':","מקרא זה הוא סוד עליון, \u0003לאדמת ישראל קץ,\u0004 מה הוא, וכי אדמת ישראל קץ הוא. ומשיב, אלא כן הוא ודאי, ולמדנו, קץ הוא לימין, קץ הוא לשמאל. ומפרש, קץ לימין, שכתוב, לקץ הימין, קץ לשמאל, שכתוב, קץ שם לחשך ולכל תכלית הוא חוקר. וזה הוא קץ כל בשר כמו שלמדנו. (וזה נתבאר לעיל פרשת נח דף כ\"ח ד\"ה קץ לימינא ע\"ש)."],[1,"קץ דימינא וכו':","קץ הימין, היינו שכתוב \u0003ולאדמת ישראל קץ.\u0004 בא הקץ על ארבע כנפות הארץ, זה הוא קץ השמאל. קץ הימין זה הוא קץ יצר הטוב. קץ השמאל זה הוא קץ היצר הרע. וזה הוא, כאשר ההטאים גרמו ונתגברו, נגזר וניתן ממשלה למלכות הרשעה, לשלוט ולהחריב ביתו ומקדשו, וזה הוא, שכתוב, כה אמר ה' אלקים רעה אחר רעה הנה באה. והכל אחד."],[1,"","פירוש. השמאל, ה\"ס רעה, ששם דינים ועונשים, וקץ השמאל הוא רעה שניה, שהוא היצר הרע, שהוא השטן ומלאך המות. שזסו\"ה רעה אחר רעה הנה באה, ואומר, \u0003והכל אחד,\u0004 כי ב' רעות אלו נעשו אחד. כי נתחברו זה בזה."],[2,"ובג\"כ אתאבלו וכו':","ומשום זה התאבלו העליונים ותחתונים על שניתן הממשלה ל \u0003קץ\u0004 הזה של השמאל. ומשום זה, כיון שמלכות הקדושה, מלכות שמים הושפלה, ומלכות הרשעה התגברה, יש לכל אדם להתאבל עמה, עם המלכות הקדושה, ולהיות מושפל עמה. ובשביל זה, כאשר תקום המלכות הקדושה, והעולם יהיה שמח, ישמח גם הוא עמה, שכתוב שישו אתה משוש כל המתאבלים עליה."],[3,"תא חזי כתיב וכו':","בוא וראה, כתוב בהם, במצרים, \u0003עגלה יפיפיה מצרים,\u0004 ובסוד עגלה הזו, היו ישראל תחת ממשלתה כמה זמנים וכמה שנים, דהיינו רד\"ו שנים שהיו במצרים, ומשום שאחר כך עתידים ישראל למשול עליה, נרמז להם זה עתה, בהכתוב, קחו לכם מארץ מצרים \u0003עגלות\u0004 לטפכם וגו'."],[3,"","ביאור המאמר. כבר ידעת שקליפת מצרים ה\"ס המשכת החכמה ממעלה למטה מסוד קו השמאל, כמו החטא דעץ הדעת, כי הכלים והניצוצין שפגם אותם אדם בחטאו בעץ הדעת נפלו לחלקם של המצרים (כמ\"ש באורך לעיל לך דף מ\"ד ד\"ה ביאור, ודף מ\"ח ד\"ה ויש כאן)."],[3,"","והנה הכתוב אומר, קחו לכם מארץ מצרים עגלות וגו', שפנימיות הכתוב, יורה, שיקבלו מרכבות מארץ מצרים להמשכת המוחין, והוקשה לו לרבי חייא, היתכן שישמשו השבטים ויעקב בעגלות ארץ מצרים, שהן מרכבות הטומאה. ולתרץ זה מביא רבי חייא את הכתוב (באות ק\"ו) שמחו וגו' שישו אתה משוש כל המתאבלים עליה. ומקדים לבאר ענין הדינים הקשים השולטים בשעת הארת השמאל, שהוא סוד חורבן ביהמ\"ק וגלות ישראל וגלות השכינה וסוד הכתוב ויקרא ה' צבאות ביום ההוא לבכי ולמספד ולקרחה וגו', שהוא נוהג בכל זווג וזווג כמו שביאר ר' אלעזר במאמר הסמוך, (עי' בדף ל\"ב ד\"ה ביאור הדברים, עש\"ה בכל ההמשך) וכן הוא בזווגים הכוללים שהם גלות וגאולה. שבזמן שליטת השמאל, ניתן כח לס\"א לשלוט על ישראל, \u0003ולחרבא ביתיה ומקדשיה,\u0004 שבזה הוכן זווג השלם לשעת הגאולה, בשלמות ג' התקונים המובאים לעיל (בד\"ה ביאור הדברים עש\"ה) כי זווגים הפרטיים וזווגים הכוללים שוים זה לזה בכל סדריהם. ואחר כך, מרחיב הדברים בביאור קץ הימין וקץ השמאל. ומסיים, \u0003ובגין כך\u0004 וכו' \u0003אית ליה לכל בר נש לאתאבלא עמה ולאתכפיא עמה.\u0004 כלומר, שאין אדם יכול לקבל מאור שלימות הזווג של זו\"ן, אם אינו נכלל עם הנוקבא בעת שמתעוררים עליה הדינים הקשים של השמאל, שאז מתאבל עמה ומושפל עמה, כי על ידי זה מקבל גם הוא אותם ג' התקונים הנ\"ל המכשירים אותו להכלל בהארת הזווג, ועקרם הוא תקון הג', שיעזוב את הג\"ר דשמאל, דהיינו שלא ימשיך אור החכמה ממעלה למטה אלא ממטה למעלה שהוא בחינת ו\"ק בלבד, ואז, \u0003דכד איהי יזדקפא ועלמא יתחדי, יתחדי איהו בהדה,\u0004 דהיינו שיוכל להכלל ולקבל משלימות הזווג, \u0003דכתיב שישו אתה משוש כל המתאבלים עליה,\u0004 שפירושו שכל מי שנכלל עם הנוקבא בעת שנתעוררו עליה הדינים דקו שמאל, והתאבל עליה והושפל עמה, הוא ישיש עמה בעת שתהיה בזווג השלם. אמנם אם לא התאבל עליה, כי לא נכלל עמה בעת התעוררות הדינים הקשים, לא יוכל לשוש עמה ולקבל מהארת זווגה השלם, משום שאינו מובטח להשמר שלא להמשיך הג\"ר דשמאל, שאז תחזור ותתחזק שליטת הס\"א על הקדושה. לפיכך מדייק הכתוב, שישו אתה משוש כל המתאבלים עליה. כי המתאבל עמה בטוח שימשיך השיעור ו\"ק דג\"ר כראוי."],[3,"","ובזה נפתח הבנת הכתוב, ואתה צויתה וגו' קחו לכם מארץ מצרים עגלות וגו', ואומר, תא חזי, \u0003כתיב בהו במצרים, עגלה יפיפיה מצרים.\u0004 פירוש, כי ידעת שמצרים ה\"ס החכמה דקליפה, כנ\"ל, ויש בה ד' מדרגות \u0003חו\"ב תו\"מ,\u0004 המכונות \u0003שור פרה, עגל עגלה.\u0004 ולא הוברר ממנה לקדושה רק בחינת ו\"ק שלהם בלבד, שה\"ס ממטה למעלה, שהיא אור המלכות המכונה \u0003עגלה.\u0004 כמ\"ש בסו\"ה שישו אתה משוש כל המתאבלים עליה. ולפיכך אין הכתוב אומר שור או פרה יפיפיה, רק \u0003עגלה יפיפיה\u0004 מטעם שלא נברר מהם רק בחינת \u0003עגלה\u0004 בלבד, כמבואר."],[3,"","וז\"ש \u0003ורזא דעגלה דא, הוו ישראל תחוח שלטניה כמה זמנין וכמה שנין,\u0004 דהיינו רק בכדי לברר סוד \u0003עגלה\u0004 הזו, שה\"ס ו\"ק דשמאל כנ\"ל, היו ישראל תחת קליפת מצרים כמה זמנים וכמה שנים. כי יותר משיעור זה המכונה עגלה אסור לקחת ממצרים כנ\"ל, \u0003ובגין דזמינין ישראל לשלטאה לבתר עלה,\u0004 דהיינו בשעת הארת הזווג, עתידים ישראל לשלוט על עגלה זו, כלומר שיקבלו ו\"ק דחכמה, \u0003אתרמיז לון השתא עגלות,\u0004 נרמז להם בדברי פרעה, \u0003קחו לכם מארץ מצרים עגלות\u0004 וגו', כי שיעור זה מותר להם לקחת ממצרים. דהיינו השיעור בבחינת עגלות שהוא ו\"ק כנ\"ל. וע\"כ אין הכתוב אומר מרכבות, אלא עגלות, כדי לרמז על שיעורו של עגלה, כמבואר."],[4,"ר' אלעזר אמר וכו':","רא\"א, רמז רמז יוסף ליעקב על \u0003עגלה ערופה,\u0004 כי כשעסקו בפרק הזה, של עגלה ערופה, נפרד ממנו. ובארוהו, עגלה ערופה. היא באה, על שנמצא הרוג ולא נודע מי הכהו, וכדי שלא תשלוטנה על הארץ רוחות רעות שאין בהם חפץ, נותנים את עגלה הזו לתקון, שלא יכירו בו ולא ישלטו עליה, על הארץ, כמ\"ש לפנינו."],[5,"ת\"ח כל בני נשא וכו':","בוא וראה, כל בני אדם נפטרים על ידי מלאך המות, חוץ מזה, שהקדימו אותו בני אדם והרגוהו, מטרם שהגיע זמנו של מלאך המות לשלוט עליו, ולקבל רשות לקחת נשמתו, כי אינו שולט על האדם עד שמקבל רשות מלמעלה (כנ\"ל פרשת נח דף כ\"ט אות ע\"ח) וביאור הדברים, עיין לעיל וירא קי\"א ד\"ה ותא חזי."],[6,"ובג\"כ אית ליה וכו':","ומשום זה, יש לו למלאך המות לשלוט עליו מן הדין, כמש\"א ולא נודע מי הכהו. ויש לו גם כן דין, \u0003שלא נודע\u0004 מי הכהו, כדי לקטרג על מקום הזה שהוא הנוקבא. ועל כן \u0003ולקחו זקני העיר ההיא עגלת בקר וגו',\u0004 כדי להעביר הדין מאותו המקום, ולהתתקן שלא ישלוט עליו המקטרג, וינצל ממנו."],[6,"","פירוש. ב' מיני דין, נכללים בהכתוב, לא נודע מי הכהו. א) שכח הצמצום עלה למלכות ונסתלקו האורות דג\"ר מהנוקבא, שהם אור החיים. ב) שאפילו אם יתקנו אותה והג\"ר תחזרנה אל הנוקבא, יש עוד כח לסטרא אחרא, לקטרג עליה ולסתום אורותיה על ידי אחיזתו בג\"ר הללו, (כמ\"ש לעיל וירא דף קי\"א ד\"ה ותא חזי, ובד\"ה וקב\"ה חיים)."],[6,"","וזה אמרו, \u0003ובג\"כ אית ליה דינא לשלטאה על האי אתר\u0004 וכו', דהיינו לשלוט על הנוקבא, מחמת שנסתלקו ממנה אורות דג\"ר שהוא בחינת דין הא'. \u0003הכי נמי אית ליה דינא וכו' בגין לקטרגא על ההוא אתר,\u0004 דהיינו בחינת דין הב', שאם יתקנו אותה והג\"ר תחזרנה אליה, יוכל לסתום אורותיה. ועל כן היא צריכה לב' תקונים (כמ\"ש וירא דף קי\"א ד\"ה ורזא עלאה ע\"ש) וז\"ש וע\"ד \u0003ולקחו וגו' בגין לאעברא דיניה דההוא אתר,\u0004 דהיינו להעביר דין הצמצום ממנה ולתקנה שהג\"ר תחזרנה אליה. וזהו תקון לדין הא'. וזהו נעשה ע\"י הבאת העגלה. \u0003ולאתתקנא דלא ישלוט ביה מקטרגא,\u0004 דהיינו למעט אותה מג\"ר דג\"ר שבזה מתבטל אחיזת ס\"א, לסתום אורותיה, וזהו תקון לדין הב', ונעשה ע\"י עריפת העגלה. כמ\"ש כל זה באורך, לעיל (וירא קי\"א ד\"ה רזא עלאה) עש\"ה."],[7,"ת\"ח יוסף כד וכו':","בוא וראה יוסף כשנפרד מאביו, נשלח בלי לויה ובלי אכילה, והיה מה שהיה, וכשאמר יעקב טרוף טורף יוסף, אמר כי ארד אל בני אבל שאולה, כי אני גרמתי לו שנהרג, משום ששלחתי אותו בלי לויה, ואיני יכול לומר, ידינו לא שפכה את הדם הזה, כבעגלה ערופה, שפירושו, לא פטרנוהו בלי לויה. (סוטה ל\"ח:) ועוד שידעתי שאחיו שונאים אותו ושלחתי אותו אליהם. ורמז רמז לו יוסף על כל זה בשליחת העגלות."],[8,"א\"ל ר' יהודה וכו':","אמר לו ר\"י, אלו העגלות, על פי פרעה שלח אותם, שכתוב, ויתן להם וגו'. ואיך תאמר, שרמז רמז לו יוסף בשליחת עגלות. אמר לו ר' אלעזר, הדיוק של המלה, שכתוב, ואתת צויתה זאת עשו, שלא היה צריך לומר, ואתה צויתה, כי כבר כתוב, ויאמר פרעה אל יוסף אמר אל אחיך, אלא ואתה צויתה שאומר כאן הוא בדיוק, וע\"כ כתוב צוית \u0003ה\u0004 עם \u0003ה'\u0004 לבסוף, להורות שהוא בדיוק, שבא ללמדנו, שיוסף דרש ממנו, שיתן לו עגלות, וע\"כ ויתן להם יוסף על פי פרעה, כי יוסף היה הנותן, והוא בקש מפרעה. ולמה דרש מפרעה עגלות, הוא מטעם שרצה לרמז לאביו על עגלה ערופה כנ\"ל. וע\"כ, יעקב, לא האמין הדבר עד שראה את העגלות והבין הרמז שרמז לו, שכתוב וירא את העגלות וגו'."],[9,"אר\"ש בקדמיתא וכו':","אמר ר' שמעון, בתחילה כתוב, ותחי רוח יעקב, ואח\"כ, ויאמר ישראל רב עוד יוסף בני חי, למה מתחיל ביעקב וגומר בישראל. ומשיב, אלא בתחילה קראו התורה יעקב, בשביל השותפות שנשתתפה השכינה בחרם שעשו השבטים כשנמכר יוסף, שלא לגלות הדבר. שמשום זה נסתלקה השכינה מיעקב כל אותו הזמן. ועתה שחזרה אליו השכינה, נאמר, ותחי \u0003רוח יעקב\u0004 אביהם, שזהו סוד השכינה, הנקראת רוח יעקב, ואחר שהשכינה נתקיימה בו, אז המדרגה של מעלה עברה ממדרגת יעקב אל המדרגה שהוא ישראל, דהיינו ממדרגת מוחין דו\"ק שנקרא יעקב למדרגת מוחין דג\"ר שנקרא ישראל. מכאן נשמע, שהמדרגה שלמעלה אינה מתעוררת למעלה מטרם שנתעורר למטה. כי כאן כתוב ותחי רוח יעקב תחילה, שהוא ההתעוררות שלמטה, ואה\"כ כתוב ויאמר ישראל. שהוא התעוררות שלמעלה."]],[[0,"","פָּתַח וְאָמַר, (יחזקאל ז) וְאַתָּה בֶּן אָדָם כֹּה אָמַר ה' אֱלֹהִים לְאַדְמַת יִשְׂרָאֵל קֵץ בָּא הַקֵּץ עַל אַרְבַּע כַּנְפוֹת הָאָרֶץ. הַפָּסוּק הַזֶּה הוּא עֶלְיוֹן. מַה זֶּה לְאַדְמַת יִשְׂרָאֵל קֵץ, וְכִי אַדְמַת יִשְׂרָאֵל הִיא קֵץ? אֶלָּא כָּךְ זֶה וַדַּאי, וְנִתְבָּאֵר. הַקֵּץ הוּא לְיָמִין, וְהַקֵּץ הוּא לִשְׂמֹאל. קֵץ לְיָמִין - שֶׁכָּתוּב (דניאל יב) לְקֵץ הַיָּמִין. קֵץ לִשְׂמֹאל - שֶׁכָּתוּב (בראשית ו) קֵץ שָׂם לַחֹשֶׁךְ וּלְכָל תַּכְלִית הוּא חֹקֵר, וְזֶהוּ קֵץ כָּל בָּשָׂר, כְּמוֹ שֶׁנִּתְבָּאֵר."],[1,"","קֵץ שֶׁל הַיָּמִין - הַיְנוּ שֶׁכָּתוּב לְאַדְמַת יִשְׂרָאֵל קֵץ. בָּא הַקֵּץ - זֶה קֵץ הַשְּׂמֹאל. הַקֵּץ שֶׁל הַיָּמִין זֶה הַקֵּץ שֶׁל יֵצֶר הַטּוֹב. הַקֵּץ שֶׁל הַשְּׂמֹאל זֶה הַקֵּץ שֶׁל יֵצֶר הָרָע. וְזֶה הוּא שֶׁכַּאֲשֶׁר הַחֲטָאִים גָּרְמוּ וְהִתְגַּבְּרוּ, נִגְזַר וְנִתַּן הַשִּׁלְטוֹן לְמַלְכוּת הָרִשְׁעָה לִשְׁלֹט וּלְהַחֲרִיב בֵּיתוֹ וּמִקְדָּשׁוֹ, וְזֶהוּ שֶׁכָּתוּב (יחזקאל ז) כֹּה אָמַר ה' אֱלֹהִים רָעָה אַחַת רָעָה הִנֵּה בָאָה, וְהַכֹּל אֶחָד."],[2,"","וּמִשּׁוּם כָּךְ הִתְאַבְּלוּ עֶלְיוֹנִים וְתַחְתּוֹנִים, עַל שֶׁנִּתַּן הַשִּׁלְטוֹן לַקֵּץ הַזֶּה שֶׁל הַשְּׂמֹאל. וּמִשּׁוּם כָּךְ, כֵּיוָן שֶׁהַמַּלְכוּת הַקְּדוֹשָׁה, מַלְכוּת הַשָּׁמַיִם נִכְנְעָה, וּמַלְכוּת הָרִשְׁעָה (האחרת) הִתְגַּבְּרָה, (אז) יֵשׁ לְכָל אָדָם לְהִתְאַבֵּל עִמָּהּ וּלְהִכָּנַע עִמָּהּ, וּמִשּׁוּם שֶׁכַּאֲשֶׁר הִיא תִזְדַּקֵּף וְהָעוֹלָם יִתְחַדֵּשׁ הוּא יִתְחַדֵּשׁ עִמָּהּ, שֶׁכָּתוּב (ישעיה סו) שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ כָּל הַמִּתְאַבְּלִים עָלֶיהָ."],[3,"","בֹּא רְאֵה, כָּתוּב בְּמִצְרַיִם (ירמיה מו) עֶגְלָה יְפֵה פִיָּה מִצְרָיִם, וְהַסּוֹד שֶׁל הָעֶגְלָה הַזּוֹ הָיוּ יִשְׂרָאֵל תַּחַת שִׁלְטוֹנָהּ כַּמָּה פְעָמִים וְכַמָּה שָׁנִים. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל עֲתִידִים אַחַר כָּךְ לִשְׁלֹט עָלֶיהָ, נִרְמָז לָהֶם כָּאן עֲגָלוֹת."],[4,"","רַבִּי אֶלְעָזָר אָמַר, רֶמֶז רָמַז יוֹסֵף לְיַעֲקֹב עַל עֶגְלָה עֲרוּפָה, שֶׁהֲרֵי בְּאוֹתוֹ פֶרֶק נִפְרַד מִמֶּנּוּ. וּבֵאֲרוּהָ, עֶגְלָה עֲרוּפָה, שֶׁהִיא בָּאָה עַל שֶׁנִּמְצָא הָרוּג וְלֹא נוֹדָע מִי הָרַג אוֹתוֹ, וּכְדֵי שֶׁלֹּא יִשְׁלְטוּ עַל הָאָרֶץ רוּחוֹת רָעוֹת שֶׁאֵינָן צְרִיכוֹת, נוֹתְנִים אֶת הָעֶגְלָה הַזּוֹ לְתִקּוּן, כְּדֵי שֶׁלֹּא יִתְוַדְּעוּ אֵלָיו וְלֹא יִשְׁלְטוּ עֲלֵיהֶם."],[5,"","בֹּא רְאֵה, כָּל בְּנֵי הָאָדָם, כֻּלָּם עוֹבְרִים עַל יְדֵי מַלְאַךְ הַמָּוֶת, פְּרָט לָזֶה, שֶׁהִקְדִּימוּ אוֹתוֹ בְּנֵי אָדָם טֶרֶם הִגִּיעַ זְמַנּוֹ לִשְׁלֹט בּוֹ וְלִטֹּל רְשׁוּת, שֶׁהֲרֵי אֵין שׁוֹלֵט בָּאָדָם עַד שֶׁנּוֹטֵל רְשׁוּת."],[6,"","וּמִשּׁוּם כָּךְ יֵשׁ לוֹ דִּין לִשְׁלֹט עַל אוֹתוֹ מָקוֹם, כְּמוֹ שֶׁנֶּאֱמַר לֹא נוֹדַע מִי הִכָּהוּ. גַּם כָּךְ יֵשׁ לוֹ דִּין שֶׁלֹּא נוֹדַע כְּדֵי לְקַטְרֵג עַל אוֹתוֹ מָקוֹם, וְעַל כֵּן (דברים כא) וְלָקְחוּ זִקְנֵי הָעִיר הַהִיא עֶגְלַת בָּקָר וְגוֹ', כְּדֵי לְהַעֲבִיר דִּינוֹ שֶׁל הַמָּקוֹם הַהוּא, וּלְהִתַּקֵּן שֶׁלֹּא יִשְׁלֹט בּוֹ הַמְקַטְרֵג וּלְהִנָּצֵל מִמֶּנּוּ."],[7,"","בֹּא רְאֵה, כְּשֶׁנִּפְרַד יוֹסֵף מֵאָבִיו, בְּלִי לְוָיָה וּבְלִי אֲכִילָה נִשְׁלַח, וְהָיָה מַה שֶּׁהָיָה, וּכְשֶׁאָמַר יַעֲקֹב (בראשית לז) טָרֹף טֹרַף יוֹסֵף, אָמַר כִּי אֵרֵד אֶל בְּנִי אָבֵל שְׁאֹלָה, שֶׁאֲנִי גָרַמְתִּי לוֹ, וְעוֹד - שֶׁהָיִיתִי יוֹדֵעַ שֶׁאֶחָיו שׂוֹנְאִים אוֹתוֹ וְשָׁלַחְתִּי אוֹתוֹ, וְרֶמֶז הוּא רָמַז לוֹ."],[8,"","אָמַר לוֹ רַבִּי יְהוּדָה, אֶת אוֹתָם הָעֲגָלוֹת שָׁלַח אוֹתָם עַל פִּי פַרְעֹה, שֶׁכָּתוּב וַיִּתֵּן לָהֶם יוֹסֵף עֲגָלוֹת עַל פִּי פַרְעֹה. אָמַר לוֹ, דִּיּוּקוֹ שֶׁל דָּבָר, שֶׁכָּתוּב וְאַתָּה צֻוֵּיתָה זאת עֲשׂוּ. וְאַתָּה צֻוֵּיתָה דַּוְקָא, וּמִשּׁוּם כָּךְ כָּתוּב בְּהֵ\"א, מַשְׁמָע שֶׁיּוֹסֵף בִּקֵּשׁ אוֹתָם, וּמִשּׁוּם כָּךְ וַיִּתֵּן לָהֶם יוֹסֵף עֲגָלוֹת עַל פִּי פַרְעֹה, וְיַעֲקֹב לֹא עָמַד בַּדָּבָר עַד שֶׁרָאָה אוֹתָם, שֶׁכָּתוּב וַיַּרְא אֶת הָעֲגָלוֹת אֲשֶׁר שָׁלַח יוֹסֵף לָשֵׂאת אֹתוֹ וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם."],[9,"","אָמַר רַבִּי שִׁמְעוֹן, בָּרִאשׁוֹנָה וַתְּחִי רוּחַ יַעֲקֹב, וְאַחַר כָּךְ וַיּאמֶר יִשְׂרָאֵל רַב עוֹד יוֹסֵף בְּנִי חָי. אֶלָּא בָּרִאשׁוֹנָה קָרְאָה לוֹ הַתּוֹרָה יַעֲקֹב, מִשּׁוּם הַשֻּׁתָּפוּת, שֶׁשִּׁתְּפוּ אֶת הַשְּׁכִינָה בְּאוֹתוֹ חֵרֶם כְּשֶׁנִּמְכַּר יוֹסֵף, וְעַכְשָׁו שֶׁשְּׁכִינָה עָלְתָה, אָז הִיא וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם, וְזֶה הוּא סוֹד הַשְּׁכִינָה. וְאַחַר שֶׁהִיא עָמְדָה בְקִיּוּם, (משום) אָז הַדַּרְגָּה שֶׁלְּמַעְלָה עָבְרָה אֵלֶיהָ, הַדַּרְגָּה שֶׁהִיא יִשְׂרָאֵל. (אז הדרגה שלמעלה התעוררה אליה, וזוהי דרגה של ישראל) מִכָּאן שֶׁהַדַּרְגָּה שֶׁלְּמַעְלָה לֹא מִתְעוֹרֶרֶת לְמַעְלָה עַד שֶׁמִּתְעוֹרֶרֶת בָּרִאשׁוֹנָה לְמַטָּה, שֶׁהֲרֵי כָּאן וַתְּחִי רוּחַ יַעֲקֹב בָּרִאשׁוֹנָה, וְאַחַר כָּךְ וַיֹּאמֶר יִשְׂרָאֵל."]]],[["וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאֹת הַלַּיְלָה, בְּמַרְאַת כְּתִיב. תָּא חֲזֵי, וַיִּזְבַּח זְבָחִים לֵאלהֵי אָבִיו יִצְחָק, בְּקַדְמִיתָא. בְּגִין לְאִתְעָרָא שְׂמָאלָא בְּרָזָא דִרְחִימוּ. וּכְדֵין וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאוֹת הַלַּיְלָה, בְּהַאי דַרְגָּא דְּקָאֲמָרָן דְּאִיהִי מַרְאוֹת הַלַּיְלָה.","וַיֹּאמֶר אָנֹכִי הָאֵל אֱלֹהֵי אָבִיךָ, מַאי טַעְמָא. בְּגִין דְּסִטְרָא דִקְדּוּשָּׁה דִלְעֵילָא, הָכִי הוּא. דְּהָא סִטְרָא דִמְסָאֲבָא, לָא אַדְכַּר שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכָל סְטַר דִּקְדּוּשָּׁה אִדְכַּר בִּשְׁמֵיהּ. אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה וְגו', מִכָּאן, דִּשְׁכִינְתָּא נָחֲתַת עִמֵּיהּ בְּגָלוּתָא, וּבְכָל אֲתַר דְּיִשְׂרָאֵל אִתְגָּלוּ, שְׁכִינְתָּא אִתְגַּלְּיָא עִמְּהוֹן, וְהָא אוּקְמוּהָ.","תָּא חֲזֵי, כַּמָּה עֲגָלוֹת הֲווּ. שִׁית. כְּמָא דְאַתְּ אָמֵר, (במדבר ו) שֵׁשׁ עֶגְלוֹת צָב. דָּבָר אַחֵר, שִׁיתִּין הֲווּ, וְכֹלָּא רָזָא חָדָא. בְּקַדְמִיתָא כְּתִיב בָּעֲגָלוֹת אֲשֶׁר שָׁלַח יוֹסֵף, וּלְבַסּוֹף אֲשֶׁר שָׁלַח פַּרְעֹה. אֶלָּא, כֻּלְּהוּ דְּשַׁדַּר יוֹסֵף, הֲווּ בְּחוּשְׁבָּנָא כְּדְקָא חָזֵי. וְאִינוּן דְּשַׁדַּר פַּרְעֹה יַתִּיר מִנַּיְיהוּ, לָא הֲווּ בְּרָזָא דָא, וְלָא הֲווּ בְּחוּשְׁבָּנָא.","וְאִלֵּין וְאִלֵּין קָאָתוּ. בְּגִין כָּךְ, אֲשֶׁר שָׁלַח יוֹסֵף, אֲשֶׁר שָׁלַח פַּרְעֹה. וְכַד יִפְקוּן יִשְׂרָאֵל מִן גָּלוּתָא מַה כְּתִיב, (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה' וְגו':","וַיֶּאֱסוֹר יוֹסֵף מֶרְכַּבְתּוֹ, רִבִּי יִצְחָק פָּתַח וְאָמַר, (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא נָטוּי עַל רָאשֵׁיהֶם מִלְּמַעְלָה, הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, אִית חַיָּה לְעֵיל מִן חַיָּה, וְאִית חַיָּה קַדִּישָׁא דְּקָיְימָא עַל רִישׁ חֵיוָתָא.","וְאִית חַיָּה עִלָּאָה, לְעֵילָא עַל כָּל שְׁאָר חֵיוָתָא, וְהַאי (נ\"א ואית) חַיָּה שָׁלְטָא עַל כֻּלְּהוּ. בְּגִין דְּכַד הַאי חֵיוָתָא יָהֲבָא וְנָהֲרָא לְכֻלְּהוּ, כְּדֵין כֻּלְּהוּ נָטְלִין לְמַטְלָנוֹי, וִיהִיבַת דָּא לְדָא, וְשָׁלְטָא דָּא עַל דָּא.","וְאִית חֵיוָתָא לְעֵילָא עַל תַּתָּאֵי, עַל שְׁאָר חֵיוָתָא לְתַתָּא, וְכֻלְּהוּ אִתְּזָנוּ מִינָהּ, וְד' סִטְרֵי דְעַלְמָא רְשִׁימִין בָּהּ. אַנְפִּין נְהִירִין יְדִיעָן (דינין) לְכָל סְטַר, וְאִיהִי שָׁלְטָא עַל ד' סִטְרֵי. וְהָא אוּקְמוּהָ, דְּאִינוּן ג' לִסְטַר דָּא, וְג' לִסְטַר דָּא, וְכֵן לְד' סִטְרִין דְּעַלְמָא.","(שמות ריב ע\"א) וְאִית רָקִיעַ לְעֵיל מִן רָקִיעַ, וְהַאי רָקִיעַ דְּשָׁלְטָא עֲלַיְיהוּ, כֻּלְּהוּ מִסְתַּכְּלָן לְגַבֵּיהּ. מַה כְּתִיב, (יחזקאל א׳:כ״ג) וְתַחַת הָרָקִיעַ כַּנְפֵיהֶם יְשָׁרוֹת אִשָּׁה אֶל אֲחוֹתָהּ וְגו'. בְּגִין דְּכֻלְּהוּ שָׁלְטִין עַל מַה דְּאִתְפָּקְדוּ, וּשְׁלִיחוּ דְּקוּסְטָא דְּקוּפְטְרָא בְּהוּ.","וְאִינוּן לְכָל סְטַר תִּשְׁעָה, (ט') לְד' סִטְרִין דְּעַלְמָא, וְאִינוּן ל\"ו בְּחוּשְׁבְּנָא. וְכַד מִתְחַבְּרָן כֻּלְּהוּ, אִתְעֲבִידוּ רְשִׁימָא חָדָא בְּרָזָא דִשְׁמָא חָדָא, בְּיִחוּדָא שְׁלִים כִּדְקָחָזֵי.","וְכַד מִתְתַּקְנֵי לְגַבֵּי כָּרְסְיָא, מַה כְּתִיב. וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֶה אָדָם עָלָיו מִלְּמָעְלָה, וְהָא אוֹקִימְנָא (נ\"א דיוקנא) דְּהַאי אֶבֶן טָבָא בְּכָרְסְיָא דְּקָיְימָא עַל ד' קָיְימִין, וְעַל הַהוּא כָּרְסְיָא דִּיוּקְנָא דְאָדָם, לְאִתְחַבְּרָא בֵּיהּ כְּחֲדָא, וּלְאִתְבָּרְכָא כְּדְקָא יְאוּת.","וְכַד אִיהִי מִתְתַּקְנָא לְגַבֵּיהּ דְּאָדָם, לְמֶהֱוֵי כֹּלָּא רְתִיכָא (נ\"א קדישא, וכהן כלא רתיכא) חָדָא, לְהַאי אָדָם. כְּדֵין כְּתִיב, וַיֶּאֱסוֹר יוֹסֵף מֶרְכַּבְתּוֹ דָּא צַדִּיק. וַיַּעַל לִקְרַאת יִשְׂרָאֵל אָבִיו גּשְׁנָה. לִקְרַאת יִשְׂרָאֵל, דָּא רָזָא דְּאָדָם. גּשְׁנָה, תִּקְרוּבְתָּא חָדָא, לְאִתְקְרָבָא כְּחֲדָא, בְּקָרְבָּנָא חָדָא וְיִחוּדָא חָדָא.","וַיֵּרָא אֵלָיו, דְּכַד אִתְחֲזֵי שִׁמְשָׁא בְּסִיהֲרָא, כְּדֵין נָהִיר סִיהֲרָא וְאַנְהִיר לְכֻלְּהוּ דִלְתַתָּא. וְכֵן כְּגַוְונָא דָא, כָּל זִמְנָא דִּקְדּוּשָּׁה דִלְעֵילָא שָׁרָא עַל מַקְדְּשָׁא דִלְתַתָּא, אִתְנְהִיר בֵּי מַקְדְּשָׁא וְקָיְימָא בִּשְׁלִימוּתֵיהּ. וְכַד אִסְתַּלַּק מִנֵּיהּ וְאִתְחָרִיב בֵּי מַקְדְּשָׁא, כְּדֵין, וַיֵּבְךִ עַל צַוָּארָיו עוֹד. דְּבָכוּן כֹּלָּא עַל מַקְדְּשָׁא דְּאִתְחָרִיב. עוֹד, מַאי עוֹד. דָּא גָלוּתָא בַּתְרָאָה.","כְּדֵין כֵּיוָן דְּחָמָא יַעֲקֹב וְאִסְתַּכַּל דְּהָא תִּקּוּנָא דִלְתַתָּא אִשְׁתַּכְלַל כְּגַוְונָא דִלְעֵילָא, כְּדֵין אָמַר אָמוּתָה הַפָּעַם וְגו'. כִּי עוֹדְךָ חַי, דְּאִתְקָיְימַת בְּרָזָא דִּבְרִית קַדִּישָׁא, דְּאִקְרֵי חַי הָעוֹלָמִים, וּבְגִין כָּךְ כִּי עוֹדְךָ חָי. וְעַל דָּא בְּקַדְמִיתָא אָמַר, רַב עוֹד יוֹסֵף בְּנִי חָי, דְּאִצְטְרִיךְ לְמֵיקַם בְּרָזָא דְחַי, וְהָא אִתְּמָר."],[[0,"ויאמר אלקים וגו' במראות הלילה:","במראת כתיב, בלי \u0003ו',\u0004 שהוא לשון יחיד, הרומז למדרגת הנוקבא הנקראת מראה, ונקראת לילה. בוא וראה, ויזבח זבחים לאלקי אביו יצחק, כתוב בתחילה, כדי לעורר השמאל. שנקרא יצחק, בסוד האהבה אל הנוקבא, דהיינו אהבת דודים הנמשכת משמאל, ואז, ויאמר אלקים לישראל במראת הלילה, דהיינו שנתגלה עליו. באותה מדרגה שאמרנו, שהיא הנוקבה, הנקראת מראת הלילה."],[1,"ויאמר אנכי האל אלקי אביך:","שואל מהו הטעם שהזכיר לו את שמו, ומשיב משום שהצד הקדוש שלמעלה נוהג כן. כי צד הטומאה אינו מזכיר שמו של הקב\"ה, וכל צד הקדושה נזכר בשמו. אנכי ארד עמך מצרימה וגו', מכאן, שהשכינה ירדה עמו בגלות. ובכל מקום שגלו ישראל גלתה עמהם השכינה, ובארוהו."],[2,"ת\"ח כמה עגלות וכו':","שואל בוא וראה כמה עגלות היו. ומשיב שש היו. כמו שאתה אומר \u0003שש עגלות\u0004 צב. דבר אחר, ששים היו. והכל סוד אחד. כי \u0003שש\u0004 רומזות לששה ספירות. חג\"ת נה\"י. \u0003וששים,\u0004 רומזות"],[2,"בקדמיתא כתיב וכו':","שואל בתחילה כתיב, בעגלות אשר שלח יוסף, ולבסוף אשר שלח פרעה. ומשיב, אלא כל העגלות ששלח יוסף היו בחשבון כראוי, ואלו ששלח פרעה יותר עליהם, לא היו בסוד הזה, ולא היו בחשבון. פירוש. \u0003העגלות,\u0004 ה\"ס צורת המוחין דהארת חכמה, כנ\"ל, \u0003וחשבון,\u0004 ה\"ס המלכות שנקראת חשבון כנודע. וז\"ש \u0003כלהו דשדר יוסף הוו בחושבנא,\u0004 כלומר, שהיו רק בשיעור אור המלכות שה\"ס ו\"ק דג\"ר וכנ\"ל (דף ל\"ו ד\"ה ובזה נפתח), שרק שיעור זה מותר לקחת ממצרים ולא יותר, שה\"ס עגלה, כמ\"ש שם. אבל אלו ששלח פרעה \u0003לא הוו ברזא דא ולא הוו בחושבנא,\u0004 אלא, למעלה משיעור עגלה, דהיינו מבחינת שור פרה עגל. שזה היתה מנחה מצד פרעה, שהיה אסור ליוסף, כנ\"ל."],[3,"ואלין ואלין קאתו וכו':","ואלו ואלו באו ליעקב, הן מבחינת עגלה, ששלח יוסף והן מבחינות שלמעלה מעגלה ששלח פרעה. וע\"כ כתוב, אשר שלח יוסף, אשר שלח פרעה. וכשיצאו ישראל מן הגלות מה כתוב, והביאו וגו'. כי אז יביאו כל האומות מנחה לה' כמו פרעה."],[4,"ויאסור יוסף מרכבתו:","ר' יצחק פתח ואמר, ודמות על ראשי החיה וגו'. מקרא זה בארוהו, אבל בוא וראה, יש חיה למעלה מחיה. פירוש החיה מבחינת קו ימין שהוא פני אריה, דהיינו חסד, היא למעלה וחשובה יותר מן החיה שבקו שמאל שהוא פני שור. כי ד' חיות הן בסוד המרכבה: אריה שור ונשר הן כנגד ג' קוין ימין שמאל ואמצע, וחיה הרביעית הוא פני אדם, הכוללת את הג'. כמו שמפרש לפנינו."],[4,"ואית חיה קדישא דקיימא על ריש חיותא:","ויש חיה קדושה העומדת על ראשי החיות. פירוש. היא החיה מבחינת קו שמאל, שהיא פני שור, דהיינו גבורה, ואחר התכללותה בימין נמשכת ממנה המוחין דראש לכל החיות, כי מקו שמאל נמשך הארת החכמה, וע\"כ אומר \u0003דקיימא על ריש חיותא.\u0004 כלומר, שעומדת לבחינת ראש אל החיות."],[5,"ואית חיה עלאה לעילא על כל שאר חיותא וכו':","ויש חיה עליונה למעלה על כל שאר החיות, היינו החיה שמבחינת קו אמצעי, שהיא פני נשר דהיינו תפארת, ומתוך שהיא מכרעת על ב' החיות שבימין ושמאל, וכוללן יחד זו בזו, ע\"כ היא נבחנת שהיא למעלה מהן, שפירושו, חשובה מהן. וחיה זו שולטת על כולן, משום כאשר חיה הזו נותנת כחה, ומאירה לכולן, שה\"ס כח המסך דחירק והארת החסדים, שהן ב' ענינים הפועלים בקו אמצעי (כנ\"ל לך דף י\"ג ד\"ה ונתבאר), אז כולן נוסעות למסעיהן, היינו שנכללות זו מזו, ונותנת זו לזו מכחה, ושולטות זו על זו, שניתן שליטה לכל אחת ואחת על כולן, כי בג' שבקו ימין שולטת פני האריה, ובג' שבשמאל שולטת פני השור, ובג' שבאמצעי שולטת פני נשר."],[6,"ואית חיותא לעילא על תתאי וכו':","ויש חיה שהיא למעלה על התחתונים, דהיינו על שאר החיות שהן למטה, מעולם אצילות, שהיא פני אדם, דהיינו הנוקבא, וכולן ניזונות ממנה. וארבע רוחות העולם רשומות בה, שה\"ס חו\"ג תו\"מ כנ\"ל, פנים ידועות מאירים לכל רוח, שהן ג' פנים אריה שור נשר המאירים בכל רוח מד' הרוחות, שב' הרוחות דרומית וצפונית, הם ימין ושמאל. ומזרחית, ה\"ס קו אמצעי. ומערבית, ה\"ס הנוקבא, המקבלת את כולן וכוללת כולן. והיא, הנוקבא, שולטת על ד' הרוחות. והרי בארוה, שהן ג' לרוח זו וג' לרוח זו וכן לד' רוחות העולם. כלומר אחר שכולן נכללות זו מזו, אינן ד' בכל רוח, שהן ט\"ו אלא ג' לכל רוח, שהן י\"ב פנים. והטעם נתבאר לעיל ב\"א דף פ\"ז ד\"ה ואלין ע\"ש."],[7,"ואית רקיע לעיל מן רקיע וכו':","ויש רקיע למעלה מרקיע, ורקיע הזה השולט עליהם, דהיינו ג' רקיעים, שהימני והשמאלי הם זה למעלה מזה, ורקיע האמצעי הוא השולט על שניהם, דהיינו שמכריע אותם וכוללם זה בזה. כנ\"ל אצל החיות. כולם מסתכלים אליו, דהיינו שמקבלים ממנו ההכרעה וההתכללות. מה כתוב, ותחת הרקיע כנפיהן ישרות וגו', משום שכולן שולטות על מה שנתמנו, כי קו האמצעי מקיים הארת שניהם יחד, שהימני יאיר ממעלה למטה, והשמאלי ממטה למעלה, ועל כן כנף הימנית שוה עם כנף השמאלית. והתפשטות מדת החבל בהם, דהיינו כח המסך שבקו האמצעי, שקושר הימין ושמאל ביחד."],[7,"שליחו,","פירושו התפשטות והשקאה, כמו בית השלחין (מועד קטן ב.) שהוא שדה שמשקים אותו מים, והמים מתפשטים בו. \u0003קוסטא,\u0004 פירושו מדה. \u0003קופטרא,\u0004 פירושו חבל שקושרים בו את הספינה אל החוף, מלשון כקפטורין יוצאת מתוך הושט. (תנחומא מקץ)."],[8,"דאנון לכל סטר וכו':","והם, ג' הרקיעים נמצאים בכל רוח, דהיינו שנכללים זה מזה, ובכל אחד מג' יש ג', והם תשעה תשעה לכל הצדדים, שיש ט' ברוח מזרחית וט' ברוח מערבית וכו' כן. דהיינו ד\"פ תשעה, והם במספר ל\"ו רקיעים, וכשמתחברים, כולם נעשו לרושם אחד, דהיינו לרקיע אחד, בסוד שם אחד, דהיינו הנוקבא הנקראת שם, ביחוד השלם כראוי."],[9,"וכד מתתקני לגבי כרסיא וכו':","וכשהם, דהיינו הרקיעים והחיות, מתתקנים לבחינת כסא, מה כתוב, וממעל לרקיע אשר על ראשם כמראה אבן ספיר דמות כסא, ועל דמות הכסא כמראה אדם עליו מלמעלה. והנה בארוה, שאותה אבן טוב, שהיא הנוקבא, מתתקנת בכסא העומדת על ד' עמודים, ועל כסא ההיא דמות אדם, שהוא ז\"א, להתחבר עמו יחד, שהכסא שהיא הנוקבא, תתחבר עם האדם שעליו, שהוא ז\"א, ולהתברך ממנו כראוי."],[9,"","פירוש. הרקיע והחיות הנ\"ל פעמים מתתקנים בבחינת \u0003כסא,\u0004 ופעמים בבחינת \u0003מרכבה,\u0004 כמ\"ש לפנינו. ושניהם הם תקון הנוקבא לזווג עם ז\"א, כנ\"ל, אלא כשמתתקנים בשליטת הימין מכונים \u0003כסא.\u0004 וכשמתתקנים בשליטת השמאל, מכונים \u0003מרכבה.\u0004"],[10,"וכד איהי מתתקנא וכו' למהוי כלא רתיכא וכו':","וכשהיא, דהיינו הרקיעים והחיות שהם סוד הנוקבא כנ\"ל, מתתקנת להיות הכל \u0003מרכבה\u0004 אחת לאדם הזה, שהוא ז\"א, אז נאמר \u0003ויאסור יוסף מרכבתו,\u0004 זהו צדיק, דהיינו יסוד דז\"א, שנקרא יוסף הצדיק, קשר ואיחד את \u0003מרכבתו,\u0004 שהיא הנוקבא בסוד הרקיעים והחיות כנ\"ל, \u0003ויעל לקראת ישראל אביו גשנה\u0004 לקראת \u0003ישראל,\u0004 זהו סוד אדם, דהיינו האדם שממעל לכסא הנ\"ל, שהוא ז\"א. גשנה, פירושו, גישה אחת להתקרב יחד בקריבה אחת ויחוד אחד. פירוש. \u0003גשנה,\u0004 היא מלשון \u0003גשו אלי\u0004 שהוא קריבה וסוד הזווג של ז\"א ונוקבא, המרומזים כאן במרכבתו דיוסף וישראל אביו. והוציא הכתוב לרמז הזווג בלשון \u0003גישה,\u0004 הוא להיותו בחינת שליטת השמאל הנוהג בתחילת כל זווג, בסו\"ה שמאלו תחת לראשי וגו', שהיא רק גישה אחת, ותכף נפרש וחוזר לימין, מטעם הדינין המתעוררים עם שליטה זאת. ומטעם שנסתמים אז כל האורות. וז\"ש \u0003תקרובתא חדא וכו',\u0004 ותכף נפרש מזה."],[11,"וירא אליו:","הוקשה לו הלשון, \u0003וירא אליו,\u0004 שמשמעותו, שנראה אליו ונסתלק, ומה משמיענו הכתוב בזה. ואומר, כאשר השמש, נראה אל הלבנה, אז מאירה הלבנה, ומאירה לכל אלו שהם למטה בעולם, וכן כעין זה, כל זמן שהקדושה העליונה, דהיינו אור ז\"א, שורה על בית המקדש למטה, שהיא הנוקבא, מאיר בית המקדש ועומד בשלימותו. אבל כאן נאמר \u0003וירא\u0004 אליו, שמשמע שנראה לה האור ונסתלק, ולאחר שנסתלק ממנה אור העליון, של ז\"א, אומר הכתוב, אז \u0003ויבך על צואריו עוד,\u0004 שכולם בכו על בית המקדש שנחרב דהיינו על הפסק האור מן הנוקבא, בסבת הזווג הזה שבשליטת השמאל, שמסבה זו תכף חוזר לימין, כנ\"ל. הכתוב אומר \u0003עוד,\u0004 מהו \u0003עוד:\u0004 זה גלות האחרון, דהיינו רוב הדינים הנמשכים על ישראל בגלות האחרון מסבת שליטת השמאל, שמשום זה נפרש תיכף מזה, וחזר לימין. כמ\"ש לפנינו."],[12,"וכדין כיון דחמא וכו':","ואז כיון שראה יעקב והסתכל, שהתקון שלמטה בזו\"ן, הוא כעין שלמעלה באו\"א, דהיינו שנזדווג בשליטת הימין והאורות חזרו ונפתחו כמו למעלה, אז אמר \u0003אמותה הפעם אחרי ראותי את פניך כי עודך חי,\u0004 שפירושו, שאתה מתקיים בסוד ברית הקדוש שנקרא חי העולמים, ומשום זה, \u0003כי עודך חי,\u0004 ועל כן אמר בתחילה, רב עוד יוסף בני חי, כי הוא צריך להיות בסוד \u0003חי,\u0004 וכבר נתבאר."],[12,"","ושיעור הכתוב הוא, כי הסתלקות האורות שנעשה אחר הזווג שבשליטת השמאל נבחן כמו מיתה, דהיינו הסתלקות אורות החיים, וזה שאה\"כ, \u0003אמותה הפעם אחרי ראותי פניך,\u0004 כי ע\"כ נסתלקו האורות אחר התחלת הזווג המרומז בהכתוב \u0003וירא אליו,\u0004 כנ\"ל, שהוא מיתה, הוא מטעם, \u0003כי עודך חי,\u0004 כי עודך ברית קדוש בסוד \u0003חי העולמים,\u0004 שהוא ימין, שאז אור החכמה שנק' \u0003חי\u0004 מתלבש בחסדים ומתקיים, וע\"כ הוכרחתי להחזיר הזווג בשליטת הימין."]],[[0,"","וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאֹת הַלַּיְלָה. בְּמַרְאַת כָּתוּב. בּא רְאֵה, וַיִּזְבַּח זְבָחִים לֵאלֹהֵי אָבִיו יִצְחָק, בָּרִאשׁוֹנָה, כְּדֵי לְהָעִיר אֶת הַשְּׂמֹאל בַּסּוֹד שֶׁל הָאַהֲבָה. וְאָז - וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאֹת הַלַּיְלָה, בַּדַּרְגָּה הַזּוֹ שֶׁאָמַרְנוּ, שֶׁהִיא מַרְאוֹת הַלַּיְלָה."],[1,"","וַיֹּאמֶר אָנֹכִי הָאֵל אֱלֹהֵי אָבִיךְ. מָה הַטַּעַם? מִשּׁוּם שֶׁצַּד הַקְּדֻשָּׁה שֶׁלְּמַעְלָה כָּךְ הוּא, שֶׁהֲרֵי צַד הַטֻּמְאָה לֹא מַזְכִּיר אֶת שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל צַד הַקְּדֻשָּׁה נִזְכָּר בִּשְׁמוֹ. אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה וְגוֹ'. מִכָּאן שֶׁשְּׁכִינָה יָרְדָה עִמּוֹ בַּגָּלוּת, וּבְכָל מָקוֹם שֶׁיִּשְׂרָאֵל גָּלוּ - שְׁכִינָה גָּלְתָה עִמָּהֶם, וְהִנֵּה פֵּרְשׁוּהָ."],[2,"","בֹּא רְאֵה, כַּמָּה עֲגָלוֹת הָיוּ? שֵׁשׁ, כְּמוֹ שֶׁנֶּאֱמַר (במדבר ז) שֵׁשׁ עֶגְלוֹת צָב. דָּבָר אַחֵר, שִׁשִּׁים הָיוּ, וְהַכֹּל סוֹד אֶחָד. בָּרִאשׁוֹנָה כָּתוּב בָּעֲגָלוֹת אֲשֶׁר שָׁלַח יוֹסֵף, וּלְבַסּוֹף - אֲשֶׁר שָׁלַח פַּרְעֹה. אֶלָּא כֻּלָּם שֶׁשָּׁלַח יוֹסֵף הָיוּ בַּחֶשְׁבּוֹן כָּרָאוּי, וְאוֹתָם שֶׁשָּׁלַח פַּרְעֹה יוֹתֵר מֵהֶם, לֹא הָיוּ בְּסוֹד זֶה וְלֹא הָיוּ בַּחֶשְׁבּוֹן."],[3,"","וְאֵלֶּה וְאֵלֶּה בָּאוּ, מִשּׁוּם כָּךְ אֲשֶׁר שָׁלַח יוֹסֵף, אֲשֶׁר שָׁלַח פַּרְעֹה. וּכְשֶׁיָּצְאוּ יִשְׂרָאֵל מִן הַגָּלוּת מַה כָּתוּב? (ישעיה סו) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה' וְגוֹ'."],[4,"","וַיֶּאְסֹר יוֹסֵף מֶרְכַּבְתּוֹ. רַבִּי יִצְחָק פָּתַח וְאָמַר, (יחזקאל א) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא נָטוּי עַל רָאשֵׁיהֶם מִלְמַעְלָה. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, אֲבָל בֹּא רְאֵה, יֵשׁ חַיָּה לְמַעְלָה מִן הַחַיָּה, וְיֵשׁ חַיָּה קְדוֹשָׁה שֶׁעוֹמֶדֶת עַל רֹאשׁ הַחַיּוֹת."],[5,"","וְיִשִׁ חַיָּה עֶלְיוֹנָה לְמַעְלָה עַל כָּל שְׁאָר הַחַיּוֹת, וְזוֹ (ויש) הַחַיָּה שׁוֹלֶטֶת עַל כֻּלָּם, מִשּׁוּם שֶׁכַּאֲשֶׁר הַחַיָּה הַזּוֹ נוֹתֶנֶת וּמְאִירָה לְכֻלָּם, אָז כֻּלָּן נוֹסְעוֹת לְמַסְעוֹתֵיהֶן וְנוֹתְנוֹת זוֹ לָזוֹ וְשׁוֹלְטוֹת זוֹ עַל זוֹ."],[6,"","וְיִשִׁ חַיָּה לְמַעְלָה עַל הַתַּחְתּוֹנִים עַל שְׁאָר הַחַיּוֹת שֶׁלְּמַטָּה, וְכֻלָּם נִזּוֹנִים מִמֶּנָּה, וְאַרְבַּעַת צִדְדֵי הָעוֹלָם רְשׁוּמִים בָּהּ, פָּנִים מְאִירוֹת יְדוּעוֹת (דינים) לְכָל צַד, וְהִיא שׁוֹלֶטֶת עַל אַרְבָּעָה צְדָדִים, וְהִנֵּה פֵּרְשׁוּהָ, שֶׁהֵם שָׁלֹשׁ לְצַד זֶה וְשָׁלֹשׁ לְצַד זֶה, וְכֵן לְאַרְבַּעַת צִדְדֵי הָעוֹלָם."],[7,"","וְיִשִׁ רָקִיעַ לְמַעְלָה מִן הָרָקִיעַ, וְהָרָקִיעַ הַזֶּה שֶׁשּׁוֹלֵט עֲלֵיהֶם, כֻּלָּם מִסְתַּכְּלִים כְּלַפָּיו. מַה כָּתוּב? (יחזקאל א) וְתַחַת הָרָקִיעַ כַּנְפֵיהֶם יְשָׁרוֹת אִשָּׁה אֶל אֲחוֹתָהּ וְגוֹ', מִשּׁוּם שֶׁכֻּלָּם שׁוֹלְטִים עַל מַה שֶּׁנִּפְקְדוּ, וּשְׁלִיחוּת שֶׁל מִדַּת הַחֶבֶל בָּהֶם."],[8,"","וְהֵם תִּשְׁעָה לְכָל צַד, לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וְהֵם ל\"ו בְּחֶשְׁבּוֹן. וּכְשֶׁכֻּלָּם מִתְחַבְּרִים, נַעֲשִׂים רִשּׁוּם אֶחָד, בְּסוֹד שֶׁל שֵׁם אֶחָד, בְּיִחוּד שָׁלֵם כָּרָאוּי."],[9,"","וּכְשֶׁנִּתְקָנִים כְּלַפֵּי הַכִּסֵּא, מַה כָּתוּב? וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. וַהֲרֵי בֵּאַרְנוּ, (דמות) שֶׁהָאֶבֶן הַטּוֹבָה הַזּוֹ בַּכִּסֵּא, שֶׁעוֹמֵד עַל אַרְבָּעָה עַמּוּדִים, וְעַל אוֹתוֹ הַכִּסֵּא דְּמוּת שֶׁל אָדָם, לְהִתְחַבֵּר בּוֹ יַחַד וּלְהִתְבָּרֵךְ כָּרָאוּי."],[10,"","וּכְשֶׁהִיא נִתְקֶנֶת כְּלַפֵּי אָדָם, שֶׁהַכֹּל יִהְיֶה מֶרְכָּבָה (נ\"א: קדושה, ואז כל המרכבה) אַחַת לָאָדָם הַזֶּה, אָז כָּתוּב: וַיֶּאְסֹר יוֹסֵף מֶרְכַּבְתּוֹ - זֶה הַצַּדִּיק. וַיַּעַל לִקְרַאת יִשְׂרָאֵל אָבִיו גֹּשְׁנָה. לִקְרַאת יִשְׂרָאֵל - זֶה הַסּוֹד שֶׁל אָדָם. גֹּשְׁנָה - הִתְקָרְבוּת אַחַת, לְהִתְקָרֵב יַחַד בְּקָרְבָּן אֶחָד וְיִחוּד אֶחָד."],[11,"","וַיֵּרָא אֵלָיו - שֶׁכְּשֶׁנִּרְאֶה הַשֶּׁמֶשׁ עִם הַלְּבָנָה, אָז מְאִירָה הַלְּבָנָה, וּמְאִירָה לְכֻלָּם שֶׁלְּמַטָּה. וְכֵן כְּמוֹ זֶה, כָּל זְמַן שֶׁהַקְּדֻשָּׁה שֶׁלְּמַעְלָה שׁוֹרָה עַל הַמִּקְדָּשׁ שֶׁלְּמַטָּה, מֵאִיר בֵּית הַמִּקְדָּשׁ וְעוֹמֵד בִּשְׁלֵמוּתוֹ. וּכְשֶׁמִּסְתַּלֵּק מִמֶּנּוּ וְנֶחֱרָב בֵּית הַמִּקְדָּשׁ, אָז וַיֵּבְךָּ עַל צַוָּארָיו עוֹד, שֶׁכֻּלָּם בָּכוּ עַל הַמִּקְדָּשׁ שֶׁנֶּחֱרָב. עוֹד, מַה זֶּה עוֹד? זוֹ הַגָּלוּת הָאַחֲרוֹנָה."],[12,"","אָז כֵּיוָן שֶׁרָאָה יַעֲקֹב וְהִסְתַּכֵּל שֶׁהִנֵּה הַתִּקּוּן שֶׁלְּמַטָּה נִתְקַן כְּמוֹ שֶׁלְּמַעְלָה, אָז אָמַר אָמוּתָה הַפָּעַם וְגוֹ'. כִּי עוֹדְךְ חָי, שֶׁהִתְקַיַּמְתָּ בַּסּוֹד שֶׁל הַבְּרִית הַקָּדוֹשׁ שֶׁנִּקְרָא חַי הָעוֹלָמִים, וּמִשּׁוּם כָּךְ כִּי עוֹדְךְ חָי. וְעַל כֵּן בָּרִאשׁוֹנָה אָמַר, רַב עוֹד יוֹסֵף בְּנִי חָי, שֶׁצָּרִיךְ לַעֲמֹד בַּסּוֹד שֶׁל חַי, וְהִנֵּה נִתְבָּאֵר."]]],[["תָּא חֲזֵי, מַה כְּתִיב, וַיְבָרֶךְ יַעֲקֹב אֶת פַּרְעֹה, אָמַר רִבִּי יוֹסֵי, פַּרְעֹה אַף עַל גַּב דְּאוּקְמוּהָ בְּרָזָא אוֹחֲרָא, סֶמֶךְ דְּקָא סַמְכִינָן בְּעַלְמָא.","אֲבָל תָּא חֲזֵי, (שיר השירים א׳:ט׳) לְסוּסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעֲיָתִי, תָּא חֲזֵי, אִית רְתִיכִין לִשְׂמָאלָא בְּרָזָא דְסִטְרָא אָחֳרָא, וְאִית רְתִיכִין לִימִינָא בְּרָזָא דִלְעֵילָא דִקְדּוּשָּׁה, וְאִלֵּין לָקֳבֵל אִלֵּין. אִלֵּין דְּרַחֲמֵי וְאִלֵּין דְּדִינָא.","וְכַד קוּדְשָׁא בְּרִיךְ הוּא עָבַד דִּינָא בְּמִצְרָאֵי, כָּל דִּינָא דְּעָבִיד, כְּהַהוּא גַוְונָא דְּאִינוּן רְתִיכִין מַמָּשׁ, וּכְגַוְונָא דִילֵיהּ דְּהַהוּא סִטְרָא מַמָּשׁ. מַה הַהוּא סִטְרָא (ממש) קָטִיל וְאַפִּיק נִשְׁמָתִין, אוּף קוּדְשָׁא בְּרִיךְ הוּא עָבִיד בְּהַהוּא גַוְונָא מַמָּשׁ. דִּכְתִיב, (שמות י״ג:ט״ו) וַיַּהֲרֹג ה' כָּל בְּכוֹר, וְכֵן כֹּלָּא בְּמִצְרַיִם, בְּהַהוּא גַוְונָא מַמָּשׁ. וּבְגִין כָּךְ דִּמִיתִיךְ רַעֲיָתִי, כְּגַוְונָא דִילָהּ מַמָּשׁ לְקָטְלָא. דִּכְתִיב, כִּי אֲנִי ה' אֲנִי הוּא וְלא אַחֵר. וּלְזִמְנָא דְאָתֵי מַה כְּתִיב, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגו'.","תָּא חֲזֵי, מַה כְּתִיב, וַיֵּשֶׁב יִשְׂרָאֵל בְּאֶרֶץ מִצְרַיִם בְּאֶרֶץ גּוֹשֶׁן וַיֵּאָחֲזוּ בָהּ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד. וַיֵּאָחֲזוּ בָהּ, אַחְסָנַת עָלְמִין. וְיֵּאָחֲזוּ בָּהּ, דְּהָא לְהוֹן אִתְחֲזֵי, כְּמָה דְאוּקְמוּהָ. (ד\"א ל\"ג אמר רבי יוסי) וַיִּפְרוּ וַיִּרְבּוּ מְאֹד, ודַּאי, דְּהָא צַעֲרָא לָא שָׁרַאת בְּהוּ, וְקָיְימֵי בְּתַפְנוּקֵי עַלְמָא, וּבְגִין כָּךְ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן:"],[[0,"תא חזי מה כתיב וכו':","בוא וראה, מה כתוב, ויברך יעקב את פרעה. אמר ר' יוסי, פרעה, אע\"פ שבארוהו בסוד אחר, דהיינו שאינו קליפה רעה אלא הוא בחינת אמא דאצילות, (כמ\"ש לעיל אות ק\"ד בביאור הכתוב והקול נשמע בית פרעה) סמך הוא שאנו סומכים כדרכו, בדרוש, אמנם לפי הפשט הוא קליפה רעה."],[1,"אבל תא חזי וכו':","אבל בוא וראה, לסוסתי ברכבי פרעה וגו'. בא וראה, יש מרכבות לשמאל בסוד הסטרא אחרא, ויש מרכבות לימין, בסוד שלמעלה בקדושה, ואלו לעומת אלו, אלו של הקדושה הן של רחמים, ואלו של הס\"א, הן של דין."],[2,"וכד קב\"ה עביד וכו':","וכאשר עשה הקב\"ה דין במצרים, כל דין שעשה, היה ממש באותו הדרך של אלו המרכבות של הס\"א, ובאותו אופן של אותו הצד ממש, מה צד ההוא הורג ומוציא נשמות, אף הקב\"ה עשה באותו אופן ממש, שכתוב, ויהרג ה' כל בכור, אע\"פ שדרכו הוא רחמים כנ\"ל, וכן הכל מה שעשה במצרים, היה באותו אופן ממש, ומשום זה כתוב, \u0003דמיתיך רעיתי,\u0004 כי נדמתה כרכבי פרעה להרג ולהוציא נשמות בני אדם, כדרך שלה ממש, של מרכבות פרעה שהוא הס\"א, להרג, שכתוב, (שמות ט\"ו י\"ח) \u0003כי אני ה',\u0004 אני הוא ולא אחר. ולעתיד לבא מה כתוב, מי זה בא מאדום חמוץ בגדים מבצרה וגו'. שגם אז יהרג אותם ה', ולא שליח."],[3,"תא חזי מה וכו':","בוא וראה, מה כתוב, וישב ישראל בארץ מצרים בארץ גושן וגו'. \u0003ויאחזו בה,\u0004 פירושו אחוזת עולם. \u0003ויאחזו בה,\u0004 כי להם ראוי לאחז בה ולא למצרים, כמו שבארוהו. \u0003ויפרו וירבו מאד,\u0004 כי ודאי, שלא היה להם צער ונמצאו בתפנוקי מלכים, כל עוד שהשבטים היו בחיים, ומשום זה ויפרו וירבו מאד. בילא\"ו."]],[[0,"","בֹּא רְאֵה מַה כָּתוּב, וַיְבָרֶךְ יַעֲקֹב אֶת פַּרְעֹה. אָמַר רַבִּי יוֹסֵי, פַּרְעֹה, אַף עַל גַּב שֶׁבֵּאֲרוּהוּ בְּסוֹד אַחֵר, סֶמֶךְ שֶׁסּוֹמְכִים בָּעוֹלָם."],[1,"","אֲבָל בֹּא רְאֵה, (שיר א) לְסֻסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעְיָתִי. בֹּא רְאֵה, יֵשׁ מֶרְכָּבוֹת לִשְׂמֹאל בַּסּוֹד שֶׁל הַצַּד הָאַחֵר, וְיֵשׁ מֶרְכָּבוֹת לְיָמִין בַּסּוֹד שֶׁל לְמַעְלָה שֶׁל קְדֻשָּׁה, וְאֵלֶּה כְּנֶגֶד אֵלֶּה. אֵלֶּה שֶׁל רַחֲמִים, וְאֵלֶּה שֶׁל דִּין."],[2,"","וּכְשֶׁהַקָּדוֹשׁ בָּרוּךָ הוּא עָשָׂה דִין בְּמִצְרַיִם, כָּל הַדִּין שֶׁעָשָׂה, בְּאוֹתָהּ צוּרָה, שֶׁהֵם הַמֶּרְכָּבוֹת מַמָּשׁ, וּכְמוֹ שֶׁל אוֹתוֹ הַצַּד מַמָּשׁ. מָה אוֹתוֹ הַצַּד (ממש) הוֹרֵג וּמוֹצִיא נְשָׁמוֹת, כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה כְּאוֹתָהּ צוּרָה מַמָּשׁ, שֶׁכָּתוּב (שמות יג) וַיַּהֲרֹג ה' כָּל בְּכוֹר, וְכֵן בְּכָל מִצְרַיִם בְּאוֹתָהּ צוּרָה מַמָּשׁ. וּמִשּׁוּם כָּךְ דִּמִּיתִיךְ רַעְיָתִי, כְּמוֹ שֶׁלָּהּ מַמָּשׁ לַהֲרֹג, שֶׁכָּתוּב כִּי אֲנִי ה' אֲנִי הוּא וְלֹא אַחֵר. וְלֶעָתִיד לָבא מַה כָּתוּב? (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ'"],[3,"","בֹּא רְאֵה מַה כָּתוּב. וַיֵּשֶׁב יִשְׂרָאֵל בְּאֶרֶץ מִצְרַיִם בְּאֶרֶץ גֹּשֶׁן וַיֵּאָחֲזוּ בָהּ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד. וַיֵּאָחֲזוּ בָהּ - יְרֻשַּׁת עוֹלָמִים. וַיֵּאָחֲזוּ בָהּ - שֶׁהֲרֵי לָהֶם רְאוּיָה, כְּמוֹ שֶׁבֵּאֲרוּהָ. (אמר רבי יוסי) וַיִּפְרוּ וַיִּרְבּוּ מְאֹד, וַדַּאי, שֶׁהֲרֵי הַצַּעַר לֹא שָׁרָה בָהֶם וְעָמְדוּ בְּתַפְנוּקֵי הָעוֹלָם, וּמִשּׁוּם כָּךְ וַיִּפְרוּ וַיִּרְבּוּ מְאֹד. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
